import type { T } from './lang';

// Every rule of The Racing Rules of Sailing 2025–2028 (with World Sailing's changes and corrections to 20 April 2026),
// for /rulebook: each in a sentence or a few of our own words, in the book's order. A summary to find your way
// by, not the official text, which is World Sailing's (RULEBOOK_SOURCE); the page says so.
export const RULEBOOK_DATE = '2026-11-18';
export const RULEBOOK_SOURCE = 'https://www.sailing.org/racingrules';

export type PartId = 'definitions' | 'principles' | 'part-1' | 'part-2' | 'part-3' | 'part-4' | 'part-5' | 'part-6' | 'part-7' | 'appendices' | 'signals';
export type RuleEntry = { id: string; no?: string; title: string; text: string; see?: string };
export type RuleSection = { id?: string; title?: string; intro?: string; entries: RuleEntry[] };
export type RulePart = { id: PartId; chip: string; title: string; intro: string; sections: RuleSection[] };

type Pair = [en: string, ru: string, es?: string, de?: string, tr?: string];

export const entriesOf = (p: RulePart) => p.sections.flatMap((s) => s.entries);
// the numbered rules of Parts 1 to 7, a rule told in parts (18.1 to 18.4) counted once
export const ruleCount = (parts: RulePart[]) => new Set(parts.filter((p) => p.id.startsWith('part-')).flatMap(entriesOf).map((e) => e.no!.split('.')[0])).size;

export function rulebook(t: T): RulePart[] {
  const def = (id: string, title: Pair, text: Pair): RuleEntry => ({ id: `def-${id}`, title: t(...title), text: t(...text) });
  const rule = (no: string, title: Pair, text: Pair, see?: string): RuleEntry => ({ id: `rule-${no.replace('.', '-')}`, no, title: t(...title), text: t(...text), see });
  const app = (no: string, title: Pair, text: Pair): RuleEntry => ({ id: `appendix-${no.toLowerCase()}`, no, title: t(...title), text: t(...text) });
  const sig = (id: string, no: string, title: Pair, text: Pair): RuleEntry => ({ id: `signal-${id}`, no: no || undefined, title: t(...title), text: t(...text) });
  const sec = (id: string, title: Pair, intro: Pair | null, entries: RuleEntry[]): RuleSection => ({ id, title: t(...title), intro: intro ? t(...intro) : undefined, entries });

  return [
    { id: 'definitions', chip: t('Definitions', 'Определения', 'Definiciones', 'Begriffsbestimmungen', 'Tanımlar'), title: t('Definitions', 'Определения', 'Definiciones', 'Begriffsbestimmungen', 'Tanımlar'),
      intro: t('The words the rules use in an exact sense. Most arguments on the water come down to one of these.', 'Слова, которые правила понимают в точном смысле. Большинство споров на воде сводится к одному из них.', 'Las palabras que las reglas usan en un sentido exacto. La mayoría de las discusiones en el agua se reducen a una de estas.', 'Die Wörter, die die Regeln in einem genauen Sinn verwenden. Die meisten Streitigkeiten auf dem Wasser laufen auf eines davon hinaus.', 'Kuralların kesin bir anlamda kullandığı sözcükler. Suda yaşanan tartışmaların çoğu bunlardan birine dayanır.'),
      sections: [{ entries: [
        def('abandon', ['Abandon', 'Прекращение гонки', 'Abandonar', 'Abbrechen', 'İptal'], ['A race abandoned by the race committee or the protest committee doesn’t count. It may be sailed again.', 'Гонка, прекращённая гоночным или протестовым комитетом, не считается. Её можно провести заново.', 'Una regata abandonada por el comité de regatas o el comité de protestas no cuenta. Puede volver a navegarse.', 'Eine von der Wettfahrtleitung oder vom Protestkomitee abgebrochene Wettfahrt zählt nicht. Sie kann neu gesegelt werden.', 'Yarış komitesi ya da protesto komitesi tarafından iptal edilen bir yarış sayılmaz. Yeniden yapılabilir.']),
        def('overlap', ['Clear astern, clear ahead, overlap', 'Чисто позади, чисто впереди, связанность', 'Libre por la popa, libre por la proa, compromiso', 'Klar achteraus, klar voraus, Überlappung', 'Açık arkada, açık önde, bindirme'], ['A boat is clear astern when her hull and equipment in normal position are behind a line square across the aftermost point of the other boat, which is clear ahead. If neither is clear astern they overlap, and a boat between two others can link them. On opposite tacks these words apply only when rule 18 applies between the boats or both are sailing more than 90° from the true wind.', 'Лодка чисто позади, когда её корпус и снаряжение в обычном положении находятся за линией, проведённой поперёк через самую кормовую точку другой лодки; та — чисто впереди. Если ни одна не чисто позади, они связаны, а лодка между двумя другими может связать их. На разных галсах эти слова действуют, только если между лодками применяется правило 18 или обе идут дальше 90° от истинного ветра.', 'Un barco está libre por la popa cuando su casco y equipo en posición normal están detrás de una línea perpendicular que pasa por el punto más a popa del otro barco, que está libre por la proa. Si ninguno está libre por la popa, tienen compromiso, y un barco entre otros dos puede enlazarlos. En amuras opuestas estos términos se aplican solo cuando la regla 18 se aplica entre los barcos o ambos navegan a más de 90° del viento verdadero.', 'Ein Boot ist klar achteraus, wenn sein Rumpf und seine Ausrüstung in normaler Stellung hinter einer Linie rechtwinklig durch den achtersten Punkt des anderen Bootes liegen, das klar voraus ist. Ist keines klar achteraus, überlappen sie, und ein Boot zwischen zwei anderen kann sie verbinden. Auf entgegengesetzten Bugen gelten diese Begriffe nur, wenn Regel 18 zwischen den Booten gilt oder beide mehr als 90° vom wahren Wind segeln.', 'Bir tekne, gövdesi ve normal konumdaki donanımı, açık önde olan öteki teknenin en arka noktasından geçen dik bir çizginin gerisindeyse açık arkadadır. İkisi de açık arkada değilse bindirmelidirler ve iki teknenin arasındaki bir tekne onları birbirine bağlayabilir. Zıt kontralarda bu sözcükler yalnızca kural 18 tekneler arasında geçerliyse ya da ikisi de gerçek rüzgârdan 90°’den fazla yelken açıyorsa uygulanır.']),
        def('committee', ['Committee', 'Комитет', 'Comité', 'Komitee', 'Komite'], ['The protest committee, the race committee or the technical committee.', 'Протестовый, гоночный или технический комитет.', 'El comité de protestas, el comité de regatas o el comité técnico.', 'Das Protestkomitee, die Wettfahrtleitung oder das technische Komitee.', 'Protesto komitesi, yarış komitesi ya da teknik komite.']),
        def('conflict', ['Conflict of interest', 'Конфликт интересов', 'Conflicto de intereses', 'Interessenkonflikt', 'Çıkar çatışması'], ['A person has one if they could gain or lose by a decision they help to make, could reasonably seem to have a personal or financial stake that affects their impartiality, or have a close personal interest in the decision.', 'Он есть у человека, который может выиграть или проиграть от решения, в котором участвует, может обоснованно казаться лично или финансово заинтересованным либо имеет к решению близкий личный интерес.', 'Lo tiene una persona que podría ganar o perder con una decisión en la que participa, que podría parecer razonablemente tener un interés personal o económico que afecte a su imparcialidad, o que tiene un interés personal cercano en la decisión.', 'Eine Person hat einen, wenn sie durch eine Entscheidung, an der sie mitwirkt, gewinnen oder verlieren könnte, vernünftigerweise ein persönliches oder finanzielles Interesse zu haben scheinen könnte, das ihre Unparteilichkeit beeinträchtigt, oder ein enges persönliches Interesse an der Entscheidung hat.', 'Bir kişi, alınmasına katkıda bulunduğu bir karardan kazanç ya da kayıp sağlayabilecekse, tarafsızlığını etkileyen kişisel ya da mali bir çıkarı makul olarak varmış gibi görünüyorsa ya da kararda yakın bir kişisel çıkarı varsa çıkar çatışması vardır.']),
        def('continuing', ['Continuing obstruction', 'Протяжённое препятствие', 'Obstáculo continuo', 'Fortdauerndes Hindernis', 'Sürekli engel'], ['An obstruction the boat with the shortest hull involved will sail alongside for at least three of her hull lengths. A vessel under way, a boat racing and a committee boat that is also a mark are never one.', 'Препятствие, вдоль которого лодка с самым коротким корпусом из участвующих пройдёт не меньше трёх своих корпусов. Судно на ходу, лодка в гонке и судно комитета, служащее знаком, такими не бывают.', 'Un obstáculo junto al que el barco de casco más corto implicado navegará al menos tres esloras suyas. Un buque en navegación, un barco en regata y un barco del comité que también es baliza nunca lo son.', 'Ein Hindernis, an dem das Boot mit dem kürzesten beteiligten Rumpf mindestens drei seiner Rumpflängen entlangsegeln wird. Ein fahrendes Fahrzeug, ein Boot in der Wettfahrt und ein Komiteeboot, das zugleich Bahnmarke ist, sind nie eines.', 'İlgili en kısa gövdeli teknenin, en az üç tekne boyu boyunca yanından yelken açacağı bir engel. Seyir halindeki bir araç, yarışan bir tekne ve aynı zamanda şamandıra olan bir komite teknesi hiçbir zaman sürekli engel değildir.']),
        def('fetching', ['Fetching', 'Лежать на знак', 'Aproar', 'Anliegen', 'Yetişme'], ['A boat is fetching a mark when she can pass to windward of it and leave it on the required side without changing tack.', 'Лодка лежит на знак, когда может пройти его с наветра и оставить с нужной стороны, не меняя галса.', 'Un barco aproa una baliza cuando puede pasar a barlovento de ella y dejarla por el lado requerido sin cambiar de amura.', 'Ein Boot liegt eine Bahnmarke an, wenn es sie in Luv passieren und auf der vorgeschriebenen Seite lassen kann, ohne den Bug zu wechseln.', 'Bir tekne, bir şamandırayı rüzgârüstünden geçip istenen tarafta bırakabiliyorsa, tramola atmadan o şamandıraya yetişiyordur.']),
        def('finish', ['Finish', 'Финиш', 'Llegada', 'Ziel', 'Bitiş'], ['A boat finishes when, after her starting signal, any part of her hull crosses the finishing line from the course side. She hasn’t finished if she then takes a penalty turn, corrects a mistake made at the line or sails on with the course. She need not cross the line completely.', 'Лодка финиширует, когда после своего стартового сигнала любая часть её корпуса пересекает финишную линию со стороны дистанции. Она не финишировала, если затем выполняет штрафной оборот, исправляет ошибку, сделанную на линии, или продолжает проходить дистанцию. Пересекать линию полностью не обязательно.', 'Un barco llega cuando, tras su señal de salida, cualquier parte de su casco cruza la línea de llegada desde el lado del recorrido. No ha llegado si después cumple un giro de penalización, corrige un error cometido en la línea o sigue navegando el recorrido. No necesita cruzar la línea por completo.', 'Ein Boot kommt ins Ziel, wenn nach seinem Startsignal irgendein Teil seines Rumpfes die Ziellinie von der Bahnseite aus kreuzt. Es ist nicht ins Ziel gekommen, wenn es danach einen Strafkringel nimmt, einen Fehler an der Linie korrigiert oder mit der Bahn weitersegelt. Es muss die Linie nicht vollständig kreuzen.', 'Bir tekne, start işaretinden sonra gövdesinin herhangi bir kısmı bitiş hattını parkur tarafından geçtiğinde bitirir. Sonra bir ceza dönüşü alırsa, hatta yaptığı bir hatayı düzeltirse ya da parkurla birlikte yelken açmaya devam ederse bitirmemiş sayılır. Hattı tamamen geçmesi gerekmez.']),
        def('keep-clear', ['Keep clear', 'Уступать', 'Mantenerse separado', 'Sich freihalten', 'Uzak durmak'], ['A boat keeps clear when the right-of-way boat can sail her course with no need to take avoiding action and, if they are overlapped, can also change course either way without touching her at once.', 'Лодка уступает, когда лодка с правом дороги может идти своим курсом, ничего не предпринимая, чтобы её избежать, а если они связаны — ещё и менять курс в обе стороны без немедленного касания.', 'Un barco se mantiene separado cuando el barco con derecho de paso puede navegar su rumbo sin necesidad de maniobrar para evitarlo y, si tienen compromiso, también puede cambiar de rumbo hacia cualquier lado sin tocarlo de inmediato.', 'Ein Boot hält sich frei, wenn das Boot mit Wegerecht seinen Kurs segeln kann, ohne ausweichen zu müssen, und, falls sie überlappen, auch in beide Richtungen den Kurs ändern kann, ohne es sofort zu berühren.', 'Geçiş hakkı olan tekne, kaçınma hareketi yapmak zorunda kalmadan rotasında yelken açabiliyorsa ve bindirmeliyseler ona hemen dokunmadan iki yöne de rota değiştirebiliyorsa, bir tekne uzak durmuş olur.']),
        def('leeward', ['Leeward and windward', 'Подветренная и наветренная', 'Sotavento y barlovento', 'Lee und Luv', 'Rüzgâraltı ve rüzgârüstü'], ['The leeward side is the side away from the wind; sailing by the lee or dead downwind, it is the side the mainsail lies on. Of two overlapped boats on the same tack, the one on the other’s leeward side is the leeward boat and the other the windward boat.', 'Подветренный борт — тот, что дальше от ветра; при ходе с ветром с подветренного борта или прямо по ветру — тот, на котором лежит грот. Из двух связанных лодок на одном галсе та, что с подветренного борта другой, — подветренная, другая — наветренная.', 'El lado de sotavento es el lado opuesto al viento; navegando por la contra o en popa total, es el lado en que cae la mayor. De dos barcos con compromiso en la misma amura, el que está al lado de sotavento del otro es el barco de sotavento y el otro el de barlovento.', 'Die Leeseite ist die vom Wind abgewandte Seite; beim Segeln by the lee oder genau vor dem Wind ist es die Seite, auf der das Großsegel liegt. Von zwei überlappenden Booten auf demselben Bug ist das auf der Leeseite des anderen das Leeboot und das andere das Luvboot.', 'Rüzgâraltı taraf, rüzgârdan uzak olan taraftır; rüzgârın tersine ya da tam pupa yelken açarken ana yelkenin yattığı taraftır. Aynı kontradaki bindirmeli iki tekneden, ötekinin rüzgâraltı tarafında olan rüzgâraltı tekne, diğeri rüzgârüstü teknedir.']),
        def('mark', ['Mark', 'Знак', 'Baliza', 'Bahnmarke', 'Şamandıra'], ['An object the sailing instructions say to leave on a given side, a race committee vessel in navigable water at the end of the starting or finishing line, and anything deliberately attached to them. The anchor line is not part of the mark.', 'Предмет, который гоночная инструкция велит оставить с определённой стороны, судно гоночного комитета на судоходной воде, от которого идёт стартовая или финишная линия, и всё, что к ним намеренно прикреплено. Якорный конец частью знака не считается.', 'Un objeto que las instrucciones de regata dicen dejar por un lado determinado, una embarcación del comité de regatas en aguas navegables en el extremo de la línea de salida o de llegada, y todo lo que esté unido a ellos deliberadamente. El cabo del ancla no forma parte de la baliza.', 'Ein Gegenstand, den die Segelanweisungen auf einer bestimmten Seite zu lassen vorschreiben, ein Wettfahrtleitungsfahrzeug in schiffbarem Wasser am Ende der Start- oder Ziellinie und alles, was absichtlich daran befestigt ist. Die Ankerleine gehört nicht zur Bahnmarke.', 'Yarış talimatının belirli bir tarafta bırakılmasını söylediği bir nesne, start ya da bitiş hattının ucunda seyre elverişli suda duran bir yarış komitesi aracı ve onlara kasıtlı olarak bağlı her şey. Çapa halatı şamandıranın parçası değildir.']),
        def('mark-room', ['Mark-room', 'Место у знака', 'Espacio en baliza', 'Bahnmarkenraum', 'Şamandıra alanı'], ['Room for a boat to sail to the mark when her proper course takes her close to it, to round or pass it on the required side, and to leave it astern.', 'Место, чтобы подойти к знаку, когда надлежащий курс ведёт близко к нему, обогнуть или пройти его с нужной стороны и оставить за кормой.', 'Espacio para que un barco navegue hasta la baliza cuando su rumbo debido lo lleva cerca de ella, para redondearla o pasarla por el lado requerido y para dejarla por la popa.', 'Raum für ein Boot, zur Bahnmarke zu segeln, wenn sein richtiger Kurs es nah daran führt, sie auf der vorgeschriebenen Seite zu runden oder zu passieren und sie achteraus zu lassen.', 'Bir teknenin, uygun rotası onu şamandıraya yakın götürdüğünde şamandıraya yelken açması, gereken tarafta dönmesi ya da geçmesi ve onu kıçında bırakması için alan.']),
        def('obstruction', ['Obstruction', 'Препятствие', 'Obstáculo', 'Hindernis', 'Engel'], ['An object a boat could not pass without changing course substantially if she were one hull length away and heading straight at it, an object that is safe to pass on one side only, or an object, area or line a rule names as one. A boat racing is an obstruction only to boats that must keep clear of her or, under rule 22, avoid her.', 'Предмет, который лодка не смогла бы пройти без существенного изменения курса, идя прямо на него в одном корпусе от него; предмет, который безопасно обойти только с одной стороны; либо предмет, район или линия, названные препятствием в правиле. Лодка в гонке — препятствие только для тех, кто должен ей уступать или, по правилу 22, избегать её.', 'Un objeto que un barco no podría pasar sin cambiar sustancialmente de rumbo si estuviera a una eslora y fuera directo hacia él, un objeto que solo es seguro pasar por un lado, o un objeto, zona o línea que una regla nombra como tal. Un barco en regata es un obstáculo solo para los barcos que deben mantenerse separados de él o, según la regla 22, evitarlo.', 'Ein Gegenstand, den ein Boot nicht passieren könnte, ohne den Kurs deutlich zu ändern, wenn es eine Rumpflänge entfernt wäre und direkt darauf zuhielte, ein Gegenstand, der nur auf einer Seite sicher zu passieren ist, oder ein Gegenstand, Bereich oder eine Linie, den eine Regel als eines benennt. Ein Boot in der Wettfahrt ist nur für Boote ein Hindernis, die sich von ihm freihalten oder ihr nach Regel 22 ausweichen müssen.', 'Bir teknenin, bir tekne boyu uzaktan doğrudan ona yönelmişken rotasını büyük ölçüde değiştirmeden geçemeyeceği bir nesne, yalnızca bir yandan geçilmesi güvenli olan bir nesne ya da bir kuralın engel diye adlandırdığı bir nesne, alan ya da çizgi. Yarışan bir tekne yalnızca ondan uzak durması gereken ya da kural 22 uyarınca ondan kaçınması gereken tekneler için engeldir.']),
        def('party', ['Party', 'Сторона', 'Parte', 'Partei', 'Taraf'], ['Those a hearing is about: the protestor and the protestee, a boat seeking redress, the committee or body whose action is questioned, a person accused of misconduct, and a support person being heard. The protest committee is never a party.', 'Те, кого касается рассмотрение: протестующий и опротестованный, лодка, просящая исправить результат, комитет или орган, чьи действия под вопросом, человек, обвинённый в проступке, и сопровождающее лицо, чьё дело рассматривается. Протестовый комитет стороной не бывает.', 'Aquellos sobre quienes trata una audiencia: el protestante y el protestado, un barco que solicita reparación, el comité u órgano cuya actuación se cuestiona, una persona acusada de mala conducta y una persona de apoyo que es oída. El comité de protestas nunca es parte.', 'Die, um die es in einer Verhandlung geht: der Protestierende und der Protestierte, ein Boot, das Wiedergutmachung verlangt, das Komitee oder die Stelle, deren Handlung angezweifelt wird, eine Person, der Fehlverhalten vorgeworfen wird, und eine Betreuungsperson, die angehört wird. Das Protestkomitee ist nie Partei.', 'Bir duruşmanın ilgilendirdiği kişiler: protesto eden ve protesto edilen, telafi arayan tekne, eylemi sorgulanan komite ya da kurum, görgü kuralına aykırı davranmakla suçlanan kişi ve dinlenen bir destek kişisi. Protesto komitesi hiçbir zaman taraf değildir.']),
        def('postpone', ['Postpone', 'Откладывание', 'Aplazar', 'Verschieben', 'Erteleme'], ['A postponed race is delayed before its scheduled start. It may start later or be abandoned.', 'Отложенная гонка задерживается до назначенного старта. Её могут начать позже или прекратить.', 'Una regata aplazada se retrasa antes de su hora de salida prevista. Puede salir más tarde o ser abandonada.', 'Eine verschobene Wettfahrt wird vor ihrem geplanten Start verzögert. Sie kann später starten oder abgebrochen werden.', 'Ertelenen bir yarış, planlanan startından önce geciktirilir. Daha sonra start alabilir ya da iptal edilebilir.']),
        def('proper-course', ['Proper course', 'Надлежащий курс', 'Rumbo debido', 'Richtiger Kurs', 'Uygun rota'], ['The course a boat would choose to sail the course as quickly as possible if the other boats named in the rule weren’t there. Before her starting signal a boat has no proper course.', 'Курс, который лодка выбрала бы, чтобы пройти дистанцию как можно быстрее, если бы названных в правиле лодок не было. До своего стартового сигнала надлежащего курса у лодки нет.', 'El rumbo que un barco elegiría para navegar el recorrido lo más rápido posible si los otros barcos nombrados en la regla no estuvieran allí. Antes de su señal de salida un barco no tiene rumbo debido.', 'Der Kurs, den ein Boot wählen würde, um die Bahn so schnell wie möglich zu segeln, wenn die anderen in der Regel genannten Boote nicht da wären. Vor seinem Startsignal hat ein Boot keinen richtigen Kurs.', 'Kuralda adı geçen diğer tekneler orada olmasaydı, bir teknenin parkuru mümkün olan en hızlı şekilde yelken açmak için seçeceği rota. Start işaretinden önce bir teknenin uygun rotası yoktur.']),
        def('protest', ['Protest', 'Протест', 'Protesta', 'Protest', 'Protesto'], ['An allegation under rule 60, by a boat or a committee, that a boat has broken a rule.', 'Заявление лодки или комитета по правилу 60 о том, что лодка нарушила правило.', 'Una alegación, según la regla 60, de un barco o de un comité, de que un barco ha infringido una regla.', 'Eine Behauptung nach Regel 60 durch ein Boot oder ein Komitee, dass ein Boot eine Regel verletzt hat.', 'Bir teknenin ya da bir komitenin, bir teknenin bir kuralı çiğnediğine dair kural 60 uyarınca iddiası.']),
        def('racing', ['Racing', 'В гонке', 'En regata', 'In der Wettfahrt', 'Yarışmak'], ['A boat is racing from her preparatory signal until she has finished and cleared the finishing line and marks, or retired, or until the race committee signals a general recall, a postponement or an abandonment.', 'Лодка в гонке с подготовительного сигнала и до тех пор, пока не финишировала и не отошла от финишной линии и знаков, не вышла из гонки либо пока гоночный комитет не дал сигнал общего отзыва, откладывания или прекращения.', 'Un barco está en regata desde su señal preparatoria hasta que ha llegado y ha despejado la línea de llegada y las balizas, o se ha retirado, o hasta que el comité de regatas señala una llamada general, un aplazamiento o un abandono.', 'Ein Boot ist in der Wettfahrt von seinem Vorbereitungssignal an, bis es im Ziel ist und die Ziellinie und Bahnmarken geräumt hat, oder aufgegeben hat, oder bis die Wettfahrtleitung einen allgemeinen Rückruf, eine Verschiebung oder einen Abbruch signalisiert.', 'Bir tekne, hazırlık işaretinden itibaren, bitirip bitiş hattını ve şamandıraları temizleyene kadar, ya da çekilene kadar, ya da yarış komitesi genel geri çağırma, erteleme ya da iptal işareti verene kadar yarışır.']),
        def('room', ['Room', 'Место', 'Espacio', 'Raum', 'Alan'], ['The space a boat needs in the conditions at the time, manoeuvring promptly and in a seamanlike way, including the space to meet her duties under Part 2 and rule 31.', 'Пространство, нужное лодке в данных условиях при быстром и грамотном маневрировании, включая место, чтобы выполнить обязанности по части 2 и правилу 31.', 'El espacio que un barco necesita en las condiciones del momento, maniobrando con prontitud y de forma marinera, incluido el espacio para cumplir sus obligaciones de la Parte 2 y de la regla 31.', 'Der Platz, den ein Boot unter den zu diesem Zeitpunkt herrschenden Bedingungen braucht, wenn es zügig und seemännisch manövriert, einschließlich des Platzes, ihren Pflichten nach Teil 2 und Regel 31 nachzukommen.', 'Bir teknenin, o andaki koşullarda hemen ve denizcilik kurallarına uygun manevra yaparak ihtiyaç duyduğu alan; 2. Bölüm ve kural 31 uyarınca yükümlülüklerini yerine getirmek için gereken alan dahil.']),
        def('rule', ['Rule', 'Правило', 'Regla', 'Regel', 'Kural'], ['What binds a race: this book (but not the Basic Principles or the titles), World Sailing regulations with the status of a rule, national prescriptions, class rules, the notice of race, the sailing instructions and any other document governing the event.', 'То, что обязательно в гонке: эта книга (кроме основных принципов и заголовков), регламенты World Sailing со статусом правила, предписания национальной федерации, правила класса, положение о соревновании, гоночная инструкция и другие документы, регулирующие соревнование.', 'Lo que obliga en una regata: este libro (pero no los Principios Básicos ni los títulos), los reglamentos de World Sailing con categoría de regla, las prescripciones nacionales, las reglas de clase, el anuncio de regata, las instrucciones de regata y cualquier otro documento que rija el evento.', 'Was eine Wettfahrt bindet: dieses Buch (aber nicht die Grundprinzipien oder die Titel), Vorschriften von World Sailing mit dem Status einer Regel, nationale Vorschriften, Klassenvorschriften, die Ausschreibung, die Segelanweisungen und jedes andere die Veranstaltung regelnde Dokument.', 'Bir yarışı bağlayan şeyler: bu kitap (ama Temel İlkeler ya da başlıklar değil), kural statüsündeki World Sailing düzenlemeleri, ulusal ekler, sınıf kuralları, yarış duyurusu, yarış talimatı ve etkinliği yöneten diğer her belge.']),
        def('sail-the-course', ['Sail the course', 'Пройти дистанцию', 'Completar el recorrido', 'Die Bahn segeln', 'Parkuru yelken açmak'], ['A boat starts; a string following her track, pulled taut, passes each mark on the required side and in the right order, touches each rounding mark the sailing instructions name and goes through each gate from the direction of the previous mark; then she finishes.', 'Лодка стартует; нить, повторяющая её путь, если её натянуть, проходит каждый знак с нужной стороны и в нужном порядке, касается каждого знака огибания, названного в инструкции, и проходит ворота со стороны предыдущего знака; затем лодка финиширует.', 'Un barco sale; un cabo que siguiera su derrota, tensado, pasa cada baliza por el lado requerido y en el orden correcto, toca cada baliza de redondeo que nombran las instrucciones de regata y atraviesa cada puerta desde la dirección de la baliza anterior; luego llega.', 'Ein Boot startet; eine seiner Spur folgende, straff gezogene Leine passiert jede Bahnmarke auf der vorgeschriebenen Seite und in der richtigen Reihenfolge, berührt jede Rundungsmarke, die die Segelanweisungen nennen, und geht durch jedes Tor aus der Richtung der vorherigen Bahnmarke; dann kommt es ins Ziel.', 'Bir tekne start verir; izini izleyen, gerilmiş bir ip her şamandırayı gereken tarafta ve doğru sırada geçer, yarış talimatının adını verdiği her dönüş şamandırasına dokunur ve her kapıdan bir önceki şamandıranın yönünden geçer; sonra tekne bitirir.']),
        def('start', ['Start', 'Старт', 'Salida', 'Start', 'Start'], ['A boat starts when, with her hull wholly on the pre-start side at or after her starting signal and rule 30.1 met if it applies, any part of her hull crosses the starting line to the course side.', 'Лодка стартует, когда в момент своего стартового сигнала или позже её корпус целиком на предстартовой стороне, правило 30.1, если оно действует, выполнено, и любая часть корпуса пересекает стартовую линию в сторону дистанции.', 'Un barco sale cuando, con su casco totalmente en el lado de pre-salida en o después de su señal de salida y cumplida la regla 30.1 si se aplica, cualquier parte de su casco cruza la línea de salida hacia el lado del recorrido.', 'Ein Boot startet, wenn sein Rumpf bei oder nach seinem Startsignal ganz auf der Vorstartseite ist und Regel 30.1, falls sie gilt, erfüllt ist und irgendein Teil seines Rumpfes die Startlinie zur Bahnseite hin kreuzt.', 'Bir tekne, gövdesi tamamen start işaretinde ya da sonrasında start öncesi tarafta ve geçerliyse kural 30.1 sağlanmışken, gövdesinin herhangi bir kısmı start hattını parkur tarafına geçtiğinde start verir.']),
        def('support-person', ['Support person', 'Сопровождающее лицо', 'Persona de apoyo', 'Betreuungsperson', 'Destek kişisi'], ['Anyone who gives or may give a competitor physical or advisory support, such as a coach, trainer, manager or medic, and any competitor’s parent or guardian.', 'Любой, кто оказывает или может оказать гонщику физическую помощь или советы — тренер, менеджер, медик и другие, — а также родитель или опекун гонщика.', 'Cualquiera que da o puede dar a un regatista apoyo físico o de asesoramiento, como un entrenador, preparador, jefe de equipo o médico, y el padre, madre o tutor de cualquier regatista.', 'Jeder, der einem Teilnehmer körperliche oder beratende Unterstützung gibt oder geben kann, etwa Trainer, Manager oder Sanitäter, und jeder Elternteil oder Vormund eines Teilnehmers.', 'Bir yarışçıya fiziksel ya da danışmanlık desteği veren ya da verebilecek herkes, örneğin antrenör, eğitmen, menajer ya da sağlıkçı, ve her yarışçının ebeveyni ya da vasisi.']),
        def('tack', ['Tack, starboard or port', 'Галс, правый или левый', 'Amura, estribor o babor', 'Bug, Steuerbord oder Backbord', 'Kontra, sancak ya da iskele'], ['A boat is on the tack of her windward side: wind on her starboard side, starboard tack.', 'Галс лодки определяется её наветренным бортом: ветер в правый борт — правый галс.', 'Un barco está en la amura de su lado de barlovento: viento por su costado de estribor, amura de estribor.', 'Ein Boot liegt auf dem Bug seiner Luvseite: Wind auf seiner Steuerbordseite, Steuerbordbug.', 'Bir tekne, rüzgârüstü tarafının kontrasındadır: rüzgâr sancak tarafından geliyorsa sancak kontra.']),
        def('zone', ['Zone', 'Зона', 'Zona', 'Zone', 'Bölge'], ['The area around a mark within three hull lengths of the boat nearer to it. A boat is in the zone as soon as any part of her hull is.', 'Область вокруг знака в пределах трёх корпусов лодки, которая ближе к нему. Лодка в зоне, как только в неё вошла любая часть корпуса.', 'La zona alrededor de una baliza a menos de tres esloras del barco más cercano a ella. Un barco está en la zona en cuanto cualquier parte de su casco lo está.', 'Der Bereich um eine Bahnmarke innerhalb von drei Rumpflängen des ihr näheren Bootes. Ein Boot ist in der Zone, sobald irgendein Teil ihres Rumpfes es ist.', 'Bir şamandıranın çevresinde, ona daha yakın olan teknenin üç tekne boyu içindeki alan. Bir tekne gövdesinin herhangi bir kısmı içindeyse hemen bölgededir.']),
      ] }] },

    { id: 'principles', chip: t('Principles', 'Принципы', 'Principios', 'Grundsätze', 'İlkeler'), title: t('Basic principles', 'Основные принципы', 'Principios básicos', 'Grundprinzipien', 'Temel ilkeler'),
      intro: t('The two ideas the sport rests on. No event may change them.', 'Две идеи, на которых держится спорт. Ни одно соревнование не может их изменить.', 'Las dos ideas en que se apoya el deporte. Ningún evento puede cambiarlas.', 'Die zwei Ideen, auf denen der Sport ruht. Keine Veranstaltung darf sie ändern.', 'Sporun dayandığı iki fikir. Hiçbir etkinlik bunları değiştiremez.'),
      sections: [{ entries: [
        def('sportsmanship', ['Sportsmanship and the rules', 'Спортивное поведение и правила', 'Deportividad y las reglas', 'Sportgeist und die Regeln', 'Sporculuk ve kurallar'], ['Sailors are expected to follow the rules and enforce them. A boat that breaks a rule and isn’t exonerated promptly takes a penalty or other fitting action, which may be to retire.', 'Гонщики сами соблюдают правила и следят за их соблюдением. Лодка, нарушившая правило и не освобождённая от ответственности, сразу выполняет наказание или другое подходящее действие — вплоть до выхода из гонки.', 'Se espera que los regatistas cumplan las reglas y las hagan cumplir. Un barco que infringe una regla y no queda exonerado cumple sin demora una penalización u otra acción adecuada, que puede ser retirarse.', 'Von Seglern wird erwartet, dass sie die Regeln befolgen und durchsetzen. Ein Boot, das eine Regel verletzt und nicht entlastet ist, nimmt umgehend eine Strafe oder eine andere angemessene Maßnahme, was auch die Aufgabe sein kann.', 'Yelkencilerin kurallara uymaları ve onları uygulamaları beklenir. Bir kuralı çiğneyen ve çabucak aklanmayan tekne, çekilmek de olabilecek bir ceza ya da uygun başka bir işlem alır.']),
        def('environment', ['Environmental responsibility', 'Забота об окружающей среде', 'Responsabilidad medioambiental', 'Umweltverantwortung', 'Çevreye karşı sorumluluk'], ['Everyone taking part is encouraged to keep the sport’s harm to the environment as small as they can.', 'Всем участникам предлагается как можно меньше вредить окружающей среде.', 'Se anima a todos los participantes a reducir al mínimo el daño del deporte al medio ambiente.', 'Alle Teilnehmenden sollen die Umweltschäden durch den Segelsport so gering wie möglich halten.', 'Yarışa katılan herkes, sporun çevreye verdiği zararı olabildiğince küçük tutmaya teşvik edilir.']),
      ] }] },

    { id: 'part-1', chip: t('Part 1', 'Часть 1', 'Parte 1', 'Teil 1', 'Bölüm 1'), title: t('Part 1 · Fundamental rules', 'Часть 1 · Основополагающие правила', 'Parte 1 · Reglas fundamentales', 'Teil 1 · Grundregeln', 'Bölüm 1 · Temel kurallar'),
      intro: t('Safety, fair play and what you agree to by taking part.', 'Безопасность, честная борьба и то, на что вы соглашаетесь, выходя на старт.', 'Seguridad, juego limpio y lo que aceptas al participar.', 'Sicherheit, Fairness und das, was du mit der Teilnahme akzeptierst.', 'Güvenlik, adil oyun ve katılarak kabul ettiklerin.'),
      sections: [{ entries: [
        rule('1', ['Safety', 'Безопасность', 'Seguridad', 'Sicherheit', 'Güvenlik'], ['Give all possible help to any person or vessel in danger (1.1). Carry adequate life-saving equipment for everyone aboard, one item ready for immediate use, and each competitor is responsible for wearing a personal flotation device fit for the conditions (1.2).', 'Оказывайте всю возможную помощь любому человеку или судну в опасности (1.1). Имейте на борту достаточные спасательные средства на всех, одно из них — наготове; каждый гонщик сам отвечает за то, чтобы носить спасательный жилет, подходящий к условиям (1.2).', 'Presta toda la ayuda posible a cualquier persona o buque en peligro (1.1). Lleva equipo de salvamento adecuado para todos los que van a bordo, una pieza lista para uso inmediato, y cada regatista es responsable de llevar un dispositivo de flotación personal adecuado a las condiciones (1.2).', 'Leiste jeder Person oder jedem Fahrzeug in Gefahr jede mögliche Hilfe (1.1). Führe ausreichende Rettungsmittel für alle an Bord mit, eines davon sofort einsatzbereit, und jede Teilnehmerin und jeder Teilnehmer ist selbst dafür verantwortlich, eine für die Bedingungen geeignete Schwimmweste zu tragen (1.2).', 'Tehlikedeki her kişiye ya da tekneye elinden gelen her yardımı ver (1.1). Teknedeki herkes için yeterli can kurtarma donanımı bulundur, bir parçası hemen kullanılabilecek durumda olsun; her yarışçı, koşullara uygun bir can yeleği giymekten kendisi sorumludur (1.2).']),
        rule('2', ['Fair sailing', 'Честная гонка', 'Juego limpio', 'Faires Segeln', 'Adil yelken'], ['A boat and her owner compete by the recognised principles of sportsmanship and fair play. A boat is penalised under this rule only when a breach is clearly established, and the penalty is a disqualification she can’t discard.', 'Лодка и её владелец соревнуются по признанным принципам спортивного поведения и честной игры. Наказание по этому правилу возможно, только если нарушение ясно установлено, и это дисквалификация, которую нельзя исключить из зачёта.', 'Un barco y su armador compiten según los principios reconocidos de deportividad y juego limpio. Un barco es penalizado según esta regla solo cuando la infracción queda claramente establecida, y la penalización es una descalificación que no puede descartar.', 'Ein Boot und sein Eigner segeln nach den anerkannten Grundsätzen der Sportlichkeit und Fairness. Ein Boot wird nach dieser Regel nur bestraft, wenn ein Verstoß eindeutig feststeht, und die Strafe ist eine Disqualifikation, die es nicht streichen kann.', 'Bir tekne ve sahibi, sportmenlik ve adil oyunun kabul görmüş ilkelerine göre yarışır. Bir tekneye bu kuralın ihlalinden ceza ancak ihlal açıkça kanıtlandığında verilir; ceza, çıkarılamayan bir diskalifiyedir.']),
        rule('3', ['Decision to race', 'Решение участвовать в гонке', 'Decisión de regatear', 'Entscheidung zur Teilnahme', 'Yarışma kararı'], ['Whether to race, or to carry on racing, is the boat’s decision alone.', 'Участвовать ли в гонке и продолжать ли её — решение только самой лодки.', 'Participar en una regata, o seguir en ella, es decisión exclusiva del barco.', 'Ob ein Boot an einer Wettfahrt teilnimmt oder weiterfährt, entscheidet allein das Boot.', 'Yarışıp yarışmayacağına ya da yarışa devam edip etmeyeceğine yalnızca tekne karar verir.']),
        rule('4', ['Acceptance of the rules', 'Принятие правил', 'Aceptación de las reglas', 'Anerkennung der Regeln', 'Kuralların kabulü'], ['By taking part, competitors, owners and support persons accept the rules and the penalties given under them, subject to appeal, and agree not to take such a matter to a court or tribunal the rules don’t provide for. The person in charge makes sure the crew and the owner know this.', 'Участвуя, гонщики, владельцы и сопровождающие лица принимают правила и наказания по ним, с учётом права на апелляцию, и соглашаются не обращаться по этим вопросам в суды, не предусмотренные правилами. Ответственный на лодке следит, чтобы экипаж и владелец об этом знали.', 'Al participar, regatistas, armadores y personas de apoyo aceptan las reglas y las penalizaciones impuestas conforme a ellas, sujetas a apelación, y se comprometen a no llevar tal asunto a un tribunal que las reglas no prevean. La persona al mando se asegura de que la tripulación y el armador lo sepan.', 'Mit der Teilnahme erkennen Teilnehmer, Eigner und Betreuer die Regeln und die danach verhängten Strafen an, vorbehaltlich Berufung, und verpflichten sich, eine solche Angelegenheit nicht vor ein Gericht oder Tribunal zu bringen, das die Regeln nicht vorsehen. Die verantwortliche Person sorgt dafür, dass Crew und Eigner das wissen.', 'Yarışçılar, tekne sahipleri ve destek ekibi, katılarak kuralları ve bunlara göre verilen cezaları kabul eder (itiraz hakkı saklıdır) ve kuralların öngörmediği bir mahkemeye ya da kurula böyle bir konuyu götürmemeyi kabul eder. Sorumlu kişi, mürettebatın ve tekne sahibinin bunu bildiğinden emin olur.']),
        rule('5', ['Rules governing organizing authorities and officials', 'Правила для организаторов и судей', 'Reglas que rigen a las autoridades organizadoras y a los oficiales', 'Regeln für Veranstalter und Offizielle', 'Organizatör kurumları ve görevlileri bağlayan kurallar'], ['The organisers, the committees and the race officials are bound by the rules too, in how they run and judge the event.', 'Организаторы, комитеты и судьи тоже подчиняются правилам, проводя и судя соревнование.', 'Los organizadores, los comités y los oficiales de regata también están sujetos a las reglas, en cómo dirigen y juzgan el evento.', 'Auch die Veranstalter, die Komitees und die Wettfahrtoffiziellen sind an die Regeln gebunden, wenn sie die Veranstaltung durchführen und beurteilen.', 'Organizatörler, komiteler ve yarış görevlileri de yarışı yürütürken ve yargılarken kurallarla bağlıdır.']),
        rule('6', ['World Sailing regulations', 'Регламенты World Sailing', 'Reglamentos de World Sailing', 'Bestimmungen von World Sailing', 'World Sailing düzenlemeleri'], ['Competitors, owners and support persons follow the World Sailing codes that count as rules: Advertising, Anti-Doping, Ethics, Eligibility and Sailor Categorization. Part 5 applies to a breach of one only if that code allows protests.', 'Гонщики, владельцы и сопровождающие лица соблюдают кодексы World Sailing со статусом правил: о рекламе, антидопинговый, этический, о допуске и о категориях гонщиков. Часть 5 применяется к их нарушению, только если сам кодекс допускает протесты.', 'Los regatistas, propietarios y personas de apoyo cumplen los códigos de World Sailing que cuentan como reglas: Publicidad, Antidopaje, Ética, Elegibilidad y Categorización de Regatistas. La Parte 5 se aplica a una infracción de uno de ellos solo si ese código permite las protestas.', 'Teilnehmer, Eigner und Betreuer befolgen die Codes von World Sailing, die als Regeln gelten: Werbung, Anti-Doping, Ethik, Zulassung und Segler-Kategorisierung. Teil 5 gilt bei einem Verstoß gegen einen davon nur, wenn dieser Code Proteste zulässt.', 'Yarışçılar, tekne sahipleri ve destek ekibi, kural sayılan World Sailing kodlarına uyar: Reklam, Doping Karşıtlığı, Etik, Uygunluk ve Yelkenci Sınıflandırması. 5. Bölüm, bunlardan birinin ihlaline ancak o kod protestoya izin veriyorsa uygulanır.']),
      ] }] },

    { id: 'part-2', chip: t('Part 2', 'Часть 2', 'Parte 2', 'Teil 2', 'Bölüm 2'), title: t('Part 2 · When boats meet', 'Часть 2 · Когда лодки встречаются', 'Parte 2 · Cuando los barcos se encuentran', 'Teil 2 · Wenn Boote sich begegnen', 'Bölüm 2 · Tekneler karşılaştığında'),
      intro: t('These rules apply between boats sailing in or near the racing area that intend to race, are racing or have been racing. A boat not racing is penalised only for rule 14 when there is injury or serious damage, or for rule 23.1. Meeting a vessel that isn’t under these rules, a boat follows the collision regulations (IRPCAS) or the government’s right-of-way rules.', 'Эти правила действуют между лодками в районе гонки или рядом с ним, которые собираются гоняться, гоняются или уже гонялись. Лодку не в гонке наказывают только за правило 14, если есть травма или серьёзное повреждение, и за правило 23.1. Встречая судно, не идущее по этим правилам, лодка выполняет МППСС или государственные правила расхождения.', 'Estas reglas se aplican entre barcos que navegan en la zona de regata o cerca de ella y que tienen intención de regatear, están regateando o han estado regateando. Un barco que no está en regata solo es penalizado por la regla 14 cuando hay lesión o daño grave, o por la regla 23.1. Cuando se encuentra con un buque al que no se aplican estas reglas, el barco sigue el reglamento internacional para prevenir los abordajes (RIPA) o las reglas de derecho de paso del gobierno.', 'Diese Regeln gelten zwischen Booten, die im oder nahe beim Wettfahrtgebiet segeln und die Absicht haben, an der Wettfahrt teilzunehmen, in der Wettfahrt sind oder in der Wettfahrt waren. Ein Boot, das nicht in der Wettfahrt ist, wird nur nach Regel 14 bestraft, wenn es zu Verletzung oder ernsthaftem Schaden kommt, oder nach Regel 23.1. Begegnet ein Boot einem Fahrzeug, für das diese Regeln nicht gelten, befolgt es die Kollisionsverhütungsregeln (KVR/IRPCAS) oder die staatlichen Vorfahrtsregeln.', 'Bu kurallar, yarış alanında ya da yakınında seyreden ve yarışmayı düşünen, yarışan ya da yarışmış olan tekneler arasında geçerlidir. Yarışmayan bir tekneye ancak yaralanma veya ciddi hasar olduğunda kural 14’ten ya da kural 23.1’den ceza verilir. Bu kurallara tabi olmayan bir tekneyle karşılaşan tekne, denizde çatışmayı önleme tüzüğüne (IRPCAS) ya da devletin geçiş hakkı kurallarına uyar.'),
      sections: [
        sec('section-a', ['Section A · Right of way', 'Раздел A · Право дороги', 'Sección A · Derecho de paso', 'Abschnitt A · Wegerecht', 'A Kısmı · Geçiş hakkı'], ['A boat has right of way when the other must keep clear of her. Sections B, C and D limit what she may do with it.', 'Лодка имеет право дороги, когда другая должна ей уступать. Разделы B, C и D ограничивают её действия.', 'Un barco tiene derecho de paso cuando el otro debe mantenerse separado de él. Las secciones B, C y D limitan lo que puede hacer con ese derecho.', 'Ein Boot hat Wegerecht, wenn das andere sich freihalten muss. Die Abschnitte B, C und D begrenzen, was es damit tun darf.', 'Karşıdaki teknenin uzak durması gereken tekne geçiş hakkına sahiptir. B, C ve D kısımları, bu hakla neler yapabileceğini sınırlar.'], [
          rule('10', ['On opposite tacks', 'На разных галсах', 'En amuras opuestas', 'Auf entgegengesetzten Bugen', 'Zıt kontralarda'], ['A port-tack boat keeps clear of a starboard-tack boat.', 'Лодка левого галса уступает лодке правого галса.', 'Un barco en amura de babor se mantiene separado de un barco en amura de estribor.', 'Ein Boot auf Backbordbug hält sich von einem Boot auf Steuerbordbug frei.', 'İskele kontradaki tekne, sancak kontradaki tekneden uzak durur.'], '/learn/rules#r10'),
          rule('11', ['On the same tack, overlapped', 'На одном галсе, связаны', 'En la misma amura, con compromiso', 'Auf demselben Bug, überlappt', 'Aynı kontrada, bindirmeli'], ['A windward boat keeps clear of a leeward boat.', 'Наветренная лодка уступает подветренной.', 'Un barco de barlovento se mantiene separado de un barco de sotavento.', 'Ein Luvboot hält sich von einem Leeboot frei.', 'Rüzgârüstündeki tekne, rüzgâraltındaki tekneden uzak durur.'], '/learn/rules#r11'),
          rule('12', ['On the same tack, not overlapped', 'На одном галсе, не связаны', 'En la misma amura, sin compromiso', 'Auf demselben Bug, nicht überlappt', 'Aynı kontrada, bindirmesiz'], ['A boat clear astern keeps clear of a boat clear ahead.', 'Лодка чисто позади уступает лодке чисто впереди.', 'Un barco libre por la popa se mantiene separado de un barco libre por la proa.', 'Ein Boot, das klar achteraus ist, hält sich von einem Boot frei, das klar voraus ist.', 'Açık arkadaki tekne, açık öndeki tekneden uzak durur.'], '/learn/rules#r12'),
          rule('13', ['While tacking', 'Во время поворота оверштаг', 'Mientras vira por avante', 'Beim Wenden', 'Tramola atarken'], ['After passing head to wind a boat keeps clear of all others until she is on a close-hauled course, and rules 10, 11 and 12 don’t apply meanwhile. If two boats are tacking at once, the one on the other’s port side, or the one astern, keeps clear.', 'Пройдя положение левентик, лодка уступает всем, пока не ляжет на курс бейдевинд; правила 10, 11 и 12 в это время не действуют. Если поворачивают две лодки сразу, уступает та, что слева от другой, или та, что позади.', 'Después de pasar la proa al viento, un barco se mantiene separado de todos los demás hasta que está en rumbo de ceñida, y mientras tanto no se aplican las reglas 10, 11 y 12. Si dos barcos viran por avante a la vez, se mantiene separado el que está por la banda de babor del otro, o el que está por la popa.', 'Nachdem ein Boot durch den Wind gegangen ist, hält es sich von allen anderen frei, bis es auf einem Kurs hoch am Wind ist, und die Regeln 10, 11 und 12 gelten in der Zwischenzeit nicht. Wenden zwei Boote gleichzeitig, hält sich das Boot frei, das auf der Backbordseite des anderen ist, oder das, das achteraus ist.', 'Başı rüzgârdan geçtikten sonra bir tekne, orsa rotasına gelene kadar diğer tüm teknelerden uzak durur ve bu sürede kural 10, 11 ve 12 uygulanmaz. İki tekne aynı anda tramola atıyorsa, diğerinin iskele tarafındaki ya da arkadaki tekne uzak durur.'], '/learn/rules#r13'),
        ]),
        sec('section-b', ['Section B · General limitations', 'Раздел B · Общие ограничения', 'Sección B · Limitaciones generales', 'Abschnitt B · Allgemeine Einschränkungen', 'B Kısmı · Genel sınırlamalar'], null, [
          rule('14', ['Avoiding contact', 'Избежание контакта', 'Evitar el contacto', 'Berührung vermeiden', 'Temastan kaçınma'], ['If reasonably possible, a boat avoids contact with another boat and doesn’t cause contact between boats, or between a boat and an object that should be avoided. A right-of-way boat, or one within the room she is owed, need act only once it is clear the other isn’t keeping clear or giving room.', 'Если это разумно возможно, лодка избегает контакта с другой лодкой и не вызывает контакта между лодками или между лодкой и предметом, которого следует избегать. Лодка с правом дороги или идущая в пределах положенного ей места должна действовать, только когда ясно, что другая не уступает или не даёт места.', 'Si es razonablemente posible, un barco evita el contacto con otro barco y no provoca contacto entre barcos, ni entre un barco y un objeto que deba evitarse. Un barco con derecho de paso, o uno que está dentro del espacio que se le debe, solo necesita actuar cuando está claro que el otro no se mantiene separado ni da espacio.', 'Wenn es vernünftigerweise möglich ist, vermeidet ein Boot die Berührung mit einem anderen Boot und verursacht keine Berührung zwischen Booten oder zwischen einem Boot und einem Gegenstand, dem man ausweichen sollte. Ein Boot mit Wegerecht, oder eines innerhalb des Raums, der ihm zusteht, muss erst handeln, wenn klar ist, dass das andere sich nicht freihält oder keinen Raum gibt.', 'Makul ölçüde mümkünse bir tekne diğer tekneyle temastan kaçınır; tekneler arasında ya da bir tekne ile kaçınılması gereken bir nesne arasında temasa yol açmaz. Geçiş hakkı olan tekne ya da kendisine tanınması gereken alan içindeki tekne, ancak diğerinin uzak durmadığı ya da alan vermediği belli olduktan sonra harekete geçmek zorundadır.']),
          rule('15', ['Acquiring right of way', 'Получение права дороги', 'Adquirir el derecho de paso', 'Wegerecht erwerben', 'Geçiş hakkı kazanma'], ['A boat that gains right of way at first gives the other boat room to keep clear, unless she gained it through the other boat’s own actions.', 'Лодка, получившая право дороги, сначала даёт другой место, чтобы уступить, если только право не появилось из-за действий самой другой лодки.', 'Un barco que adquiere el derecho de paso da al principio al otro barco espacio para mantenerse separado, salvo que lo haya adquirido por las propias acciones del otro barco.', 'Ein Boot, das Wegerecht erwirbt, gibt dem anderen Boot zunächst Raum, sich freizuhalten, es sei denn, es hat das Wegerecht durch das eigene Handeln des anderen Boots erworben.', 'Geçiş hakkı kazanan tekne, başlangıçta diğer tekneye uzak durması için alan verir; ancak hakkı diğer teknenin kendi hareketleriyle kazandıysa bu şart aranmaz.'], '/learn/rules#r13'),
          rule('16', ['Changing course', 'Изменение курса', 'Cambiar de rumbo', 'Kursänderung', 'Rota değiştirme'], ['A right-of-way boat that changes course gives the other boat room to keep clear (16.1). On a beat, when a port-tack boat is keeping clear by heading to pass astern of a starboard-tack boat, the starboard boat must not bear away if the port boat would then have to change course at once to keep clear (16.2).', 'Лодка с правом дороги, меняя курс, даёт другой место, чтобы уступить (16.1). На лавировке, когда лодка левого галса уступает, собираясь пройти за кормой лодки правого галса, та не должна уваливаться, если из-за этого лодке левого галса придётся немедленно менять курс (16.2).', 'Un barco con derecho de paso que cambia de rumbo da al otro barco espacio para mantenerse separado (16.1). En una ceñida, cuando un barco en amura de babor se mantiene separado dirigiéndose a pasar por la popa de un barco en amura de estribor, el barco de estribor no debe arribar si el de babor tuviera entonces que cambiar de rumbo de inmediato para mantenerse separado (16.2).', 'Ein Boot mit Wegerecht, das den Kurs ändert, gibt dem anderen Boot Raum, sich freizuhalten (16.1). Auf einem Kreuzkurs, wenn ein Boot auf Backbordbug sich freihält, indem es hinter einem Boot auf Steuerbordbug durchgeht, darf das Steuerbordboot nicht abfallen, wenn das Backbordboot dann sofort den Kurs ändern müsste, um sich freizuhalten (16.2).', 'Rota değiştiren geçiş hakkı sahibi tekne, diğer tekneye uzak durması için alan verir (16.1). Orsa ayağında, iskele kontradaki tekne sancak kontradaki teknenin kıçından geçecek şekilde baş çevirerek uzak duruyorsa, sancak kontradaki tekne, iskele kontradaki teknenin hemen rota değiştirmesini gerektirecekse boşlamamalıdır (16.2).'], '/learn/rules#r13'),
          rule('17', ['On the same tack; proper course', 'На одном галсе; надлежащий курс', 'En la misma amura; rumbo debido', 'Auf demselben Bug; richtiger Kurs', 'Aynı kontrada; uygun rota'], ['A boat that becomes overlapped from clear astern within two of her hull lengths to leeward of a boat on the same tack doesn’t sail above her proper course while they stay on that tack and overlapped within that distance, unless by doing so she promptly passes astern of the other boat.', 'Лодка, ставшая связанной из положения чисто позади ближе двух своих корпусов с подветра от лодки того же галса, не идёт выше надлежащего курса, пока они на этом галсе и связаны на таком расстоянии, если только при этом она сразу не проходит за кормой другой лодки.', 'Un barco que se compromete por sotavento, viniendo libre por la popa y a menos de dos esloras de casco de un barco en la misma amura, no navega por encima de su rumbo debido mientras ambos sigan en esa amura y comprometidos dentro de esa distancia, salvo que al hacerlo pase de inmediato por la popa del otro barco.', 'Ein Boot, das von klar achteraus innerhalb von zwei Rumpflängen in Lee eines Boots auf demselben Bug überlappt wird, segelt nicht höher als seinen richtigen Kurs, solange sie auf diesem Bug und innerhalb dieser Entfernung überlappt bleiben, es sei denn, es geht dadurch zügig hinter dem anderen Boot durch.', 'Aynı kontradaki bir teknenin rüzgâraltında, iki gövde boyu içinde açık arkadan bindirme kuran tekne, bu kontrada ve bu mesafe içinde bindirmeli kaldıkları sürece uygun rotasının üstüne orsalamaz; ancak bunu yaparak hemen diğer teknenin kıçından geçiyorsa istisnadır.'], '/learn/rules#r11'),
        ]),
        sec('section-c', ['Section C · At marks and obstructions', 'Раздел C · У знаков и препятствий', 'Sección C · En balizas y obstrucciones', 'Abschnitt C · An Bahnmarken und Hindernissen', 'C Kısmı · Şamandıralarda ve engellerde'], ['Section C doesn’t apply at a starting mark surrounded by navigable water, or at its anchor line, from when boats approach it to start until they have left it astern.', 'Раздел C не действует у стартового знака, окружённого судоходной водой, и у его якорного конца с момента, когда лодки подходят к нему для старта, и пока не оставят его за кормой.', 'La sección C no se aplica en una baliza de salida rodeada de agua navegable, ni en su línea de fondeo, desde que los barcos se aproximan a ella para salir hasta que la han dejado por la popa.', 'Abschnitt C gilt nicht an einer Startmarke, die von schiffbarem Wasser umgeben ist, oder an ihrer Ankerleine, ab dem Moment, in dem Boote sich ihr zum Start nähern, bis sie sie achteraus gelassen haben.', 'C Kısmı, çevresi seyre elverişli suyla çevrili bir start şamandırasında ya da onun çapa halatında, tekneler start için yaklaşmaya başladığından onu arkada bırakana kadar uygulanmaz.'], [
          rule('18.1', ['Mark-room: when rule 18 applies', 'Место у знака: когда действует правило 18', 'Espacio en baliza: cuándo se aplica la regla 18', 'Bahnmarkenraum: wann Regel 18 gilt', 'Şamandıra alanı: kural 18 ne zaman uygulanır'], ['When boats must leave a mark on the same side and at least one is in the zone. Not between boats on opposite tacks on a beat, on opposite tacks when only one of them has to tack at the mark, between a boat approaching a mark and one leaving it, or at a mark that is a continuing obstruction. It ends once mark-room has been given.', 'Когда лодки должны оставить знак с одной стороны и хотя бы одна из них в зоне. Не действует между лодками на разных галсах на лавировке, на разных галсах, когда у знака поворачивать надо только одной, между подходящей к знаку и отходящей от него, а также у знака, который является протяжённым препятствием. Перестаёт действовать, когда место у знака дано.', 'Cuando los barcos deben dejar una baliza por la misma banda y al menos uno está en la zona. No se aplica entre barcos en amuras opuestas en una ceñida, en amuras opuestas cuando solo uno de ellos tiene que virar por avante en la baliza, entre un barco que se aproxima a una baliza y otro que la está dejando, ni en una baliza que es una obstrucción continua. Termina una vez que se ha dado el espacio en baliza.', 'Wenn Boote eine Bahnmarke auf derselben Seite lassen müssen und mindestens eines in der Zone ist. Nicht zwischen Booten auf entgegengesetzten Bugen auf einem Kreuzkurs, auf entgegengesetzten Bugen, wenn nur eines von ihnen an der Bahnmarke wenden muss, zwischen einem Boot, das sich einer Bahnmarke nähert, und einem, das sie verlässt, oder an einer Bahnmarke, die ein fortdauerndes Hindernis ist. Sie endet, sobald der Bahnmarkenraum gegeben wurde.', 'Tekneler bir şamandırayı aynı yandan bırakmak zorundaysa ve en az biri bölgedeyse. Orsa ayağında zıt kontradaki tekneler arasında, zıt kontralarda yalnızca biri şamandırada tramola atmak zorundaysa, şamandıraya yaklaşan bir tekne ile onu bırakan bir tekne arasında ya da sürekli engel olan bir şamandırada uygulanmaz. Şamandıra alanı verildiğinde sona erer.'], '/learn/rules#r18'),
          rule('18.2', ['Mark-room: giving it', 'Место у знака: кто его даёт', 'Espacio en baliza: darlo', 'Bahnmarkenraum: ihn geben', 'Şamandıra alanı: verme'], ['When the first of two boats reaches the zone, an outside overlapped boat gives the inside boat mark-room; if they aren’t overlapped, the boat not yet in the zone gives it to the one that is. That duty lasts even if an overlap later breaks or begins, and ends if the entitled boat passes head to wind or leaves the zone. Where there is reasonable doubt about an overlap, it is taken not to have been made or broken in time.', 'Когда первая из двух лодок входит в зону, внешняя связанная лодка даёт внутренней место у знака; если они не связаны, его даёт та, что ещё не в зоне. Обязанность сохраняется, даже если связанность потом прервётся или появится, и кончается, когда лодка, которой положено место, проходит левентик или покидает зону. При обоснованном сомнении считается, что связанность не была установлена или прервана вовремя.', 'Cuando el primero de dos barcos llega a la zona, un barco exterior comprometido da espacio en baliza al barco interior; si no están comprometidos, el barco que aún no está en la zona se lo da al que ya está. Ese deber se mantiene aunque un compromiso se rompa o empiece más tarde, y termina si el barco con derecho pasa la proa al viento o sale de la zona. Cuando hay duda razonable sobre un compromiso, se considera que no se estableció o no se rompió a tiempo.', 'Wenn das erste von zwei Booten die Zone erreicht, gibt ein äußeres überlapptes Boot dem inneren Boot Bahnmarkenraum; sind sie nicht überlappt, gibt ihn das Boot, das noch nicht in der Zone ist, dem Boot, das in der Zone ist. Diese Pflicht besteht auch dann, wenn eine Überlappung später endet oder entsteht, und sie endet, wenn das berechtigte Boot durch den Wind geht oder die Zone verlässt. Bei vernünftigem Zweifel an einer Überlappung gilt sie als nicht rechtzeitig entstanden oder beendet.', 'İki teknenin ilki bölgeye ulaştığında, dıştaki bindirmeli tekne içteki tekneye şamandıra alanı verir; bindirmeli değillerse, henüz bölgede olmayan tekne bunu bölgedeki tekneye verir. Bu yükümlülük, bindirme sonradan bozulsa ya da kurulsa da sürer; hak sahibi tekne başı rüzgârdan geçerse ya da bölgeden çıkarsa sona erer. Bir bindirmeden makul şüphe varsa, bindirmenin zamanında kurulmadığı ya da bozulmadığı kabul edilir.'], '/learn/rules#r18'),
          rule('18.3', ['Mark-room: tacking in the zone', 'Место у знака: поворот в зоне', 'Espacio en baliza: virar por avante en la zona', 'Bahnmarkenraum: Wenden in der Zone', 'Şamandıra alanı: bölgede tramola'], ['A boat that tacks from port to starboard in the zone of a mark left to port gets no mark-room from a starboard-tack boat fetching it. If that boat has been on starboard since entering the zone, the tacking boat must not make her sail above close-hauled to avoid contact, and gives her mark-room if she becomes overlapped inside.', 'Лодка, повернувшая с левого галса на правый в зоне знака, оставляемого слева, не получает места у знака от лодки правого галса, лежащей на этот знак. Если та идёт правым галсом с момента входа в зону, повернувшая не должна заставлять её идти выше бейдевинда, чтобы избежать контакта, и даёт ей место у знака, если та окажется связанной изнутри.', 'Un barco que vira por avante de babor a estribor en la zona de una baliza que se deja por babor no recibe espacio en baliza de un barco en amura de estribor que llega a ella. Si ese barco está en estribor desde que entró en la zona, el barco que vira no debe obligarle a navegar por encima de la ceñida para evitar el contacto, y le da espacio en baliza si se compromete por el interior.', 'Ein Boot, das in der Zone einer an Backbord zu lassenden Bahnmarke von Backbordbug auf Steuerbordbug wendet, erhält keinen Bahnmarkenraum von einem Boot auf Steuerbordbug, das die Bahnmarke anliegt. Ist dieses Boot seit dem Eintritt in die Zone auf Steuerbord, darf das wendende Boot es nicht zwingen, höher als hoch am Wind zu segeln, um eine Berührung zu vermeiden, und gibt ihm Bahnmarkenraum, wenn es innen überlappt wird.', 'İskelede bırakılan bir şamandıranın bölgesinde iskeleden sancağa tramola atan tekne, şamandıraya yetişebilen sancak kontradaki tekneden şamandıra alanı alamaz. O tekne bölgeye girdiğinden beri sancaktaysa, tramola atan tekne onu temastan kaçınmak için orsadan daha yukarı seyretmeye zorlamamalıdır; içeriden bindirme kurarsa ona şamandıra alanı verir.'], '/learn/rules#r18'),
          rule('18.4', ['Mark-room: gybing in the zone', 'Место у знака: поворот фордевинд в зоне', 'Espacio en baliza: trasluchar en la zona', 'Bahnmarkenraum: Halsen in der Zone', 'Şamandıra alanı: bölgede kavança'], ['An inside overlapped right-of-way boat that must gybe at a mark to sail her proper course sails no farther from the mark than that course needs until she gybes. This doesn’t apply at a gate mark.', 'Внутренняя связанная лодка с правом дороги, которой для надлежащего курса нужно сделать у знака поворот фордевинд, до поворота уходит от знака не дальше, чем требует этот курс. У знака ворот это не действует.', 'Un barco interior comprometido y con derecho de paso que debe trasluchar en una baliza para navegar su rumbo debido no navega más lejos de la baliza de lo que ese rumbo necesite hasta que trasluche. Esto no se aplica en una baliza de puerta.', 'Ein inneres überlapptes Boot mit Wegerecht, das an einer Bahnmarke halsen muss, um seinen richtigen Kurs zu segeln, segelt bis zur Halse nicht weiter von der Bahnmarke weg, als dieser Kurs es erfordert. Das gilt nicht an einer Tormarke.', 'Uygun rotasını izlemek için şamandırada kavança atmak zorunda olan, içteki bindirmeli geçiş hakkı sahibi tekne, kavança atana kadar şamandıradan o rotanın gerektirdiğinden daha uzağa gitmez. Bu, kapı şamandırasında uygulanmaz.'], '/learn/rules#r18'),
          rule('19', ['Room to pass an obstruction', 'Место для прохода препятствия', 'Espacio para pasar una obstrucción', 'Raum, ein Hindernis zu passieren', 'Engelden geçmek için alan'], ['At an obstruction a right-of-way boat may choose either side, giving room to keep clear if she changes course to choose. An outside overlapped boat gives the inside boat room between her and the obstruction, unless she has been unable to from when the overlap began. At a continuing obstruction, a boat from clear astern who overlaps inside with no room to pass has no right to room and keeps clear. At a mark, rule 18 applies instead, except at a continuing obstruction.', 'Лодка с правом дороги может пройти препятствие с любой стороны, но, меняя для этого курс, даёт другой место, чтобы уступить. Внешняя связанная лодка даёт внутренней место между собой и препятствием, если только не была лишена такой возможности с начала связанности. У протяжённого препятствия лодка, вошедшая изнутри из положения чисто позади, когда места для прохода нет, права на место не имеет и уступает. У знака вместо этого действует правило 18, кроме протяжённого препятствия.', 'En una obstrucción, un barco con derecho de paso puede elegir cualquiera de los dos lados, dando espacio para mantenerse separado si cambia de rumbo para elegir. Un barco exterior comprometido da al barco interior espacio entre él y la obstrucción, salvo que no haya podido hacerlo desde que empezó el compromiso. En una obstrucción continua, un barco que viene libre por la popa y se compromete por el interior sin espacio para pasar no tiene derecho a espacio y se mantiene separado. En una baliza se aplica en su lugar la regla 18, salvo en una obstrucción continua.', 'An einem Hindernis darf ein Boot mit Wegerecht eine der beiden Seiten wählen und gibt Raum, sich freizuhalten, wenn es dafür den Kurs ändert. Ein äußeres überlapptes Boot gibt dem inneren Boot Raum zwischen sich und dem Hindernis, es sei denn, es war dazu ab Beginn der Überlappung nicht in der Lage. An einem fortdauernden Hindernis hat ein Boot, das von klar achteraus innen überlappt und keinen Raum zum Passieren hat, kein Recht auf Raum und hält sich frei. An einer Bahnmarke gilt stattdessen Regel 18, außer an einem fortdauernden Hindernis.', 'Bir engelde geçiş hakkı olan tekne iki yandan birini seçebilir; seçmek için rota değiştirirse uzak durmaları için alan verir. Dıştaki bindirmeli tekne, bindirme başladığından beri yapamıyorsa dışında, içteki tekneye kendisi ile engel arasında alan verir. Sürekli bir engelde, açık arkadan içeriden bindirme kuran ve geçecek alanı olmayan tekne alan hakkı kazanmaz ve uzak durur. Şamandırada, sürekli engel dışında, bunun yerine kural 18 uygulanır.']),
          rule('20', ['Room to tack at an obstruction', 'Место для поворота у препятствия', 'Espacio para virar por avante en una obstrucción', 'Raum zum Wenden an einem Hindernis', 'Engelde tramola için alan'], ['A boat sailing close-hauled or above that will soon need to change course substantially to avoid an obstruction safely may hail “Room to tack” at a boat on the same tack, but not at a mark if a boat fetching it would have to change course. The hailed boat must respond, by tacking as soon as possible or by replying “You tack” and giving room; the hailing boat then tacks as soon as possible. A hailed boat may pass the hail on, and where a hail may not be heard a clear signal is added.', 'Лодка, идущая в бейдевинд или круче, которой скоро придётся существенно изменить курс, чтобы безопасно избежать препятствия, может окликнуть лодку того же галса: «Место для поворота». Нельзя окликать у знака, если из-за этого придётся менять курс лодке, лежащей на знак. Окликнутая обязана ответить: как можно скорее повернуть или ответить «Поворачивай» и дать место; окликнувшая затем поворачивает как можно скорее. Окликнутая может передать оклик дальше, а если оклик могут не услышать, добавляют ясный сигнал.', 'Un barco que navega de ceñida o por encima y que pronto necesitará cambiar de rumbo de forma sustancial para evitar con seguridad una obstrucción puede gritar «Espacio para virar» a un barco en la misma amura, pero no en una baliza si un barco que llega a ella tuviera que cambiar de rumbo. El barco al que se llama debe responder, virando por avante lo antes posible o contestando «Vira tú» y dando espacio; el barco que llamó vira entonces lo antes posible. Un barco al que se llama puede transmitir la llamada, y donde la llamada pueda no oírse se añade una señal clara.', 'Ein Boot, das hoch am Wind oder höher segelt und bald seinen Kurs deutlich ändern muss, um einem Hindernis sicher auszuweichen, darf einem Boot auf demselben Bug „Raum zum Wenden“ zurufen, aber nicht an einer Bahnmarke, wenn ein Boot, das sie anliegt, den Kurs ändern müsste. Das angerufene Boot muss reagieren, indem es so bald wie möglich wendet oder mit „Wende du“ antwortet und Raum gibt; das rufende Boot wendet dann so bald wie möglich. Ein angerufenes Boot darf den Ruf weitergeben, und wo ein Ruf möglicherweise nicht gehört wird, kommt ein deutliches Zeichen dazu.', 'Orsa ya da daha yüksek rotada seyreden ve bir engelden güvenle kaçınmak için yakında rotasını belirgin biçimde değiştirmesi gereken tekne, aynı kontradaki tekneye “Tramola için alan” diye seslenebilir; ancak şamandıraya yetişen bir tekne rota değiştirmek zorunda kalacaksa şamandırada seslenemez. Seslenilen tekne yanıt vermelidir: ya mümkün olan en kısa sürede tramola atar ya da “Sen tramola at” diye yanıtlayıp alan verir; seslenen tekne de ardından mümkün olan en kısa sürede tramola atar. Seslenilen tekne seslenmeyi iletebilir; sesin duyulmayabileceği yerde açık bir işaret de eklenir.']),
        ]),
        sec('section-d', ['Section D · Other rules', 'Раздел D · Другие правила', 'Sección D · Otras reglas', 'Abschnitt D · Weitere Regeln', 'D Kısmı · Diğer kurallar'], ['When rule 21 or 22 applies between two boats, the rules of Section A do not.', 'Когда между двумя лодками действует правило 21 или 22, правила раздела A не действуют.', 'Cuando la regla 21 o 22 se aplica entre dos barcos, no se aplican las reglas de la sección A.', 'Wenn Regel 21 oder 22 zwischen zwei Booten gilt, gelten die Regeln von Abschnitt A nicht.', 'Kural 21 ya da 22 iki tekne arasında uygulanıyorsa, A Kısmı kuralları uygulanmaz.'], [
          rule('21', ['Starting errors; taking penalties; backing a sail', 'Ошибки на старте; выполнение наказаний; парус на обратный ветер', 'Errores de salida; cumplir penalizaciones; dar atrás con una vela', 'Startfehler; Strafen nehmen; Segel backhalten', 'Start hataları; ceza yapmak; yelkeni ters almak'], ['A boat going back to the pre-start side after her starting signal keeps clear of boats that aren’t, until her hull is completely on that side (21.1). A boat taking a penalty keeps clear of one that isn’t (21.2). A boat moving astern, or sideways to windward, by backing a sail keeps clear of one that isn’t (21.3).', 'Лодка, возвращающаяся на предстартовую сторону после своего стартового сигнала, уступает всем остальным, пока её корпус целиком не окажется на этой стороне (21.1). Лодка, выполняющая наказание, уступает той, что его не выполняет (21.2). Лодка, идущая назад или боком на ветер с парусом на обратный ветер, уступает той, что этого не делает (21.3).', 'Un barco que vuelve al lado de pre-salida después de su señal de salida se mantiene separado de los barcos que no lo hacen, hasta que su casco está completamente en ese lado (21.1). Un barco que cumple una penalización se mantiene separado de uno que no (21.2). Un barco que se mueve hacia atrás, o de lado hacia barlovento, al hacer flamear una vela hacia atrás se mantiene separado de uno que no (21.3).', 'Ein Boot, das nach seinem Startsignal zur Vorstartseite zurückkehrt, hält sich von Booten frei, die das nicht tun, bis sein Rumpf vollständig auf dieser Seite ist (21.1). Ein Boot, das eine Strafe nimmt, hält sich von einem frei, das das nicht tut (21.2). Ein Boot, das durch Backhalten eines Segels rückwärts oder seitwärts nach Luv fährt, hält sich von einem frei, das das nicht tut (21.3).', 'Start işaretinden sonra start öncesi tarafa dönen tekne, dönmeyen teknelerden, gövdesi tamamen o tarafa geçene kadar uzak durur (21.1). Ceza yapan tekne, yapmayan tekneden uzak durur (21.2). Yelkeni ters alarak geriye ya da rüzgârüstüne doğru yan giden tekne, gitmeyen tekneden uzak durur (21.3).']),
          rule('22', ['Capsized, anchored or aground; rescuing', 'Перевёрнутая, на якоре, на мели; спасание', 'Volcado, fondeado o varado; rescate', 'Gekentert, geankert oder aufgelaufen; Rettung', 'Alabora, çapalı ya da karaya oturmuş; kurtarma'], ['If possible, a boat avoids a boat that is capsized or hasn’t regained control after capsizing, is anchored or aground, or is helping a person or vessel in danger. A boat is capsized when her masthead is in the water.', 'По возможности лодка избегает лодки, которая перевернулась или ещё не восстановила управление после этого, стоит на якоре или на мели либо помогает человеку или судну в опасности. Лодка перевёрнута, когда топ мачты в воде.', 'Si es posible, un barco evita a un barco que está volcado o no ha recuperado el control después de volcar, está fondeado o varado, o está ayudando a una persona o a un buque en peligro. Un barco está volcado cuando la punta de su palo está en el agua.', 'Wenn möglich, weicht ein Boot einem Boot aus, das gekentert ist oder nach dem Kentern die Kontrolle nicht zurückgewonnen hat, das geankert hat oder aufgelaufen ist oder das einer Person oder einem Fahrzeug in Gefahr hilft. Ein Boot ist gekentert, wenn sein Masttopp im Wasser ist.', 'Mümkünse tekne; alabora olmuş ya da alabora sonrası kontrolünü geri kazanmamış, çapalı ya da karaya oturmuş ya da tehlikedeki bir kişiye veya tekneye yardım eden tekneden kaçınır. Direk ucu suda olan tekne alabora olmuş sayılır.']),
          rule('23', ['Interfering with another boat', 'Помеха другой лодке', 'Interferir con otro barco', 'Ein anderes Boot behindern', 'Başka tekneye engel olma'], ['If reasonably possible, a boat not racing doesn’t interfere with a boat that is racing (23.1), and no boat interferes with one taking a penalty, sailing another leg or returning under rule 21.1. After the starting signal this second part doesn’t bind a boat sailing her proper course (23.2).', 'Если это разумно возможно, лодка не в гонке не мешает лодке в гонке (23.1), и никакая лодка не мешает той, что выполняет наказание, идёт по другому отрезку дистанции или возвращается по правилу 21.1. После стартового сигнала эта вторая часть не связывает лодку, идущую надлежащим курсом (23.2).', 'Si es razonablemente posible, un barco que no está en regata no interfiere con un barco que sí lo está (23.1), y ningún barco interfiere con uno que cumple una penalización, navega otro tramo o vuelve conforme a la regla 21.1. Después de la señal de salida, esta segunda parte no obliga a un barco que navega su rumbo debido (23.2).', 'Wenn es vernünftigerweise möglich ist, behindert ein Boot, das nicht in der Wettfahrt ist, kein Boot, das in der Wettfahrt ist (23.1), und kein Boot behindert eines, das eine Strafe nimmt, einen anderen Schenkel segelt oder nach Regel 21.1 zurückkehrt. Nach dem Startsignal bindet dieser zweite Teil kein Boot, das seinen richtigen Kurs segelt (23.2).', 'Makul ölçüde mümkünse yarışmayan bir tekne yarışan tekneye engel olmaz (23.1); hiçbir tekne de ceza yapan, başka bir ayakta seyreden ya da kural 21.1 uyarınca geri dönen tekneye engel olmaz. Start işaretinden sonra bu ikinci kısım, uygun rotasında seyreden tekneyi bağlamaz (23.2).']),
        ]),
      ] },

    { id: 'part-3', chip: t('Part 3', 'Часть 3', 'Parte 3', 'Teil 3', 'Bölüm 3'), title: t('Part 3 · Conduct of a race', 'Часть 3 · Проведение гонки', 'Parte 3 · Conducción de una regata', 'Teil 3 · Durchführung einer Wettfahrt', 'Bölüm 3 · Yarışın yürütülmesi'),
      intro: t('How the race committee starts, shortens, changes and ends a race, and what each signal asks of you.', 'Как гоночный комитет стартует, сокращает, меняет и завершает гонку и чего требует каждый сигнал.', 'Cómo el comité de regatas da la salida, acorta, cambia y termina una regata, y qué te pide cada señal.', 'Wie die Wettfahrtleitung eine Wettfahrt startet, verkürzt, ändert und beendet und was jedes Signal von dir verlangt.', 'Yarış komitesinin yarışı nasıl başlattığı, kısalttığı, değiştirdiği ve bitirdiği, ve her işaretin senden ne istediği.'),
      sections: [{ entries: [
        rule('25', ['Notice of race, sailing instructions and signals', 'Положение, гоночная инструкция и сигналы', 'Anuncio de regata, instrucciones de regata y señales', 'Ausschreibung, Segelanweisungen und Signale', 'Yarış ilanı, yarış talimatları ve işaretler'], ['The notice of race is available before a boat enters and the sailing instructions before a race begins. The meanings of the race signals are fixed, and any other signal must be explained in those documents. An object that looks like the flag may stand in for it.', 'Положение о соревновании доступно до подачи заявки, гоночная инструкция — до начала гонки. Значения гоночных сигналов неизменны, а любые другие сигналы объясняются в этих документах. Флаг можно заменить похожим на него предметом.', 'El anuncio de regata está disponible antes de que un barco se inscriba y las instrucciones de regata antes de que empiece una regata. El significado de las señales de regata es fijo, y cualquier otra señal debe explicarse en esos documentos. Un objeto que se parezca a la bandera puede sustituirla.', 'Die Ausschreibung liegt vor der Meldung eines Boots vor, die Segelanweisungen vor Beginn einer Wettfahrt. Die Bedeutung der Wettfahrtsignale ist festgelegt, und jedes andere Signal muss in diesen Dokumenten erklärt werden. Ein Gegenstand, der wie die Flagge aussieht, darf sie ersetzen.', 'Yarış ilanı tekne kayıt olmadan önce, yarış talimatları da yarış başlamadan önce erişilebilir olur. Yarış işaretlerinin anlamları değişmezdir; başka her işaret bu belgelerde açıklanmalıdır. Bayrağa benzeyen bir nesne onun yerine geçebilir.']),
        rule('26', ['Starting races', 'Старт гонки', 'Dar la salida a las regatas', 'Wettfahrten starten', 'Yarışların başlatılması'], ['The usual countdown: class flag up at 5 minutes with one sound (warning); P, I, Z, Z with I, U or the black flag up at 4 with one sound (preparatory); that flag down at 1 with one long sound; class flag down at 0 with one sound (start). Time is taken from the flags, so a missed sound doesn’t count.', 'Обычный отсчёт: за 5 минут поднят флаг класса, один звук (предупреждение); за 4 — флаг P, I, Z, Z с I, U или чёрный, один звук (подготовительный сигнал); за 1 — этот флаг спущен, один длинный звук; в 0 — флаг класса спущен, один звук (старт). Время считают по флагам, поэтому пропущенный звук не важен.', 'La cuenta atrás habitual: bandera de clase izada a los 5 minutos con una señal sonora (atención); P, I, Z, Z con I, U o la bandera negra izada a los 4 con una señal sonora (preparación); esa bandera arriada a 1 minuto con una señal sonora larga; bandera de clase arriada en 0 con una señal sonora (salida). El tiempo se toma de las banderas, así que una señal sonora que falla no cuenta.', 'Der übliche Countdown: Klassenflagge oben bei 5 Minuten mit einem Schallsignal (Warnsignal); P, I, Z, Z mit I, U oder die schwarze Flagge oben bei 4 mit einem Schallsignal (Vorbereitungssignal); diese Flagge runter bei 1 mit einem langen Schallsignal; Klassenflagge runter bei 0 mit einem Schallsignal (Start). Die Zeit wird nach den Flaggen genommen, ein verpasstes Schallsignal zählt also nicht.', 'Olağan geri sayım: sınıf bayrağı 5 dakikada bir ses işaretiyle çekilir (uyarı); P, I, Z, Z ile I, U ya da siyah bayrak 4. dakikada bir ses işaretiyle çekilir (hazırlık); o bayrak 1. dakikada bir uzun ses işaretiyle indirilir; sınıf bayrağı 0. dakikada bir ses işaretiyle indirilir (start). Zaman bayraklardan alınır; kaçırılan bir ses sayılmaz.'], '/learn/start'),
        rule('27', ['Other race committee actions before the starting signal', 'Другие действия комитета до старта', 'Otras acciones del comité de regatas antes de la señal de salida', 'Weitere Maßnahmen der Wettfahrtleitung vor dem Startsignal', 'Start işaretinden önce yarış komitesinin diğer eylemleri'], ['By the warning signal the committee signals the course if the sailing instructions haven’t set it, and may require personal flotation devices with flag Y. By the preparatory signal it may move a starting mark. Before the start it may postpone or abandon the race for any reason.', 'Не позже предупреждения комитет обозначает дистанцию, если её нет в инструкции, и может флагом Y потребовать надеть жилеты. Не позже подготовительного сигнала может передвинуть стартовый знак. До старта может отложить или прекратить гонку по любой причине.', 'Para la señal de atención, el comité indica el recorrido si las instrucciones de regata no lo han fijado, y puede exigir dispositivos personales de flotación con la bandera Y. Para la señal de preparación puede mover una baliza de salida. Antes de la salida puede aplazar o anular la regata por cualquier motivo.', 'Spätestens beim Warnsignal zeigt die Wettfahrtleitung die Bahn an, wenn die Segelanweisungen sie nicht festlegen, und kann mit Flagge Y Schwimmwesten vorschreiben. Bis zum Vorbereitungssignal darf sie eine Startmarke verlegen. Vor dem Start darf sie die Wettfahrt aus jedem Grund verschieben oder abbrechen.', 'Uyarı işaretine kadar komite, yarış talimatları belirlememişse parkuru işaret eder ve Y bayrağıyla can yeleği zorunlu kılabilir. Hazırlık işaretine kadar bir start şamandırasını taşıyabilir. Start öncesinde yarışı her gerekçeyle erteleyebilir ya da iptal edebilir.']),
        rule('28', ['Sailing the course', 'Прохождение дистанции', 'Navegar el recorrido', 'Die Bahn segeln', 'Parkuru yelkenle tamamlama'], ['A boat sails the course, and may correct any mistake in it as long as she hasn’t finished.', 'Лодка проходит дистанцию и может исправить любую ошибку, пока не финишировала.', 'Un barco navega el recorrido, y puede corregir cualquier error en él mientras no haya llegado.', 'Ein Boot segelt die Bahn und darf jeden Fehler darin korrigieren, solange es nicht im Ziel ist.', 'Tekne parkuru yelkenle tamamlar ve bitirmediği sürece parkurdaki hatasını düzeltebilir.']),
        rule('29', ['Recalls', 'Отзывы', 'Llamadas', 'Rückrufe', 'Geri çağırmalar'], ['Individual recall: flag X with one sound when a boat is on the course side at her start or must comply with rule 30.1, flown until they are all back, but no later than four minutes after the start or one minute before a later start, whichever comes first. General recall: the First Substitute with two sounds when the boats can’t be identified or the procedure went wrong; the new warning comes one minute after it is lowered.', 'Индивидуальный отзыв: флаг X с одним звуком, если лодка в момент старта на стороне дистанции или должна выполнить правило 30.1; он поднят, пока все не вернутся, но не дольше четырёх минут после старта или до минуты перед следующим стартом — что раньше. Общий отзыв: Первый заменяющий с двумя звуками, если лодки нельзя опознать или в процедуре была ошибка; новое предупреждение — через минуту после спуска флага.', 'Llamada individual: bandera X con una señal sonora cuando un barco está en el lado del recorrido en su salida o debe cumplir la regla 30.1, izada hasta que todos hayan vuelto, pero no más tarde de cuatro minutos después de la salida o un minuto antes de una salida posterior, lo que ocurra primero. Llamada general: el Primer Repetidor con dos señales sonoras cuando no se puede identificar a los barcos o el procedimiento falló; la nueva señal de atención llega un minuto después de arriarlo.', 'Einzelrückruf: Flagge X mit einem Schallsignal, wenn ein Boot bei seinem Start auf der Bahnseite ist oder Regel 30.1 befolgen muss, gezeigt, bis alle zurück sind, aber nicht länger als vier Minuten nach dem Start oder eine Minute vor einem späteren Start, je nachdem, was zuerst eintritt. Allgemeiner Rückruf: der Erste Wiederholer mit zwei Schallsignalen, wenn die Boote nicht identifiziert werden können oder das Verfahren falsch lief; das neue Warnsignal kommt eine Minute nach dem Niederholen.', 'Bireysel geri çağırma: bir tekne startta parkur tarafındayken ya da kural 30.1’e uymak zorundayken X bayrağı bir ses işaretiyle çekilir; hepsi geri dönene kadar açık kalır, ancak startın en geç dört dakika sonrasına ya da sonraki bir startın bir dakika öncesine kadar, hangisi önce gelirse. Genel geri çağırma: tekneler tanımlanamadığında ya da prosedür yanlış gittiğinde iki ses işaretiyle Birinci Yedek; yeni uyarı, indirildikten bir dakika sonra gelir.']),
        rule('30', ['Starting penalties', 'Наказания на старте', 'Penalizaciones de salida', 'Startstrafen', 'Start cezaları'], ['Flag I: a boat on the course side in the last minute must go round an end of the line to the pre-start side before she starts. In the last minute, under flags Z, U and black, no part of the hull may be in the triangle of the line’s ends and the first mark. Z: a 20% scoring penalty, even if the race is restarted. U: disqualified without a hearing, unless the race is restarted or resailed. Black: disqualified without a hearing even then, and she may not sail the restart.', 'Флаг I: лодка на стороне дистанции в последнюю минуту должна вернуться на предстартовую сторону через продолжение линии, прежде чем стартовать. В последнюю минуту при флагах Z, U и чёрном ни одна часть корпуса не должна быть в треугольнике из концов линии и первого знака. Z: штраф 20% очков, даже если гонку перестартуют. U: дисквалификация без рассмотрения, если гонку не перестартуют и не проведут заново. Чёрный: дисквалификация без рассмотрения даже в этом случае, и в новом старте лодка участвовать не может.', 'Bandera I: un barco que está en el lado del recorrido en el último minuto debe rodear un extremo de la línea hacia el lado de pre-salida antes de salir. En el último minuto, con las banderas Z, U y negra, ninguna parte del casco puede estar en el triángulo formado por los extremos de la línea y la primera baliza. Z: una penalización de puntuación del 20 %, aunque se vuelva a dar la salida. U: descalificado sin audiencia, salvo que se vuelva a dar la salida o se repita la regata. Negra: descalificado sin audiencia incluso entonces, y no puede navegar la nueva salida.', 'Flagge I: Ein Boot, das in der letzten Minute auf der Bahnseite ist, muss vor dem Start um ein Ende der Linie zur Vorstartseite fahren. In der letzten Minute darf bei den Flaggen Z, U und Schwarz kein Teil des Rumpfs im Dreieck aus den Enden der Linie und der ersten Bahnmarke sein. Z: eine Wertungsstrafe von 20 %, auch wenn die Wettfahrt neu gestartet wird. U: ohne Verhandlung disqualifiziert, es sei denn, die Wettfahrt wird neu gestartet oder neu gesegelt. Schwarz: auch dann ohne Verhandlung disqualifiziert, und es darf den Neustart nicht segeln.', 'I bayrağı: son dakikada parkur tarafında olan tekne, startını almadan önce hattın bir ucunu dolaşarak start öncesi tarafa geçmelidir. Son dakikada Z, U ve siyah bayrak altında, gövdenin hiçbir parçası hattın uçları ile ilk şamandıranın oluşturduğu üçgenin içinde olamaz. Z: yarış yeniden başlatılsa bile %20 puan cezası. U: yarış yeniden başlatılmadıkça ya da yeniden yapılmadıkça duruşmasız diskalifiye. Siyah: yeniden başlatılsa bile duruşmasız diskalifiye ve yeniden startta yarışamaz.']),
        rule('31', ['Touching a mark', 'Касание знака', 'Tocar una baliza', 'Eine Marke berühren', 'Şamandıraya dokunma'], ['While racing, a boat doesn’t touch a starting mark before starting, a mark that begins, bounds or ends the leg she is on, or a finishing mark after finishing.', 'В гонке лодка не касается стартового знака до старта, знака, который начинает, ограничивает или заканчивает её отрезок дистанции, и финишного знака после финиша.', 'Mientras está en regata, un barco no toca una baliza de salida antes de salir, una baliza que empieza, limita o termina el tramo en que está, ni una baliza de llegada después de llegar.', 'In der Wettfahrt berührt ein Boot vor dem Start keine Startmarke, keine Marke, die den Schenkel beginnt, begrenzt oder beendet, auf dem es ist, und nach dem Ziel keine Zielmarke.', 'Yarışırken tekne, startını almadan önce bir start şamandırasına, bulunduğu ayağı başlatan, sınırlayan ya da bitiren bir şamandıraya ya da bitirdikten sonra bir bitiş şamandırasına dokunmaz.'], '/learn/rules#pen'),
        rule('32', ['Shortening or abandoning after the start', 'Сокращение или прекращение после старта', 'Acortar o anular después de la salida', 'Nach dem Start verkürzen oder abbrechen', 'Startın ardından kısaltma ya da iptal'], ['After the start the committee may shorten or abandon for foul weather, too little wind to finish in the time limit, a mark missing or out of position, or anything directly affecting safety or fairness. It may also shorten so other races can be sailed, or abandon for an error in the starting procedure. Shorten: flag S with two sounds. Abandon: N, N over H or N over A with three sounds.', 'После старта комитет может сократить или прекратить гонку из-за плохой погоды, слабого ветра, когда никто не успеет за контрольное время, пропажи или смещения знака и всего, что прямо влияет на безопасность или честность. Может также сократить, чтобы провести другие гонки, или прекратить из-за ошибки в процедуре старта. Сокращение: флаг S, два звука. Прекращение: N, N над H или N над A, три звука.', 'Después de la salida, el comité puede acortar o anular por mal tiempo, viento insuficiente para llegar dentro del tiempo límite, una baliza que falta o está fuera de posición, o cualquier cosa que afecte directamente a la seguridad o la equidad. También puede acortar para poder navegar otras regatas, o anular por un error en el procedimiento de salida. Acortar: bandera S con dos señales sonoras. Anular: N, N sobre H o N sobre A con tres señales sonoras.', 'Nach dem Start darf die Wettfahrtleitung verkürzen oder abbrechen wegen schlechten Wetters, zu wenig Winds, um innerhalb der Zeitgrenze ins Ziel zu kommen, einer fehlenden oder verrutschten Marke oder allem, was Sicherheit oder Fairness unmittelbar betrifft. Sie darf auch verkürzen, damit weitere Wettfahrten gesegelt werden können, oder wegen eines Fehlers im Startverfahren abbrechen. Verkürzen: Flagge S mit zwei Schallsignalen. Abbrechen: N, N über H oder N über A mit drei Schallsignalen.', 'Startın ardından komite, kötü hava, bitirmek için süre sınırı içinde yetersiz rüzgâr, eksik ya da yerinden oynamış bir şamandıra ya da doğrudan güvenliği veya adaleti etkileyen herhangi bir şey nedeniyle yarışı kısaltabilir ya da iptal edebilir. Başka yarışların yapılabilmesi için de kısaltabilir ya da start prosedüründeki bir hata nedeniyle iptal edebilir. Kısaltma: S bayrağı, iki ses işaretiyle. İptal: N, N üstünde H ya da N üstünde A, üç ses işaretiyle.']),
        rule('33', ['Changing the next leg of the course', 'Изменение следующего отрезка', 'Cambiar el siguiente tramo del recorrido', 'Den nächsten Schenkel der Bahn ändern', 'Parkurun sonraki ayağını değiştirme'], ['At a rounding mark or a gate the committee may change the next leg by moving the next mark or the finishing line, signalling before boats begin the leg: flag C with repetitive sounds and the new bearing, a green triangle for starboard, a red rectangle for port, or “–” or “+” for a shorter or longer leg.', 'У знака огибания или ворот комитет может изменить следующий отрезок, передвинув следующий знак или финишную линию, и подаёт сигнал до начала этого отрезка: флаг C с повторяющимися звуками и новый пеленг, зелёный треугольник — вправо, красный прямоугольник — влево, либо «–» или «+» — короче или длиннее.', 'En una baliza de redondeo o una puerta, el comité puede cambiar el siguiente tramo moviendo la siguiente baliza o la línea de llegada, avisando antes de que los barcos empiecen el tramo: bandera C con señales sonoras repetidas y el nuevo rumbo, un triángulo verde para estribor, un rectángulo rojo para babor, o «–» o «+» para un tramo más corto o más largo.', 'An einer Rundungsmarke oder einem Tor darf die Wettfahrtleitung den nächsten Schenkel ändern, indem sie die nächste Marke oder die Ziellinie verlegt, und signalisiert das, bevor die Boote den Schenkel beginnen: Flagge C mit wiederholten Schallsignalen und dem neuen Kompasskurs, ein grünes Dreieck für Steuerbord, ein rotes Rechteck für Backbord oder „–“ oder „+“ für einen kürzeren oder längeren Schenkel.', 'Dönüş şamandırasında ya da kapıda komite, sonraki şamandırayı ya da bitiş hattını taşıyarak sonraki ayağı değiştirebilir; bunu tekneler ayağa başlamadan işaret eder: tekrarlı ses işaretleriyle C bayrağı ve yeni kerteriz, sancak için yeşil üçgen, iskele için kırmızı dikdörtgen, ya da daha kısa veya daha uzun ayak için “–” veya “+”.']),
        rule('34', ['Mark missing', 'Пропавший знак', 'Baliza que falta', 'Fehlende Marke', 'Eksik şamandıra'], ['If a mark is missing or out of position the committee, if possible, puts it back or replaces it with a similar one, or with an object showing flag M and repetitive sounds.', 'Если знак пропал или смещён, комитет по возможности возвращает его на место, заменяет похожим либо предметом с флагом M и подаёт повторяющиеся звуки.', 'Si una baliza falta o está fuera de posición, el comité, si es posible, la vuelve a poner o la sustituye por otra similar, o por un objeto que muestre la bandera M y señales sonoras repetidas.', 'Fehlt eine Marke oder ist sie verrutscht, setzt die Wettfahrtleitung sie, wenn möglich, wieder an ihren Platz oder ersetzt sie durch eine ähnliche oder durch einen Gegenstand, der Flagge M und wiederholte Schallsignale zeigt.', 'Bir şamandıra eksikse ya da yerinden oynamışsa komite, mümkünse onu yerine koyar ya da benzeri bir şamandırayla ya da M bayrağı ve tekrarlı ses işaretleri gösteren bir nesneyle değiştirir.']),
        rule('35', ['Race time limit and scores', 'Контрольное время и очки', 'Tiempo límite de la regata y puntuación', 'Zeitgrenze der Wettfahrt und Wertung', 'Yarış süre sınırı ve puanlar'], ['If one boat sails the course within any time limit, every boat that finishes is scored by her place unless the race is abandoned. If none does, the committee abandons the race.', 'Если хотя бы одна лодка прошла дистанцию в контрольное время, все финишировавшие получают очки по местам, если гонка не прекращена. Если никто не успел, комитет прекращает гонку.', 'Si un barco navega el recorrido dentro de cualquier tiempo límite, todos los barcos que llegan se puntúan por su puesto, salvo que se anule la regata. Si ninguno lo hace, el comité anula la regata.', 'Segelt ein Boot die Bahn innerhalb einer Zeitgrenze, wird jedes Boot, das ins Ziel kommt, nach seinem Platz gewertet, es sei denn, die Wettfahrt wird abgebrochen. Schafft es keines, bricht die Wettfahrtleitung die Wettfahrt ab.', 'Bir tekne süre sınırı içinde parkuru tamamlarsa, yarış iptal edilmedikçe bitiren her tekne yerine göre puanlanır. Hiçbiri tamamlamazsa komite yarışı iptal eder.']),
        rule('36', ['Races restarted or resailed', 'Новый старт или повторная гонка', 'Regatas con nueva salida o repetidas', 'Neu gestartete oder neu gesegelte Wettfahrten', 'Yeniden başlatılan ya da yeniden yapılan yarışlar'], ['A breach in the original race doesn’t stop a boat sailing the restart or resail unless she broke rule 30.4, and penalises her only under rule 2, 30.2, 30.4 or 69, or rule 14 if she caused injury or serious damage.', 'Нарушение в первоначальной гонке не мешает участвовать в новом старте или повторной гонке, кроме нарушения правила 30.4, и наказывается только по правилам 2, 30.2, 30.4 или 69 либо по правилу 14, если лодка причинила травму или серьёзное повреждение.', 'Una infracción en la regata original no impide que un barco navegue la nueva salida o la repetición, salvo que haya infringido la regla 30.4, y solo se le penaliza conforme a la regla 2, 30.2, 30.4 o 69, o la regla 14 si causó lesión o daño grave.', 'Ein Verstoß in der ursprünglichen Wettfahrt hindert ein Boot nicht daran, den Neustart oder die Wiederholung zu segeln, es sei denn, es hat Regel 30.4 verletzt, und wird dafür nur nach Regel 2, 30.2, 30.4 oder 69 bestraft, oder nach Regel 14, wenn es Verletzung oder ernsthaften Schaden verursacht hat.', 'Asıl yarıştaki bir ihlal, tekne kural 30.4’ü çiğnemedikçe onun yeniden startta ya da yeniden yarışta yelken açmasını engellemez; ve ona yalnızca kural 2, 30.2, 30.4 ya da 69’dan, yaralanmaya ya da ciddi hasara yol açtıysa kural 14’ten ceza verir.']),
        rule('37', ['Search and rescue instructions', 'Поисково-спасательные указания', 'Instrucciones de búsqueda y rescate', 'Anweisungen zu Suche und Rettung', 'Arama kurtarma talimatları'], ['At flag V with one sound, all boats and official and support vessels monitor the race committee’s channel, if they can, for search and rescue instructions.', 'При флаге V с одним звуком все лодки и суда обеспечения по возможности слушают канал гоночного комитета для получения поисково-спасательных указаний.', 'Con la bandera V y una señal sonora, todos los barcos y los buques oficiales y de apoyo escuchan, si pueden, el canal del comité de regatas para recibir instrucciones de búsqueda y rescate.', 'Bei Flagge V mit einem Schallsignal hören alle Boote sowie Offiziellen- und Betreuerfahrzeuge, wenn sie können, den Kanal der Wettfahrtleitung auf Anweisungen zu Suche und Rettung ab.', 'V bayrağı bir ses işaretiyle çekildiğinde, tüm tekneler ile resmî ve destek tekneleri, mümkünse arama kurtarma talimatları için yarış komitesinin kanalını dinler.']),
      ] }] },

    { id: 'part-4', chip: t('Part 4', 'Часть 4', 'Parte 4', 'Teil 4', 'Bölüm 4'), title: t('Part 4 · Other requirements when racing', 'Часть 4 · Другие требования в гонке', 'Parte 4 · Otros requisitos cuando se regatea', 'Teil 4 · Weitere Anforderungen in der Wettfahrt', 'Bölüm 4 · Yarışırken diğer şartlar'),
      intro: t('What a boat and her crew may and may not do while racing, unless a rule says otherwise.', 'Что можно и чего нельзя лодке и экипажу во время гонки, если правило не говорит иного.', 'Lo que un barco y su tripulación pueden y no pueden hacer mientras regatean, salvo que una regla diga otra cosa.', 'Was ein Boot und seine Crew in der Wettfahrt tun und nicht tun dürfen, sofern keine Regel etwas anderes sagt.', 'Bir kural aksini söylemedikçe, bir teknenin ve mürettebatının yarışırken neler yapıp yapamayacağı.'),
      sections: [
        sec('section-4a', ['Section A · General requirements', 'Раздел A · Общие требования', 'Sección A · Requisitos generales', 'Abschnitt A · Allgemeine Anforderungen', 'A Kısmı · Genel şartlar'], null, [
          rule('40', ['Personal flotation devices', 'Спасательные жилеты', 'Dispositivos personales de flotación', 'Schwimmwesten', 'Can yelekleri'], ['Everyone wears one, except briefly while changing clothing or personal gear, when flag Y is shown with one sound (afloat by the warning signal, for that race; ashore, for all the time afloat that day) or when a rule says so. A wetsuit or drysuit doesn’t count.', 'Все носят жилет, кроме коротких моментов смены одежды или снаряжения, когда поднят флаг Y с одним звуком (на воде не позже предупреждения — на эту гонку; на берегу — на всё время на воде в этот день) или когда этого требует правило. Гидрокостюм и сухой костюм жилетом не считаются.', 'Todos llevan uno, salvo un momento al cambiarse de ropa o de equipo personal, cuando se muestra la bandera Y con una señal sonora (a flote antes de la señal de atención, para esa regata; en tierra, durante todo el tiempo a flote ese día) o cuando una regla lo dice. Un traje de neopreno o un traje seco no cuenta.', 'Alle tragen eine, außer kurz beim Wechseln von Kleidung oder persönlicher Ausrüstung, wenn Flagge Y mit einem Schallsignal gezeigt wird (auf dem Wasser beim Warnsignal, für diese Wettfahrt; an Land für die gesamte Zeit auf dem Wasser an diesem Tag) oder wenn eine Regel es so sagt. Ein Neopren- oder Trockenanzug zählt nicht.', 'Herkes bir tane giyer; giysi ya da kişisel eşya değiştirirken kısa süreler dışında, Y bayrağı bir ses işaretiyle gösterildiğinde (suda uyarı işaretine kadar gösterilmişse o yarış için; karadaysa o gün suda geçen tüm süre için) ya da bir kural öyle diyorsa. Islak ya da kuru elbise sayılmaz.']),
          rule('41', ['Outside help', 'Посторонняя помощь', 'Ayuda externa', 'Fremde Hilfe', 'Dış yardım'], ['A boat takes no outside help, except for a crew member who is ill, injured or in danger; from the other vessel’s crew to get clear after a collision; information freely available to all boats; and unasked-for information from a disinterested source, which may be another boat in the same race.', 'Лодка не получает посторонней помощи, кроме помощи заболевшему, травмированному или находящемуся в опасности члену экипажа; помощи экипажа другого судна, чтобы разойтись после столкновения; сведений, доступных всем лодкам; и незапрошенных сведений от незаинтересованного источника, которым может быть другая лодка этой же гонки.', 'Un barco no recibe ayuda externa, salvo para un miembro de la tripulación enfermo, herido o en peligro; de la tripulación del otro buque para separarse tras una colisión; información disponible libremente para todos los barcos; e información no solicitada de una fuente desinteresada, que puede ser otro barco de la misma regata.', 'Ein Boot nimmt keine fremde Hilfe in Anspruch, außer für ein Crewmitglied, das krank, verletzt oder in Gefahr ist; von der Crew des anderen Fahrzeugs, um nach einer Kollision freizukommen; Informationen, die allen Booten frei zugänglich sind; und ungebetene Informationen aus einer unbeteiligten Quelle, die auch ein anderes Boot in derselben Wettfahrt sein kann.', 'Tekne dış yardım almaz; ancak hasta, yaralı ya da tehlikedeki bir mürettebat üyesi için; çarpışmadan sonra kurtulmak için diğer teknenin mürettebatından; tüm teknelerin serbestçe ulaşabildiği bilgiler; ve aynı yarıştaki başka bir tekne olabilen, ilgisiz bir kaynaktan istenmeden gelen bilgiler istisnadır.']),
          rule('42', ['Propulsion', 'Движущая сила', 'Propulsión', 'Antrieb', 'İtiş'], ['A boat uses only the wind and the water to change her speed. Banned: pumping, rocking, ooching, sculling, and repeated tacks or gybes unrelated to wind shifts or tactics (42.2). Allowed, among others: rolling to help steer, one pull of each sail per wave or gust to start surfing or planing, any number of pulls to start foiling, sculling to turn to close-hauled when stopped or slow above that course, and any means to help someone in danger (42.3).', 'Лодка меняет скорость только за счёт ветра и воды. Запрещены пампинг, рокинг, учинг, скаллинг и повторные повороты, не связанные со сдвигами ветра или тактикой (42.2). Разрешены, среди прочего: крен для управления, один рывок каждым парусом на волну или порыв, чтобы начать сёрфинг или глиссирование, любое число рывков для выхода на крылья, скаллинг для ухода на бейдевинд, когда лодка стоит или медленно идёт круче него, и любые средства, чтобы помочь тому, кто в опасности (42.3).', 'Un barco usa solo el viento y el agua para cambiar su velocidad. Prohibido: bombear, balancear, «ooching», remar a la espadilla, y virar o trasluchar repetidamente sin relación con las roladas del viento o la táctica (42.2). Permitido, entre otros: balancearse para ayudar a gobernar, un tirón de cada vela por ola o racha para empezar a surfear o planear, cualquier número de tirones para empezar a volar con foils, remar a la espadilla para ponerse de ceñida cuando está parado o lento por encima de ese rumbo, y cualquier medio para ayudar a alguien en peligro (42.3).', 'Ein Boot nutzt nur Wind und Wasser, um seine Geschwindigkeit zu ändern. Verboten: Pumpen, Rocken, Ooching, Wriggen sowie wiederholte Wenden oder Halsen, die nichts mit Winddrehern oder Taktik zu tun haben (42.2). Erlaubt, unter anderem: Rollen, um beim Steuern zu helfen, ein Zug an jedem Segel pro Welle oder Bö, um Gleiten oder Surfen zu beginnen, beliebig viele Züge, um ins Foilen zu kommen, Wriggen, um bei Stillstand oder langsamer Fahrt über diesem Kurs auf hoch am Wind zu drehen, und jedes Mittel, um jemandem in Gefahr zu helfen (42.3).', 'Tekne hızını değiştirmek için yalnızca rüzgârı ve suyu kullanır. Yasak: pompalama, sallanma, ooching, kürekle itme ve rüzgâr dönüşleri ya da taktikle ilgisi olmayan tekrarlı tramola ya da kavançalar (42.2). Diğerlerinin yanı sıra serbest: dümene yardım için yatırma, sörf ya da planya başlatmak için dalga ya da hamle başına her yelkende bir çekiş, foil’e kalkmak için istenen sayıda çekiş, durmuşken ya da o rotanın üstünde yavaşken orsa rotasına dönmek için kürekle itme ve tehlikedeki birine yardım için her yol (42.3).']),
          rule('43', ['Exoneration', 'Освобождение от ответственности', 'Exoneración', 'Entlastung', 'Muafiyet'], ['A boat forced to break a rule by another boat’s breach is exonerated. So is one that, sailing within the room or mark-room she is owed, breaks a Section A rule or rule 15, 16 or 31 because of an incident with the boat that owes it, and a right-of-way boat or one within her room that breaks rule 14 with no damage or injury. An exonerated boat takes no penalty.', 'Лодка, вынужденная нарушить правило из-за нарушения другой, освобождается от ответственности. Так же и лодка, которая в пределах положенного ей места нарушила правило раздела A или правила 15, 16 или 31 из-за инцидента с лодкой, обязанной это место дать, и лодка с правом дороги или в пределах своего места, нарушившая правило 14 без повреждений и травм. Освобождённая лодка наказание не выполняет.', 'Un barco obligado a infringir una regla por la infracción de otro barco queda exonerado. También lo queda el que, navegando dentro del espacio o del espacio en baliza que se le debe, infringe una regla de la sección A o la regla 15, 16 o 31 por un incidente con el barco que se lo debe, y un barco con derecho de paso, o dentro de su espacio, que infringe la regla 14 sin daño ni lesión. Un barco exonerado no cumple penalización.', 'Ein Boot, das durch den Verstoß eines anderen Boots gezwungen wird, eine Regel zu brechen, wird entlastet. Das gilt auch für eines, das innerhalb des Raums oder Bahnmarkenraums, der ihm zusteht, wegen eines Vorfalls mit dem Boot, das ihn schuldet, eine Regel aus Abschnitt A oder Regel 15, 16 oder 31 bricht, sowie für ein Boot mit Wegerecht oder eines innerhalb seines Raums, das Regel 14 ohne Schaden oder Verletzung bricht. Ein entlastetes Boot nimmt keine Strafe.', 'Başka bir teknenin ihlali yüzünden kural çiğnemek zorunda kalan tekne muaf tutulur. Borçlu olunan alan ya da şamandıra alanı içinde seyrederken, bunu borçlu olan tekneyle yaşanan bir olay yüzünden A Kısmı kurallarından birini ya da kural 15, 16 veya 31’i çiğneyen tekne de, hasar ya da yaralanma olmaksızın kural 14’ü çiğneyen geçiş hakkı sahibi ya da kendi alanı içindeki tekne de öyle. Muaf tutulan tekne ceza almaz.'], '/learn/rules#pen'),
          rule('44', ['Penalties at the time of an incident', 'Наказания в момент инцидента', 'Penalizaciones en el momento de un incidente', 'Strafen zum Zeitpunkt eines Vorfalls', 'Olay anında cezalar'], ['Two turns for a Part 2 rule, one for rule 31, unless the notice of race or sailing instructions set another penalty; for both in one incident, only the Part 2 penalty. Get well clear as soon as possible, then promptly turn the same way, each turn with one tack and one gybe. If she caused injury or serious damage, or gained a significant advantage despite the penalty, she must retire. A scoring penalty, where used, means showing a yellow flag and losing the stated points, or 20% of the Did Not Finish score.', 'Два оборота за нарушение части 2, один — за правило 31, если положение или инструкция не устанавливают иное наказание; за оба в одном инциденте — только наказание по части 2. Как можно скорее отойдите от других лодок и сразу крутитесь в одну сторону, каждый оборот — один поворот оверштаг и один фордевинд. Если лодка причинила травму или серьёзное повреждение либо несмотря на наказание получила существенное преимущество, она выходит из гонки. Штраф очками, если он применяется: жёлтый флаг и потеря указанных очков или 20% от очков за «не финишировала».', 'Dos giros por una regla de la Parte 2, uno por la regla 31, salvo que el anuncio de regata o las instrucciones de regata fijen otra penalización; si hay ambas en un incidente, solo la penalización de la Parte 2. Alejarse bien lo antes posible y luego girar de inmediato en el mismo sentido, cada giro con una virada y una trasluchada. Si causó lesión o daño grave, o ganó una ventaja significativa a pesar de la penalización, debe retirarse. Una penalización de puntuación, cuando se usa, significa mostrar una bandera amarilla y perder los puntos indicados, o el 20 % de la puntuación de No Llegó.', 'Zwei Kringel für eine Regel aus Teil 2, einen für Regel 31, es sei denn, die Ausschreibung oder die Segelanweisungen legen eine andere Strafe fest; bei beiden in einem Vorfall nur die Strafe für Teil 2. So bald wie möglich gut freikommen, dann zügig in dieselbe Richtung drehen, jeder Kringel mit einer Wende und einer Halse. Hat es Verletzung oder ernsthaften Schaden verursacht oder trotz der Strafe einen erheblichen Vorteil erlangt, muss es aufgeben. Eine Wertungsstrafe, wo sie gilt, heißt: eine gelbe Flagge zeigen und die festgelegten Punkte verlieren, oder 20 % der Punktzahl für Did Not Finish.', 'Yarış ilanı ya da yarış talimatları başka bir ceza belirlemedikçe, bir 2. Bölüm kuralı için iki dönüş, kural 31 için bir dönüş; aynı olayda ikisi birden için yalnızca 2. Bölüm cezası. Mümkün olan en kısa sürede iyice uzaklaş, ardından hemen aynı yöne dön; her dönüş bir tramola ve bir kavançadan oluşur. Yaralanmaya ya da ciddi hasara yol açtıysa ya da cezaya rağmen önemli bir avantaj elde ettiyse, çekilmelidir. Uygulanıyorsa puan cezası, sarı bayrak göstermek ve belirtilen puanı ya da Bitirmedi puanının %20’sini kaybetmek demektir.'], '/learn/rules#pen'),
          rule('45', ['Hauling out; making fast; anchoring', 'Подъём из воды; швартовка; якорь', 'Varada; amarrar; fondear', 'Aufslippen; festmachen; ankern', 'Karaya çekme; bağlama; çapa atma'], ['A boat is afloat and off moorings at her preparatory signal. After that she isn’t hauled out or made fast except to bail, reef or repair. She may anchor or the crew may stand on the bottom, but she recovers the anchor before going on unless she can’t.', 'К подготовительному сигналу лодка на плаву и не на швартовах. После этого её не поднимают из воды и не швартуют, кроме как для откачки воды, взятия рифов или ремонта. Она может стать на якорь, а экипаж — стоять на дне, но якорь нужно поднять, прежде чем продолжить гонку, если это возможно.', 'Un barco está a flote y sin amarras en su señal de preparación. Después no se vara ni se amarra, salvo para achicar, rizar o reparar. Puede fondear o la tripulación puede pisar el fondo, pero recupera el ancla antes de continuar, salvo que no pueda.', 'Ein Boot ist bei seinem Vorbereitungssignal schwimmend und von den Liegeplätzen gelöst. Danach wird es nicht aufgeslippt oder festgemacht, außer zum Lenzen, Reffen oder Reparieren. Es darf ankern oder die Crew darf auf dem Grund stehen, aber es holt den Anker ein, bevor es weitersegelt, es sei denn, es kann nicht.', 'Tekne, hazırlık işaretinde suda ve şamandırasız olmalıdır. Bundan sonra su boşaltmak, camadan almak ya da onarım yapmak dışında karaya çekilmez ya da bağlanmaz. Çapa atabilir ya da mürettebat dibe basabilir; ancak yapamıyorsa dışında, ilerlemeden önce çapayı toplar.']),
          rule('46', ['Person in charge', 'Ответственный на лодке', 'Persona al mando', 'Verantwortliche Person', 'Sorumlu kişi'], ['Each boat has on board a person in charge, named by the member or organisation that entered her.', 'На каждой лодке есть ответственный, назначенный членом клуба или организацией, заявившими лодку.', 'Cada barco lleva a bordo una persona al mando, designada por el miembro o la organización que lo inscribió.', 'Jedes Boot hat eine verantwortliche Person an Bord, die vom Mitglied oder der Organisation benannt wird, das oder die es gemeldet hat.', 'Her teknede, onu kaydeden üye ya da kuruluşun belirlediği bir sorumlu kişi bulunur.']),
          rule('47', ['Trash disposal', 'Мусор', 'Eliminación de basura', 'Müllentsorgung', 'Çöp atma'], ['Competitors and support persons never intentionally put trash in the water, at any time while afloat. The penalty may be less than disqualification.', 'Гонщики и сопровождающие лица никогда намеренно не выбрасывают мусор в воду, всё время пока находятся на воде. Наказание может быть мягче дисквалификации.', 'Los regatistas y las personas de apoyo nunca echan basura al agua intencionadamente, en ningún momento mientras están a flote. La penalización puede ser menor que la descalificación.', 'Teilnehmer und Betreuer werfen niemals absichtlich Müll ins Wasser, zu keiner Zeit auf dem Wasser. Die Strafe kann geringer sein als eine Disqualifikation.', 'Yarışçılar ve destek ekibi, suda bulundukları süre boyunca hiçbir zaman bilerek suya çöp atmaz. Ceza diskalifiyeden daha az olabilir.']),
        ]),
        sec('section-4b', ['Section B · Equipment-related requirements', 'Раздел B · Требования к снаряжению', 'Sección B · Requisitos relativos al equipo', 'Abschnitt B · Anforderungen an die Ausrüstung', 'B Kısmı · Donanıma ilişkin şartlar'], null, [
          rule('48', ['Limitations on equipment and crew', 'Ограничения на снаряжение и экипаж', 'Limitaciones al equipo y a la tripulación', 'Einschränkungen für Ausrüstung und Crew', 'Donanım ve mürettebat sınırlamaları'], ['A boat uses only the equipment on board at her preparatory signal. Nobody leaves on purpose except when ill or injured, to help someone in danger, or to swim, and anyone off the boat must be back in contact with her before she sails on to the next mark.', 'Лодка использует только снаряжение, бывшее на борту к подготовительному сигналу. Никто намеренно не покидает лодку, кроме случаев болезни, травмы, помощи тем, кто в опасности, или купания; оказавшийся за бортом должен снова коснуться лодки, прежде чем она продолжит идти к следующему знаку.', 'Un barco usa solo el equipo que lleva a bordo en su señal de preparación. Nadie lo abandona a propósito, salvo por enfermedad o lesión, para ayudar a alguien en peligro, o para nadar, y quien esté fuera del barco debe volver a estar en contacto con él antes de que siga hasta la siguiente baliza.', 'Ein Boot verwendet nur die Ausrüstung, die bei seinem Vorbereitungssignal an Bord ist. Niemand verlässt es absichtlich, außer bei Krankheit oder Verletzung, um jemandem in Gefahr zu helfen oder zum Schwimmen, und wer nicht an Bord ist, muss wieder Kontakt mit dem Boot haben, bevor es zur nächsten Marke weitersegelt.', 'Tekne, hazırlık işaretinde teknede bulunan donanımı kullanır. Hasta ya da yaralı olmak, tehlikedeki birine yardım etmek ya da yüzmek dışında hiç kimse bilerek teknesinden ayrılmaz; tekneden ayrılan herkes, tekne sonraki şamandıraya doğru yoluna devam etmeden önce onunla yeniden temas halinde olmalıdır.']),
          rule('49', ['Crew position; lifelines', 'Положение экипажа; леера', 'Posición de la tripulación; guardamancebos', 'Crewposition; Seereling', 'Mürettebat konumu; can koruma halatları'], ['No device holds the body outboard, other than hiking straps and stiffeners under the thighs. Where lifelines are required, the torso stays inside them except briefly for a necessary task, with an allowance for sitting out on boats with upper and lower lifelines, and lifelines are taut unless a rule says otherwise.', 'Никаких приспособлений для выноса тела за борт, кроме откренивающих ремней и жёстких вставок под бёдрами. Где леера обязательны, туловище остаётся внутри них, кроме коротких необходимых работ, с оговоркой для сидящих на лодках с верхним и нижним леером; леера натянуты, если правило не говорит иного.', 'Ningún dispositivo sujeta el cuerpo fuera de borda, salvo las trapas y los refuerzos bajo los muslos. Donde se exigen guardamancebos, el torso se mantiene dentro de ellos, salvo brevemente para una tarea necesaria, con una tolerancia para sentarse fuera en barcos con guardamancebos superior e inferior, y los guardamancebos están tensos salvo que una regla diga otra cosa.', 'Keine Vorrichtung hält den Körper außenbords, außer Ausreitgurte und Stützen unter den Oberschenkeln. Wo Seereling vorgeschrieben ist, bleibt der Oberkörper innerhalb davon, außer kurz für eine notwendige Aufgabe, mit einer Ausnahme zum Hinaussitzen auf Booten mit oberer und unterer Reling, und die Relings sind straff, sofern keine Regel etwas anderes sagt.', 'Vücudu dışarıda tutan hiçbir araç kullanılmaz; yalnızca ayak kayışları ve uyluk altı destekler istisnadır. Can koruma halatı zorunluysa gövde, gerekli bir iş için kısa süreler dışında halatların içinde kalır; alt ve üst halatlı teknelerde dışarı oturma için bir pay tanınır ve kural aksini söylemedikçe halatlar gergin tutulur.']),
          rule('50', ['Competitor clothing and equipment', 'Одежда и снаряжение гонщика', 'Ropa y equipo del regatista', 'Kleidung und Ausrüstung der Teilnehmer', 'Yarışçı giysisi ve donanımı'], ['Nothing is worn or carried to add weight. Clothing and equipment weigh no more than 8 kg, unless class rules or the notice of race set a lower limit or a higher one up to 10 kg, not counting a crew harness and what is worn below the knee. A harness floats, weighs up to 2 kg (4 kg if class rules allow) and releases easily. These limits don’t apply to boats that must have lifelines.', 'Ничего не надевают и не носят ради увеличения веса. Одежда и снаряжение весят не больше 8 кг, если правила класса или положение не установили меньший предел либо больший до 10 кг, не считая трапециевой обвязки и того, что носят ниже колена. Обвязка плавучая, весит до 2 кг (до 4 кг, если позволяют правила класса) и легко отсоединяется. На лодки, которым положены леера, эти пределы не распространяются.', 'No se lleva nada para añadir peso. La ropa y el equipo no pesan más de 8 kg, salvo que las reglas de clase o el anuncio de regata fijen un límite menor o uno mayor de hasta 10 kg, sin contar un arnés de tripulación ni lo que se lleva por debajo de la rodilla. Un arnés flota, pesa hasta 2 kg (4 kg si las reglas de clase lo permiten) y se suelta con facilidad. Estos límites no se aplican a los barcos que deben tener guardamancebos.', 'Nichts wird getragen oder mitgeführt, um Gewicht hinzuzufügen. Kleidung und Ausrüstung wiegen nicht mehr als 8 kg, es sei denn, Klassenregeln oder Ausschreibung setzen eine niedrigere Grenze oder eine höhere bis 10 kg, ohne Crewgurt und das, was unterhalb des Knies getragen wird. Ein Gurt schwimmt, wiegt bis zu 2 kg (4 kg, wenn die Klassenregeln es erlauben) und lässt sich leicht lösen. Diese Grenzen gelten nicht für Boote, die Relings haben müssen.', 'Ağırlık eklemek için hiçbir şey giyilmez ya da taşınmaz. Sınıf kuralları ya da yarış ilanı daha düşük bir sınır ya da 10 kg’a kadar daha yüksek bir sınır belirlemedikçe, giysi ve donanım 8 kg’dan ağır olmaz; mürettebat emniyet kemeri ve dizin altında giyilenler sayılmaz. Emniyet kemeri yüzer, 2 kg’a kadar (sınıf kuralları izin veriyorsa 4 kg) gelir ve kolayca çözülür. Bu sınırlar, can koruma halatı zorunlu teknelerde uygulanmaz.']),
          rule('51', ['Movable ballast', 'Подвижный балласт', 'Lastre móvil', 'Beweglicher Ballast', 'Hareketli balast'], ['All movable ballast, unset sails included, is properly stowed. Water, dead weight or ballast isn’t moved to change trim or stability. Floorboards, bulkheads, doors, stairs and water tanks stay in place and cabin fixtures on board. Bilge water may be bailed out.', 'Весь подвижный балласт, включая неподнятые паруса, надёжно закреплён. Воду, грузы и балласт не перемещают для изменения дифферента или остойчивости. Пайолы, переборки, двери, трапы и цистерны остаются на месте, оборудование каюты — на борту. Трюмную воду можно откачивать.', 'Todo el lastre móvil, incluidas las velas no izadas, está bien estibado. No se mueve agua, peso muerto ni lastre para cambiar el asiento o la estabilidad. Los pisos, mamparos, puertas, escaleras y tanques de agua permanecen en su sitio y los accesorios de la cabina a bordo. El agua de sentina puede achicarse.', 'Aller bewegliche Ballast, auch ungesetzte Segel, ist ordentlich verstaut. Wasser, Totgewicht oder Ballast werden nicht bewegt, um Trimm oder Stabilität zu ändern. Bodenbretter, Schotten, Türen, Treppen und Wassertanks bleiben an ihrem Platz und Kabinenausstattung bleibt an Bord. Bilgewasser darf gelenzt werden.', 'Açılmamış yelkenler dahil tüm hareketli balast düzgünce istiflenir. Su, ölü ağırlık ya da balast, trimi veya dengeyi değiştirmek için taşınmaz. Döşeme tahtaları, perdeler, kapılar, merdivenler ve su tankları yerinde kalır, kabin donanımı teknede bulunur. Sintine suyu boşaltılabilir.']),
          rule('52', ['Manual power', 'Ручная сила', 'Fuerza manual', 'Muskelkraft', 'Elle güç'], ['Rigging, spars and movable hull appendages are adjusted and worked only by the crew’s own power.', 'Такелаж, рангоут и подвижные выступающие части работают только от силы экипажа.', 'El aparejo, los palos y los apéndices móviles del casco se ajustan y manejan solo con la fuerza de la propia tripulación.', 'Rigg, Spieren und bewegliche Rumpfanhänge werden nur mit der eigenen Kraft der Crew verstellt und bedient.', 'Armada, seren ve direklerde ve hareketli gövde eklentilerinde ayar ve çalışma yalnızca mürettebatın kendi gücüyle yapılır.']),
          rule('53', ['Skin friction', 'Поверхностное трение', 'Fricción superficial', 'Hautreibung', 'Yüzey sürtünmesi'], ['A boat doesn’t release polymers or similar substances, or have specially textured surfaces, that could improve the flow of water in the boundary layer.', 'Лодка не выпускает полимеры и подобные вещества и не имеет особых текстурированных поверхностей, способных улучшить обтекание в пограничном слое.', 'Un barco no libera polímeros ni sustancias similares, ni tiene superficies con textura especial, que puedan mejorar el flujo del agua en la capa límite.', 'Ein Boot gibt keine Polymere oder ähnliche Stoffe ab und hat keine besonders strukturierten Oberflächen, die die Strömung des Wassers in der Grenzschicht verbessern könnten.', 'Tekne, sınır tabakasındaki su akışını iyileştirebilecek polimerler ya da benzeri maddeler salmaz ya da özel dokulu yüzeylere sahip olmaz.']),
          rule('54', ['Forestays and headsail tacks', 'Штаги и галсовые углы передних парусов', 'Estáis y puños de amura de las velas de proa', 'Vorstage und Vorsegelhalsen', 'Baş stayler ve flok tamaları'], ['Forestays and headsail tacks are attached about on the centreline, except a spinnaker staysail’s when the boat isn’t close-hauled.', 'Штаги и галсовые углы передних парусов крепятся примерно на диаметральной плоскости, кроме спинакер-стакселя, когда лодка идёт не в бейдевинд.', 'Los estáis y los puños de amura de las velas de proa se sujetan aproximadamente en la línea de crujía, salvo el de un foque de spinnaker cuando el barco no está de ceñida.', 'Vorstage und Halsen von Vorsegeln sind etwa in der Mittschiffslinie befestigt, außer die eines Spinnaker-Stagsegels, wenn das Boot nicht hoch am Wind ist.', 'Baş stayler ve flok tamaları yaklaşık olarak orta hatta bağlanır; tekne orsada değilken balon stayyelkenin bağlantıları istisnadır.']),
          rule('55', ['Setting and sheeting sails', 'Постановка парусов и шкоты', 'Izar y cazar velas', 'Segel setzen und schoten', 'Yelken açma ve iskotalama'], ['A new headsail or spinnaker may be set and trimmed before the old one comes down, but only one mainsail and, except when changing, one spinnaker are set at a time. One spinnaker or whisker pole is used at a time except when gybing, attached to the foremost mast. No sail is sheeted over a device that pushes the sheet or clew outboard of the hull or deck, with a few listed exceptions.', 'Новый передний парус или спинакер можно поставить и настроить до уборки старого, но поднят только один грот и, кроме момента замены, один спинакер. Используется один спинакер-гик или выстрел, кроме момента поворота фордевинд, закреплённый на передней мачте. Парус не проводят через устройство, выносящее шкот или шкотовый угол за пределы корпуса или палубы, кроме нескольких перечисленных исключений.', 'Una vela de proa o un spinnaker nuevos pueden izarse y trimarse antes de arriar el anterior, pero solo se lleva una mayor y, salvo al cambiar, un spinnaker a la vez. Se usa un solo spinnaker o tangón de foque a la vez, salvo al trasluchar, sujeto al palo más a proa. Ninguna vela se caza sobre un dispositivo que empuje la escota o el puño de escota fuera del casco o de la cubierta, con algunas excepciones enumeradas.', 'Ein neues Vorsegel oder ein neuer Spinnaker darf gesetzt und getrimmt werden, bevor das alte herunterkommt, aber es ist immer nur ein Großsegel und, außer beim Wechseln, ein Spinnaker gesetzt. Es wird jeweils nur ein Spinnaker oder Spinnakerbaum verwendet, außer beim Halsen, am vordersten Mast befestigt. Kein Segel wird über eine Vorrichtung geschotet, die die Schot oder das Schothorn außerhalb von Rumpf oder Deck drückt, mit einigen aufgeführten Ausnahmen.', 'Eski yelken inmeden yeni bir flok ya da balon açılıp trim edilebilir; ancak aynı anda yalnızca bir ana yelken ve, değiştirme sırası dışında, bir balon açık olur. Kavança dışında bir seferde yalnızca bir balon ya da bir balon sereni kullanılır ve en öndeki direğe bağlanır. Hiçbir yelken, iskotayı ya da kolayı gövde veya güvertenin dışına iten bir araç üzerinden iskotalanmaz; birkaç sayılı istisna dışında.']),
          rule('56', ['Fog signals and lights; traffic separation schemes; tracking systems', 'Туманные сигналы и огни; системы разделения движения; трекинг', 'Señales de niebla y luces; esquemas de separación de tráfico; sistemas de seguimiento', 'Nebelsignale und Lichter; Verkehrstrennungsgebiete; Trackingsysteme', 'Sis işaretleri ve ışıklar; trafik ayırma düzenleri; takip sistemleri'], ['When equipped, a boat sounds fog signals and shows lights as the collision regulations or government rules require, and follows rule 10 of the collision regulations on traffic separation schemes. A required AIS or tracking device is never switched off or deliberately made less effective.', 'Если есть оборудование, лодка подаёт туманные сигналы и несёт огни по МППСС или государственным правилам и соблюдает правило 10 МППСС о системах разделения движения. Обязательный АИС или трекер нельзя отключать или намеренно ухудшать его работу.', 'Cuando está equipado, un barco hace las señales de niebla y muestra las luces que exige el reglamento para prevenir los abordajes o las reglas del gobierno, y sigue la regla 10 de ese reglamento sobre los esquemas de separación de tráfico. Un dispositivo AIS o de seguimiento exigido nunca se apaga ni se hace menos eficaz deliberadamente.', 'Wenn ein Boot ausgerüstet ist, gibt es Nebelsignale und zeigt Lichter, wie es die Kollisionsverhütungsregeln oder staatliche Vorschriften verlangen, und befolgt Regel 10 der Kollisionsverhütungsregeln zu Verkehrstrennungsgebieten. Ein vorgeschriebenes AIS- oder Trackinggerät wird nie ausgeschaltet oder absichtlich in seiner Wirkung gemindert.', 'Donanımı varsa tekne, denizde çatışmayı önleme tüzüğünün ya da devlet kurallarının gerektirdiği biçimde sis işareti verir ve ışık gösterir; trafik ayırma düzenlerinde tüzüğün 10. kuralına uyar. Zorunlu bir AIS ya da takip cihazı hiçbir zaman kapatılmaz ya da bilerek etkisiz hale getirilmez.']),
        ]),
      ] },

    { id: 'part-5', chip: t('Part 5', 'Часть 5', 'Parte 5', 'Teil 5', 'Bölüm 5'), title: t('Part 5 · Protests, redress, hearings, misconduct and appeals', 'Часть 5 · Протесты, исправление результата, рассмотрения, проступки и апелляции', 'Parte 5 · Protestas, reparación, audiencias, mala conducta y apelaciones', 'Teil 5 · Proteste, Wiedergutmachung, Verhandlungen, Fehlverhalten und Berufungen', 'Bölüm 5 · Protestolar, tazmin, duruşmalar, kötü davranış ve itirazlar'),
      intro: t('What happens after the race when boats disagree, when a boat was wronged, or when someone behaves badly.', 'Что происходит после гонки, когда лодки не согласны друг с другом, когда лодку обидели или кто-то повёл себя недостойно.', 'Lo que ocurre después de la regata cuando los barcos no se ponen de acuerdo, cuando un barco fue perjudicado o cuando alguien se comporta mal.', 'Was nach der Wettfahrt geschieht, wenn Boote uneins sind, wenn ein Boot benachteiligt wurde oder wenn sich jemand schlecht benimmt.', 'Yarıştan sonra tekneler anlaşamadığında, bir tekne haksızlığa uğradığında ya da biri kötü davrandığında neler olduğu.'),
      sections: [
        sec('section-5a', ['Section A · Protests; redress; support persons', 'Раздел A · Протесты; исправление результата; сопровождающие лица', 'Sección A · Protestas; reparación; personas de apoyo', 'Abschnitt A · Proteste; Wiedergutmachung; Betreuer', 'A Kısmı · Protestolar; tazmin; destek ekibi'], null, [
          rule('60', ['Protests', 'Протесты', 'Protestas', 'Proteste', 'Protestolar'], ['A boat or a committee may protest a boat. A boat hails “Protest” at the first reasonable opportunity and, if longer than 6 metres, also flies a red flag until she stops racing. The written protest reaches the race office within two hours of the last boat finishing, unless the sailing instructions say otherwise. A protest about Part 2 or rule 31 is valid only from a boat that was involved and saw the incident. A boat found to have broken a rule is disqualified, unless she is exonerated, has already taken a penalty or another penalty applies.', 'Лодка или комитет могут опротестовать лодку. Лодка окликает «Протест» при первой разумной возможности и, если длиннее 6 метров, ещё поднимает красный флаг до конца гонки. Письменный протест подают в офис гонки в течение двух часов после финиша последней лодки, если инструкция не говорит иного. Протест по части 2 или правилу 31 действителен только от лодки, которая участвовала в инциденте и видела его. Лодку, признанную нарушившей правило, дисквалифицируют, если она не освобождена от ответственности, не выполнила наказание и к ней не применяется другое наказание.', 'Un barco o un comité pueden protestar a un barco. Un barco grita «Protesto» en la primera oportunidad razonable y, si mide más de 6 metros, iza además una bandera roja hasta que deja de regatear. La protesta escrita llega a la oficina de regatas dentro de las dos horas posteriores a la llegada del último barco, salvo que las instrucciones de regata digan otra cosa. Una protesta sobre la Parte 2 o la regla 31 es válida solo si la presenta un barco que estuvo implicado y vio el incidente. Un barco al que se halla culpable de infringir una regla es descalificado, salvo que esté exonerado, ya haya cumplido una penalización o se aplique otra penalización.', 'Ein Boot oder ein Komitee darf ein Boot protestieren. Ein Boot ruft bei der ersten vernünftigen Gelegenheit „Protest“ und zeigt, wenn es länger als 6 Meter ist, auch eine rote Flagge, bis es die Wettfahrt beendet. Der schriftliche Protest geht innerhalb von zwei Stunden nach dem Zieleinlauf des letzten Boots im Wettfahrtbüro ein, sofern die Segelanweisungen nichts anderes sagen. Ein Protest zu Teil 2 oder Regel 31 ist nur gültig von einem Boot, das beteiligt war und den Vorfall gesehen hat. Ein Boot, das eine Regel gebrochen hat, wird disqualifiziert, es sei denn, es wird entlastet, hat bereits eine Strafe genommen oder es gilt eine andere Strafe.', 'Bir tekne ya da bir komite bir tekneyi protesto edebilir. Tekne ilk makul fırsatta “Protesto” diye seslenir ve 6 metreden uzunsa yarışmayı bırakana kadar kırmızı bayrak da açar. Yazılı protesto, yarış talimatları başka türlü söylemedikçe, son tekne bitirdikten sonra iki saat içinde yarış ofisine ulaşır. 2. Bölüm ya da kural 31 hakkındaki protesto, yalnızca olaya karışmış ve olayı görmüş bir tekneden geçerlidir. Kural çiğnediği saptanan tekne, muaf tutulmadıkça, zaten ceza yapmadıkça ya da başka bir ceza uygulanmadıkça diskalifiye edilir.']),
          rule('61', ['Redress', 'Исправление результата', 'Reparación', 'Wiedergutmachung', 'Tazmin'], ['A boat is entitled to redress when her score is made significantly worse, through no fault of her own, by an improper action or omission of a committee or the organisers, by injury or damage from a boat breaking Part 2 or a vessel that should have kept clear, by giving help under rule 1.1, or by another boat’s action that led to a penalty under rule 2 or a penalty or warning under rule 69. She asks in writing, generally within the protest time limit, and the protest committee makes as fair an arrangement as it can for all boats affected.', 'Лодка имеет право на исправление результата, если её очки существенно ухудшились не по её вине: из-за неправильного действия или бездействия комитета либо организатора, травмы или повреждения от лодки, нарушившей часть 2, или судна, обязанного уступать, из-за помощи по правилу 1.1 либо из-за действий другой лодки, за которые назначено наказание по правилу 2 или наказание либо предупреждение по правилу 69. Запрос подают письменно, как правило в срок подачи протеста, а протестовый комитет принимает самое справедливое решение для всех затронутых лодок.', 'Un barco tiene derecho a reparación cuando su puntuación empeora de forma significativa, sin culpa suya, por una acción u omisión indebida de un comité o de los organizadores, por lesión o daño causados por un barco que infringe la Parte 2 o por un buque que debía mantenerse separado, por prestar ayuda conforme a la regla 1.1, o por una acción de otro barco que llevó a una penalización conforme a la regla 2 o a una penalización o advertencia conforme a la regla 69. La pide por escrito, por lo general dentro del plazo de protesta, y el comité de protestas hace el arreglo más equitativo posible para todos los barcos afectados.', 'Ein Boot hat Anspruch auf Wiedergutmachung, wenn seine Wertung ohne eigenes Verschulden erheblich verschlechtert wird, durch eine unzulässige Handlung oder Unterlassung eines Komitees oder der Veranstalter, durch Verletzung oder Schaden durch ein Boot, das Teil 2 bricht, oder ein Fahrzeug, das sich hätte freihalten müssen, durch Hilfeleistung nach Regel 1.1 oder durch die Handlung eines anderen Boots, die zu einer Strafe nach Regel 2 oder zu einer Strafe oder Verwarnung nach Regel 69 geführt hat. Es beantragt sie schriftlich, in der Regel innerhalb der Protestfrist, und das Protestkomitee trifft eine möglichst faire Regelung für alle betroffenen Boote.', 'Bir tekne, puanı kendi kusuru olmaksızın ciddi biçimde kötüleştiğinde tazmin hakkı kazanır: bir komitenin ya da organizatörlerin uygunsuz bir eylemi veya ihmali, 2. Bölümü çiğneyen bir tekneden ya da uzak durması gereken bir tekneden gelen yaralanma veya hasar, kural 1.1 uyarınca yardım verme ya da başka bir teknenin kural 2 uyarınca cezaya ya da kural 69 uyarınca ceza veya uyarıya yol açan eylemi nedeniyle. Genellikle protesto süre sınırı içinde yazılı olarak ister; protesto komitesi etkilenen tüm tekneler için elinden geldiğince adil bir düzenleme yapar.']),
          rule('62', ['Support persons', 'Сопровождающие лица', 'Personas de apoyo', 'Betreuer', 'Destek ekibi'], ['The protest committee may hear whether a support person broke a rule. It may warn them, exclude them from the event or venue or take other action, and may change the score of a boat that gained an advantage from the breach, up to disqualification in one race.', 'Протестовый комитет может рассмотреть, нарушило ли сопровождающее лицо правило. Он может вынести предупреждение, отстранить от соревнования или места его проведения либо принять другие меры и изменить очки лодки, получившей преимущество от нарушения, вплоть до дисквалификации в одной гонке.', 'El comité de protestas puede juzgar si una persona de apoyo infringió una regla. Puede advertirla, excluirla del evento o de la sede o tomar otras medidas, y puede cambiar la puntuación de un barco que ganó una ventaja por la infracción, hasta la descalificación en una regata.', 'Das Protestkomitee darf verhandeln, ob ein Betreuer eine Regel gebrochen hat. Es darf ihn verwarnen, von der Veranstaltung oder vom Revier ausschließen oder andere Maßnahmen ergreifen und darf die Wertung eines Boots ändern, das durch den Verstoß einen Vorteil erlangt hat, bis hin zur Disqualifikation in einer Wettfahrt.', 'Protesto komitesi, bir destek ekibi üyesinin kural çiğneyip çiğnemediğini görebilir. Onları uyarabilir, etkinlikten ya da mekândan dışlayabilir ya da başka işlem yapabilir; ihlalden avantaj elde eden bir teknenin puanını, bir yarışta diskalifiyeye kadar değiştirebilir.']),
        ]),
        sec('section-5b', ['Section B · Hearings and making decisions', 'Раздел B · Рассмотрения и решения', 'Sección B · Audiencias y toma de decisiones', 'Abschnitt B · Verhandlungen und Entscheidungen', 'B Kısmı · Duruşmalar ve karar verme'], null, [
          rule('63', ['Conduct of hearings', 'Проведение рассмотрений', 'Conducción de las audiencias', 'Durchführung von Verhandlungen', 'Duruşmaların yürütülmesi'], ['Parties are told the time and place, see the papers, get reasonable time to prepare, may have a representative and may question anyone giving evidence. A committee member with a conflict of interest stands aside unless the parties consent or it isn’t significant. The committee first decides validity, then takes evidence, finds the facts on the balance of probabilities and decides by majority. A party may ask for the decision in writing within seven days, and for a reopening within 24 hours of being told of it, or sooner on the last day of racing.', 'Стороны узнают время и место, знакомятся с документами, получают разумное время на подготовку, могут иметь представителя и задавать вопросы всем, кто даёт показания. Член комитета с конфликтом интересов отстраняется, если стороны не согласны или конфликт существенный. Комитет сначала решает вопрос о действительности, затем заслушивает показания, устанавливает факты по балансу вероятностей и решает большинством голосов. Сторона может запросить решение письменно в течение семи дней и попросить о повторном рассмотрении в течение 24 часов после объявления решения, а в последний день гонок — раньше.', 'A las partes se les informa de la hora y el lugar, ven los documentos, tienen tiempo razonable para prepararse, pueden tener un representante y pueden interrogar a quien aporte pruebas. Un miembro del comité con conflicto de intereses se aparta, salvo que las partes consientan o no sea significativo. El comité decide primero la validez, luego recibe las pruebas, establece los hechos según el balance de probabilidades y decide por mayoría. Una parte puede pedir la decisión por escrito en el plazo de siete días, y la reapertura dentro de las 24 horas desde que se le informó de ella, o antes en el último día de regatas.', 'Die Parteien erfahren Zeit und Ort, sehen die Unterlagen, bekommen angemessene Zeit zur Vorbereitung, dürfen einen Vertreter haben und jeden befragen, der Zeugnis gibt. Ein Komiteemitglied mit einem Interessenkonflikt tritt zurück, es sei denn, die Parteien stimmen zu oder er ist nicht erheblich. Das Komitee entscheidet zuerst über die Gültigkeit, erhebt dann Beweise, stellt die Tatsachen nach Wahrscheinlichkeit fest und entscheidet mit Mehrheit. Eine Partei darf innerhalb von sieben Tagen die Entscheidung schriftlich verlangen und innerhalb von 24 Stunden nach deren Bekanntgabe eine Wiedereröffnung, am letzten Wettfahrttag auch früher.', 'Taraflara zaman ve yer bildirilir, belgeleri görürler, hazırlanmak için makul süre alırlar, bir temsilci bulundurabilirler ve delil sunan herkese soru sorabilirler. Çıkar çatışması olan bir komite üyesi, taraflar razı olmadıkça ya da çatışma önemli değilse kenara çekilir. Komite önce geçerliliğe karar verir, sonra delilleri dinler, olguları olasılıkların dengesine göre saptar ve oy çokluğuyla karar verir. Bir taraf kararın yazılı olarak verilmesini yedi gün içinde, duruşmanın yeniden açılmasını da öğrenmesinden itibaren 24 saat içinde ya da yarışların son gününde daha kısa sürede isteyebilir.']),
          rule('64', ['Discretionary penalties', 'Дискреционные наказания', 'Penalizaciones discrecionales', 'Ermessensstrafen', 'Takdire bağlı cezalar'], ['When a boat reports within the protest time limit that she broke a rule open to a discretionary penalty, the protest committee sets the penalty after considering the evidence. No hearing is needed.', 'Если лодка в срок подачи протеста сообщает, что нарушила правило с дискреционным наказанием, протестовый комитет назначает наказание, изучив доказательства. Рассмотрение не требуется.', 'Cuando un barco comunica dentro del plazo de protesta que infringió una regla sujeta a penalización discrecional, el comité de protestas fija la penalización tras considerar las pruebas. No hace falta audiencia.', 'Meldet ein Boot innerhalb der Protestfrist, dass es eine Regel gebrochen hat, die einer Ermessensstrafe unterliegt, legt das Protestkomitee die Strafe nach Prüfung der Beweise fest. Eine Verhandlung ist nicht nötig.', 'Bir tekne protesto süre sınırı içinde, takdire bağlı cezaya açık bir kuralı çiğnediğini bildirdiğinde, protesto komitesi delilleri değerlendirdikten sonra cezayı belirler. Duruşma gerekmez.']),
          rule('65', ['Legal liability and costs', 'Юридическая ответственность и расходы', 'Responsabilidad legal y costes', 'Haftung und Kosten', 'Hukuki sorumluluk ve masraflar'], ['Legal liability and claims for damages are left to national prescriptions. The unsuccessful party pays measurement costs in a protest about a class rule, unless the protest committee decides otherwise.', 'Вопросы юридической ответственности и возмещения ущерба решаются предписаниями национальной федерации. Расходы на обмер при протесте по правилам класса оплачивает проигравшая сторона, если протестовый комитет не решит иначе.', 'La responsabilidad legal y las reclamaciones por daños se dejan a las prescripciones nacionales. La parte que pierde paga los costes de medición en una protesta sobre una regla de clase, salvo que el comité de protestas decida otra cosa.', 'Haftung und Schadensersatzansprüche richten sich nach den nationalen Vorschriften. Die unterlegene Partei trägt in einem Protest über eine Klassenregel die Vermessungskosten, es sei denn, das Protestkomitee entscheidet anders.', 'Hukuki sorumluluk ve zarar tazmini talepleri ulusal düzenlemelere bırakılır. Bir sınıf kuralı hakkındaki protestoda ölçüm masraflarını haksız çıkan taraf öder; protesto komitesi başka türlü karar vermedikçe.']),
        ]),
        sec('section-5c', ['Section C · Misconduct', 'Раздел C · Проступки', 'Sección C · Mala conducta', 'Abschnitt C · Fehlverhalten', 'C Kısmı · Kötü davranış'], null, [
          rule('69', ['Misconduct', 'Проступок', 'Mala conducta', 'Fehlverhalten', 'Kötü davranış'], ['Conduct that breaches good manners, sportsmanship or ethics, or may bring the sport into disrepute. An allegation isn’t grounds for a protest: a protest committee of at least three may investigate and hold a hearing, and may warn, change scores, disqualify or exclude a person from the event, and report to the national authority or World Sailing, which may add further penalties, including suspension.', 'Поведение, нарушающее правила приличия, спортивные или этические нормы либо способное опорочить спорт. Обвинение не основание для протеста: протестовый комитет не менее чем из трёх человек может провести расследование и рассмотрение, вынести предупреждение, изменить очки, дисквалифицировать или отстранить от соревнования и сообщить национальной федерации или World Sailing, а те могут добавить наказания вплоть до отстранения от спорта.', 'Conducta que infringe las buenas maneras, la deportividad o la ética, o que puede desprestigiar al deporte. Una acusación no es motivo de protesta: un comité de protestas de al menos tres miembros puede investigar y celebrar una audiencia, y puede advertir, cambiar puntuaciones, descalificar o excluir a una persona del evento, e informar a la autoridad nacional o a World Sailing, que pueden añadir otras penalizaciones, incluida la suspensión.', 'Verhalten, das gegen gute Manieren, Sportlichkeit oder Ethik verstößt oder den Sport in Verruf bringen kann. Ein Vorwurf ist kein Grund für einen Protest: Ein Protestkomitee aus mindestens drei Personen darf ermitteln und verhandeln und darf verwarnen, Wertungen ändern, disqualifizieren oder eine Person von der Veranstaltung ausschließen sowie an die nationale Vereinigung oder World Sailing melden, die weitere Strafen verhängen können, bis hin zur Sperre.', 'Görgü kurallarını, sportmenliği ya da etiği ihlal eden ya da spora zarar verebilecek davranış. İddia, protesto gerekçesi değildir: en az üç kişilik bir protesto komitesi soruşturabilir ve duruşma yapabilir; uyarabilir, puanları değiştirebilir, diskalifiye edebilir ya da bir kişiyi etkinlikten dışlayabilir ve ulusal otoriteye ya da World Sailing’e bildirebilir; onlar da uzaklaştırma dahil başka cezalar ekleyebilir.']),
        ]),
        sec('section-5d', ['Section D · Appeals', 'Раздел D · Апелляции', 'Sección D · Apelaciones', 'Abschnitt D · Berufungen', 'D Kısmı · İtirazlar'], null, [
          rule('70', ['Appeals and requests to a national authority', 'Апелляции и запросы в национальную федерацию', 'Apelaciones y solicitudes a una autoridad nacional', 'Berufungen und Anfragen an eine nationale Vereinigung', 'Ulusal otoriteye itirazlar ve talepler'], ['A party may appeal a protest committee’s decision or procedures, but not the facts found, to the national authority, and may also appeal a failure to hold a hearing or decide. There is no appeal from a properly constituted international jury, or in a few other cases if the notice of race or sailing instructions say so. A protest committee may ask the national authority to confirm or correct its decision.', 'Сторона может обжаловать решение или процедуру протестового комитета в национальной федерации, но не установленные факты; обжаловать можно и отказ провести рассмотрение или принять решение. Решения должным образом сформированного международного жюри и в ряде других случаев, указанных в положении или инструкции, не обжалуются. Протестовый комитет может попросить федерацию подтвердить или исправить его решение.', 'Una parte puede apelar ante la autoridad nacional la decisión o los procedimientos de un comité de protestas, pero no los hechos establecidos, y también puede apelar por no haberse celebrado una audiencia o no haberse decidido. No hay apelación contra un jurado internacional debidamente constituido, ni en algunos otros casos si el anuncio de regata o las instrucciones de regata lo dicen. Un comité de protestas puede pedir a la autoridad nacional que confirme o corrija su decisión.', 'Eine Partei darf gegen die Entscheidung oder das Verfahren eines Protestkomitees bei der nationalen Vereinigung Berufung einlegen, aber nicht gegen die festgestellten Tatsachen, und auch gegen das Unterlassen einer Verhandlung oder Entscheidung. Gegen eine ordnungsgemäß gebildete internationale Jury gibt es keine Berufung, ebenso in einigen anderen Fällen, wenn Ausschreibung oder Segelanweisungen es sagen. Ein Protestkomitee darf die nationale Vereinigung bitten, seine Entscheidung zu bestätigen oder zu korrigieren.', 'Bir taraf, protesto komitesinin kararına ya da usullerine, saptanan olgular dışında, ulusal otoriteye itiraz edebilir; duruşma yapılmamasına ya da karar verilmemesine de itiraz edebilir. Usulüne uygun kurulmuş uluslararası bir jürinin kararlarına karşı ya da yarış ilanı veya yelken talimatları öyle diyorsa birkaç başka durumda itiraz yolu yoktur. Protesto komitesi, ulusal otoriteden kararını onaylamasını ya da düzeltmesini isteyebilir.']),
          rule('71', ['National authority decisions', 'Решения национальной федерации', 'Decisiones de la autoridad nacional', 'Entscheidungen der nationalen Vereinigung', 'Ulusal otorite kararları'], ['The national authority accepts the facts found unless rule R5 applies. It may uphold, change or reverse the decision, or order a hearing reopened or held anew. Anyone with a conflict of interest, or who sat on the protest committee, takes no part. Its decision is final.', 'Федерация принимает установленные факты, если не применяется правило R5. Она может оставить решение в силе, изменить или отменить его либо назначить повторное или новое рассмотрение. Люди с конфликтом интересов и члены того протестового комитета не участвуют. Её решение окончательно.', 'La autoridad nacional acepta los hechos establecidos, salvo que se aplique la regla R5. Puede confirmar, cambiar o revocar la decisión, u ordenar que se reabra una audiencia o se celebre de nuevo. Quien tenga un conflicto de intereses, o haya formado parte del comité de protestas, no participa. Su decisión es definitiva.', 'Die nationale Vereinigung übernimmt die festgestellten Tatsachen, es sei denn, Regel R5 gilt. Sie darf die Entscheidung bestätigen, ändern oder aufheben oder anordnen, dass eine Verhandlung wiedereröffnet oder neu geführt wird. Wer einen Interessenkonflikt hat oder im Protestkomitee saß, nimmt nicht teil. Ihre Entscheidung ist endgültig.', 'Ulusal otorite, kural R5 uygulanmadıkça saptanan olguları kabul eder. Kararı onaylayabilir, değiştirebilir ya da bozabilir ya da bir duruşmanın yeniden açılmasını veya baştan yapılmasını isteyebilir. Çıkar çatışması olan ya da protesto komitesinde yer almış kimse işe katılmaz. Kararı kesindir.']),
          rule('72', ['Interpretations', 'Толкования', 'Interpretaciones', 'Auslegungen', 'Yorumlar'], ['A club or other affiliated organisation may ask the national authority to interpret the rules, as long as no appealable protest committee decision is involved. An interpretation doesn’t change an earlier decision.', 'Клуб или другая аффилированная организация может запросить у федерации толкование правил, если дело не касается решения протестового комитета, которое можно обжаловать. Толкование не меняет прежнее решение.', 'Un club u otra organización afiliada puede pedir a la autoridad nacional que interprete las reglas, siempre que no esté implicada una decisión apelable de un comité de protestas. Una interpretación no cambia una decisión anterior.', 'Ein Club oder eine andere angeschlossene Organisation darf die nationale Vereinigung bitten, die Regeln auszulegen, solange keine berufungsfähige Entscheidung eines Protestkomitees betroffen ist. Eine Auslegung ändert keine frühere Entscheidung.', 'Bir kulüp ya da bağlı başka bir kuruluş, itiraza açık bir protesto komitesi kararı söz konusu olmadığı sürece, ulusal otoriteden kuralları yorumlamasını isteyebilir. Bir yorum, daha önceki bir kararı değiştirmez.']),
        ]),
      ] },

    { id: 'part-6', chip: t('Part 6', 'Часть 6', 'Parte 6', 'Teil 6', 'Bölüm 6'), title: t('Part 6 · Entry and qualification', 'Часть 6 · Заявка и допуск', 'Parte 6 · Inscripción y clasificación', 'Teil 6 · Meldung und Qualifikation', 'Bölüm 6 · Kayıt ve yeterlilik'),
      intro: t('Who may enter an event, and what a boat must have in order.', 'Кто может заявиться на соревнование и что должно быть в порядке у лодки.', 'Quién puede inscribirse en un evento y qué debe tener en regla un barco.', 'Wer an einer Veranstaltung teilnehmen darf und was ein Boot in Ordnung haben muss.', 'Bir etkinliğe kimin katılabileceği ve bir teknenin neleri tam bulundurması gerektiği.'),
      sections: [{ entries: [
        rule('75', ['Entering an event', 'Заявка на соревнование', 'Inscribirse en un evento', 'Zu einer Veranstaltung melden', 'Etkinliğe kayıt'], ['A boat meets the organisers’ requirements and is entered by a member of a club or organisation affiliated to a World Sailing member national authority, by such a club or organisation, or by a member of that national authority.', 'Лодка выполняет требования организатора, и её заявляет член клуба или организации, входящей в национальную федерацию — члена World Sailing, сам такой клуб или организация либо член этой федерации.', 'Un barco cumple los requisitos de los organizadores y lo inscribe un miembro de un club u organización afiliados a una autoridad nacional miembro de World Sailing, un club u organización de ese tipo, o un miembro de esa autoridad nacional.', 'Ein Boot erfüllt die Anforderungen der Veranstalter und wird gemeldet von einem Mitglied eines Clubs oder einer Organisation, die einer nationalen Vereinigung von World Sailing angeschlossen ist, von einem solchen Club oder einer solchen Organisation oder von einem Mitglied dieser nationalen Vereinigung.', 'Tekne, organizatörlerin şartlarını karşılar ve bir World Sailing üyesi ulusal otoriteye bağlı bir kulüp ya da kuruluşun üyesi, böyle bir kulüp ya da kuruluş ya da o ulusal otoritenin üyesi tarafından kaydedilir.']),
        rule('76', ['Exclusion of boats or competitors', 'Отказ в участии', 'Exclusión de barcos o regatistas', 'Ausschluss von Booten oder Teilnehmern', 'Tekne ya da yarışçıların dışlanması'], ['The organisers or the race committee may reject an entry or exclude a competitor before the first race, for a proper reason given in writing on request. They may not do so because of advertising that meets the code or, at world and continental championships, for an entry within stated quotas without the class’s or World Sailing’s approval. A boat that thinks the decision improper may ask for redress.', 'Организатор или гоночный комитет могут отклонить заявку или отстранить гонщика до первой гонки по обоснованной причине, сообщаемой письменно по запросу. Нельзя делать это из-за рекламы, соответствующей кодексу, а на чемпионатах мира и континентов — без согласия класса или World Sailing, если заявка в пределах квот. Считающая отказ неправильным лодка может запросить исправление результата.', 'Los organizadores o el comité de regatas pueden rechazar una inscripción o excluir a un regatista antes de la primera regata, por un motivo adecuado dado por escrito si se solicita. No pueden hacerlo por publicidad que cumpla el código ni, en campeonatos mundiales y continentales, por una inscripción dentro de las cuotas establecidas sin la aprobación de la clase o de World Sailing. Un barco que crea que la decisión es indebida puede pedir reparación.', 'Die Veranstalter oder die Wettfahrtleitung dürfen vor der ersten Wettfahrt eine Meldung ablehnen oder einen Teilnehmer ausschließen, aus einem triftigen Grund, der auf Verlangen schriftlich genannt wird. Sie dürfen das nicht wegen Werbung tun, die dem Code entspricht, oder bei Welt- und Kontinentalmeisterschaften für eine Meldung innerhalb festgelegter Quoten ohne Zustimmung der Klasse oder von World Sailing. Ein Boot, das die Entscheidung für unzulässig hält, darf Wiedergutmachung beantragen.', 'Organizatörler ya da yarış komitesi, ilk yarıştan önce uygun bir gerekçeyle, istenirse yazılı verilmek üzere, bir kaydı reddedebilir ya da bir yarışçıyı dışlayabilir. Koda uygun reklam nedeniyle ya da dünya ve kıta şampiyonalarında, belirtilen kotalar içindeki bir kayıt için sınıfın veya World Sailing’in onayı olmadan bunu yapamazlar. Kararı uygunsuz bulan tekne tazmin isteyebilir.']),
        rule('77', ['Identification on sails', 'Опознавательные знаки на парусах', 'Identificación en las velas', 'Kennzeichnung auf den Segeln', 'Yelkenlerde tanıtma'], ['A boat carries class insignia, national letters and numbers on her sails as Appendix G requires.', 'На парусах лодки — эмблема класса, национальные буквы и номера по приложению G.', 'Un barco lleva en sus velas el emblema de clase, las letras nacionales y los números como exige el Apéndice G.', 'Ein Boot führt Klassenzeichen, Nationalitätszeichen und Segelnummern auf seinen Segeln, wie es Anhang G verlangt.', 'Tekne, sınıf amblemini, ulusal harfleri ve numaraları Ek G’nin gerektirdiği biçimde yelkenlerinde taşır.']),
        rule('78', ['Compliance with class rules; certificates', 'Соответствие правилам класса; сертификаты', 'Cumplimiento de las reglas de clase; certificados', 'Einhaltung der Klassenregeln; Zertifikate', 'Sınıf kurallarına uyum; sertifikalar'], ['While racing, the owner and the person in charge keep the boat within her class rules and her certificate valid. If a required certificate can’t be shown, she may race on a signed statement that one exists, and must produce it before the last day of the event or of the first series, whichever is earlier, or be disqualified from all races.', 'Во время гонки владелец и ответственный следят, чтобы лодка соответствовала правилам класса, а сертификат был действителен. Если нужный сертификат нельзя предъявить, лодка может гоняться по подписанному заявлению о том, что он есть, и должна предъявить его до последнего дня соревнования или первой серии — что раньше, иначе её дисквалифицируют во всех гонках.', 'Mientras regatean, el propietario y la persona al mando mantienen el barco dentro de sus reglas de clase y con el certificado en vigor. Si no se puede mostrar un certificado exigido, el barco puede regatear con una declaración firmada de que existe, y debe presentarlo antes del último día del evento o de la primera serie, lo que ocurra antes, o será descalificado de todas las regatas.', 'In der Wettfahrt halten der Eigner und die verantwortliche Person das Boot innerhalb seiner Klassenregeln und sein Zertifikat gültig. Kann ein vorgeschriebenes Zertifikat nicht vorgelegt werden, darf es mit einer unterschriebenen Erklärung segeln, dass eines existiert, und muss es vor dem letzten Tag der Veranstaltung oder der ersten Serie vorlegen, je nachdem, was früher ist, oder wird in allen Wettfahrten disqualifiziert.', 'Yarışırken tekne sahibi ve sorumlu kişi, tekneyi sınıf kuralları içinde tutar ve sertifikasının geçerli olmasını sağlar. Gerekli bir sertifika gösterilemiyorsa tekne, var olduğuna dair imzalı bir beyanla yarışabilir ve etkinliğin ya da ilk serinin son gününden önce, hangisi daha erkense, onu ibraz etmelidir; yoksa tüm yarışlardan diskalifiye edilir.']),
        rule('79', ['Categorization', 'Категории гонщиков', 'Categorización', 'Kategorisierung', 'Sınıflandırma'], ['If the notice of race or class rules require sailor categories, they are given under the World Sailing Sailor Categorization Code.', 'Если положение или правила класса требуют категории гонщиков, их присваивают по кодексу World Sailing о категориях.', 'Si el anuncio de regata o las reglas de clase exigen categorías de regatistas, se asignan conforme al Código de Categorización de Regatistas de World Sailing.', 'Verlangen Ausschreibung oder Klassenregeln Seglerkategorien, werden sie nach dem World Sailing Sailor Categorization Code vergeben.', 'Yarış ilanı ya da sınıf kuralları yelkenci kategorileri gerektiriyorsa, bunlar World Sailing Yelkenci Sınıflandırma Kodu uyarınca verilir.']),
        rule('80', ['Rescheduled event', 'Перенос соревнования', 'Evento reprogramado', 'Verlegte Veranstaltung', 'Ertelenen etkinlik'], ['If an event moves to new dates, all entered boats are told, and the race committee may accept new entries that meet every requirement but the original deadline.', 'Если соревнование переносят на другие даты, всем заявленным лодкам сообщают об этом, а гоночный комитет может принять новые заявки, отвечающие всем требованиям, кроме прежнего срока.', 'Si un evento pasa a nuevas fechas, se informa a todos los barcos inscritos, y el comité de regatas puede aceptar nuevas inscripciones que cumplan todos los requisitos salvo el plazo original.', 'Wird eine Veranstaltung auf neue Termine verlegt, werden alle gemeldeten Boote informiert, und die Wettfahrtleitung darf neue Meldungen annehmen, die alle Anforderungen bis auf die ursprüngliche Frist erfüllen.', 'Bir etkinlik yeni tarihlere kaydırılırsa kayıtlı tüm tekneler bilgilendirilir; yarış komitesi, asıl son başvuru tarihi dışında her şartı karşılayan yeni kayıtları kabul edebilir.']),
      ] }] },

    { id: 'part-7', chip: t('Part 7', 'Часть 7', 'Parte 7', 'Teil 7', 'Bölüm 7'), title: t('Part 7 · Event organization', 'Часть 7 · Организация соревнования', 'Parte 7 · Organización del evento', 'Teil 7 · Organisation einer Veranstaltung', 'Bölüm 7 · Etkinlik organizasyonu'),
      intro: t('Who runs an event, who judges it and how its rules may be changed.', 'Кто проводит соревнование, кто его судит и как можно менять его правила.', 'Quién dirige un evento, quién lo juzga y cómo pueden cambiarse sus reglas.', 'Wer eine Veranstaltung durchführt, wer sie beurteilt und wie ihre Regeln geändert werden dürfen.', 'Etkinliği kimin yürüttüğü, kimin yargıladığı ve kurallarının nasıl değiştirilebileceği.'),
      sections: [{ entries: [
        rule('85', ['Changes to rules', 'Изменения правил', 'Cambios a las reglas', 'Änderungen an Regeln', 'Kuralların değiştirilmesi'], ['A change must name the rule and state the change, whether it adds to the rule, deletes from it or alters it. Each kind of rule can be changed only by the route set for it.', 'Изменение должно назвать правило и указать, что меняется: что добавлено, удалено или изменено. Каждый вид правил меняют только установленным для него способом.', 'Un cambio debe nombrar la regla y expresar el cambio, ya sea que añada a la regla, suprima de ella o la altere. Cada tipo de regla solo puede cambiarse por la vía fijada para ella.', 'Eine Änderung muss die Regel benennen und die Änderung angeben, ob sie etwas zur Regel hinzufügt, daraus streicht oder sie ändert. Jede Art von Regel kann nur auf dem dafür vorgesehenen Weg geändert werden.', 'Bir değişiklik kuralı adlandırmalı ve değişikliği belirtmelidir: kurala ekleme mi, kuraldan silme mi, yoksa değiştirme mi. Her kural türü yalnızca kendisi için belirlenen yoldan değiştirilebilir.']),
        rule('86', ['Changes to the racing rules', 'Изменения гоночных правил', 'Cambios a las reglas de regata', 'Änderungen an den Wettfahrtregeln', 'Yarış kurallarının değiştirilmesi'], ['National prescriptions may change a racing rule, but not the Definitions, Part 2, Part 7 or a list of protected rules. The notice of race or sailing instructions may change a rule too, but not those or rules 4, 76.1, 76.2(a) and Appendix R. Class rules may change only rules 42, 49, 51 to 55 and 78.2.', 'Предписания национальной федерации могут менять гоночные правила, но не определения, части 2 и 7 и перечень защищённых правил. Положение или инструкция тоже могут менять правила, но не эти и не правила 4, 76.1, 76.2(a) и приложение R. Правила класса могут менять только правила 42, 49, 51–55 и 78.2.', 'Las prescripciones nacionales pueden cambiar una regla de regata, pero no las Definiciones, la Parte 2, la Parte 7 ni una lista de reglas protegidas. El anuncio de regata o las instrucciones de regata también pueden cambiar una regla, pero no esas ni las reglas 4, 76.1, 76.2(a) y el Apéndice R. Las reglas de clase solo pueden cambiar las reglas 42, 49, 51 a 55 y 78.2.', 'Nationale Vorschriften dürfen eine Wettfahrtregel ändern, aber nicht die Definitionen, Teil 2, Teil 7 oder eine Liste geschützter Regeln. Auch die Ausschreibung oder die Segelanweisungen dürfen eine Regel ändern, aber nicht diese und nicht die Regeln 4, 76.1, 76.2(a) und Anhang R. Klassenregeln dürfen nur die Regeln 42, 49, 51 bis 55 und 78.2 ändern.', 'Ulusal düzenlemeler bir yarış kuralını değiştirebilir; ancak Tanımları, 2. Bölümü, 7. Bölümü ya da korunan kurallar listesini değiştiremez. Yarış ilanı ya da yelken talimatları da bir kuralı değiştirebilir; ancak bunları ya da kural 4, 76.1, 76.2(a) ve Ek R’yi değiştiremez. Sınıf kuralları yalnızca kural 42, 49 ile 55 arası ve 78.2’yi değiştirebilir.']),
        rule('87', ['Changes to class rules', 'Изменения правил класса', 'Cambios a las reglas de clase', 'Änderungen an Klassenregeln', 'Sınıf kurallarının değiştirilmesi'], ['The notice of race may change a class rule only if the class rules allow it or the class association’s written permission is posted on the official notice board.', 'Положение может изменить правило класса, только если это позволяют правила класса или на официальной доске вывешено письменное разрешение классовой ассоциации.', 'El anuncio de regata solo puede cambiar una regla de clase si las reglas de clase lo permiten o si el permiso escrito de la asociación de clase está expuesto en el tablón oficial de avisos.', 'Die Ausschreibung darf eine Klassenregel nur ändern, wenn die Klassenregeln es erlauben oder die schriftliche Erlaubnis der Klassenvereinigung am offiziellen Anschlagbrett aushängt.', 'Yarış ilanı, bir sınıf kuralını yalnızca sınıf kuralları izin veriyorsa ya da sınıf birliğinin yazılı izni resmî ilan panosunda yayımlanmışsa değiştirebilir.']),
        rule('88', ['National prescriptions', 'Предписания национальной федерации', 'Prescripciones nacionales', 'Nationale Vorschriften', 'Ulusal düzenlemeler'], ['The prescriptions that apply are those of the national authority the organisers are associated with. The notice of race or sailing instructions may change them, unless that authority has restricted this with World Sailing’s approval.', 'Действуют предписания федерации, с которой связан организатор. Положение или инструкция могут их менять, если федерация с одобрения World Sailing этого не ограничила.', 'Las prescripciones que se aplican son las de la autoridad nacional a la que están asociados los organizadores. El anuncio de regata o las instrucciones de regata pueden cambiarlas, salvo que esa autoridad lo haya restringido con la aprobación de World Sailing.', 'Es gelten die Vorschriften der nationalen Vereinigung, der die Veranstalter angehören. Die Ausschreibung oder die Segelanweisungen dürfen sie ändern, es sei denn, diese Vereinigung hat das mit Zustimmung von World Sailing eingeschränkt.', 'Geçerli olanlar, organizatörlerin bağlı olduğu ulusal otoritenin düzenlemeleridir. Yarış ilanı ya da yelken talimatları, o otorite World Sailing’in onayıyla bunu kısıtlamadıkça, bunları değiştirebilir.']),
        rule('89', ['Organizing authority; notice of race; appointment of race officials', 'Организатор; положение; назначение судей', 'Autoridad organizadora; anuncio de regata; nombramiento de oficiales de regata', 'Veranstalter; Ausschreibung; Ernennung der Wettfahrtoffiziellen', 'Organizatör otorite; yarış ilanı; yarış görevlilerinin atanması'], ['An event is organised by World Sailing, a national authority, an affiliated club or organisation, or a class association or other body on set conditions. The organisers publish the notice of race and appoint the race committee and, when appropriate, protest and technical committees and umpires.', 'Соревнование организует World Sailing, национальная федерация, аффилированный клуб или организация либо классовая ассоциация или другой орган на установленных условиях. Организатор публикует положение и назначает гоночный комитет, а при необходимости протестовый и технический комитеты и ампайров.', 'Un evento lo organiza World Sailing, una autoridad nacional, un club u organización afiliados, o una asociación de clase u otro organismo en condiciones establecidas. Los organizadores publican el anuncio de regata y nombran al comité de regatas y, cuando procede, a los comités de protestas y técnico y a los árbitros.', 'Eine Veranstaltung wird organisiert von World Sailing, einer nationalen Vereinigung, einem angeschlossenen Club oder einer angeschlossenen Organisation oder einer Klassenvereinigung oder einer anderen Stelle unter festgelegten Bedingungen. Die Veranstalter veröffentlichen die Ausschreibung und ernennen die Wettfahrtleitung und, wenn angebracht, Protest- und Technische Komitees und Umpires.', 'Bir etkinliği World Sailing, bir ulusal otorite, bağlı bir kulüp ya da kuruluş ya da belirli koşullarla bir sınıf birliği veya başka bir kurum düzenler. Organizatörler yarış ilanını yayımlar ve yarış komitesini, uygunsa protesto ve teknik komiteleri ve hakemleri atar.']),
        rule('90', ['Race committee; sailing instructions; scoring', 'Гоночный комитет; инструкция; подсчёт очков', 'Comité de regatas; instrucciones de regata; puntuación', 'Wettfahrtleitung; Segelanweisungen; Wertung', 'Yarış komitesi; yelken talimatları; puanlama'], ['The race committee runs the races as directed and as the rules require, publishes the sailing instructions and scores by Appendix A unless another system is set. A race is scored if it isn’t abandoned and one boat sails the course within any time limit, and scoring errors it finds are corrected.', 'Гоночный комитет проводит гонки по указаниям организатора и правилам, публикует гоночную инструкцию и считает очки по приложению A, если не установлена другая система. Гонка идёт в зачёт, если не прекращена и хотя бы одна лодка прошла дистанцию в контрольное время; найденные ошибки подсчёта исправляются.', 'El comité de regatas dirige las regatas como se le indica y como exigen las reglas, publica las instrucciones de regata y puntúa según el Apéndice A, salvo que se fije otro sistema. Una regata se puntúa si no se anula y un barco navega el recorrido dentro de cualquier tiempo límite, y los errores de puntuación que detecta se corrigen.', 'Die Wettfahrtleitung führt die Wettfahrten wie angewiesen und wie die Regeln es verlangen durch, veröffentlicht die Segelanweisungen und wertet nach Anhang A, sofern kein anderes System festgelegt ist. Eine Wettfahrt wird gewertet, wenn sie nicht abgebrochen wird und ein Boot die Bahn innerhalb einer Zeitgrenze segelt, und Wertungsfehler, die sie findet, werden korrigiert.', 'Yarış komitesi yarışları yönergelere ve kuralların gerektirdiği biçimde yürütür, yelken talimatlarını yayımlar ve başka bir sistem belirlenmedikçe Ek A’ya göre puanlar. Bir yarış, iptal edilmediyse ve bir tekne süre sınırı içinde parkuru tamamladıysa puanlanır; komitenin bulduğu puanlama hataları düzeltilir.']),
        rule('91', ['Protest committee', 'Протестовый комитет', 'Comité de protestas', 'Protestkomitee', 'Protesto komitesi'], ['A committee appointed by the organisers or the race committee, an international jury, or a committee appointed by the national authority under rule 71.3(c).', 'Комитет, назначенный организатором или гоночным комитетом, международное жюри либо комитет, назначенный национальной федерацией по правилу 71.3(c).', 'Un comité nombrado por los organizadores o por el comité de regatas, un jurado internacional, o un comité nombrado por la autoridad nacional conforme a la regla 71.3(c).', 'Ein von den Veranstaltern oder der Wettfahrtleitung ernanntes Komitee, eine internationale Jury oder ein von der nationalen Vereinigung nach Regel 71.3(c) ernanntes Komitee.', 'Organizatörler ya da yarış komitesi tarafından atanan bir komite, uluslararası bir jüri ya da ulusal otorite tarafından kural 71.3(c) uyarınca atanan bir komite.']),
        rule('92', ['Technical committee', 'Технический комитет', 'Comité técnico', 'Technisches Komitee', 'Teknik komite'], ['At least one member, appointed by the organisers, the race committee or as World Sailing regulations prescribe. It carries out equipment inspection and event measurement.', 'Не меньше одного человека, назначенного организатором, гоночным комитетом или по регламентам World Sailing. Проводит проверку снаряжения и обмер на соревновании.', 'Al menos un miembro, nombrado por los organizadores, por el comité de regatas o según prescriban los reglamentos de World Sailing. Lleva a cabo la inspección de equipo y la medición del evento.', 'Mindestens ein Mitglied, ernannt von den Veranstaltern, der Wettfahrtleitung oder wie die Bestimmungen von World Sailing es vorschreiben. Es führt die Ausrüstungskontrolle und die Vermessung der Veranstaltung durch.', 'Organizatörler, yarış komitesi ya da World Sailing düzenlemelerinin öngördüğü biçimde atanan en az bir üye. Donanım denetimini ve etkinlik ölçümünü yapar.']),
      ] }] },

    { id: 'appendices', chip: t('Appendices', 'Приложения', 'Apéndices', 'Anhänge', 'Ekler'), title: t('Appendices', 'Приложения', 'Apéndices', 'Anhänge', 'Ekler'),
      intro: t('Rules for particular kinds of racing and procedures. An appendix that applies takes precedence over any part of the rules it conflicts with.', 'Правила для отдельных видов гонок и процедур. Действующее приложение важнее части правил, с которой расходится.', 'Reglas para tipos concretos de regata y procedimientos. Un apéndice que se aplica prevalece sobre cualquier parte de las reglas con la que entre en conflicto.', 'Regeln für besondere Arten von Wettfahrten und Verfahren. Ein Anhang, der gilt, hat Vorrang vor jedem Teil der Regeln, mit dem er in Konflikt steht.', 'Belirli yarış türleri ve prosedürler için kurallar. Uygulanan bir ek, çeliştiği kuralların her bölümüne göre önceliklidir.'),
      sections: [{ entries: [
        app('A', ['Scoring', 'Подсчёт очков', 'Puntuación', 'Wertung', 'Puanlama'], ['The Low Point System: first place scores 1, second 2 and so on, a boat’s worst race is excluded unless the notice of race says otherwise, and the lowest total wins. A boat that didn’t sail the course, retired or was disqualified scores one more than the number of boats entered. Ties go to the better scores, then to the last race. The codes: DNC, DNS, OCS, ZFP, UFD, BFD, SCP, NSC, DNF, RET, DSQ, DNE, RDG and DPI.', 'Линейная система: за первое место 1 очко, за второе 2 и так далее, худшая гонка отбрасывается, если положение не говорит иного, побеждает наименьшая сумма. Лодка, не прошедшая дистанцию, вышедшая из гонки или дисквалифицированная, получает на одно очко больше числа заявленных лодок. При равенстве решают лучшие результаты, затем последняя гонка. Обозначения: DNC, DNS, OCS, ZFP, UFD, BFD, SCP, NSC, DNF, RET, DSQ, DNE, RDG и DPI.', 'El Sistema de Puntuación Baja: el primer puesto puntúa 1, el segundo 2 y así sucesivamente, la peor regata de un barco se excluye salvo que el anuncio de regata diga otra cosa, y gana el total más bajo. Un barco que no navegó el recorrido, se retiró o fue descalificado puntúa uno más que el número de barcos inscritos. Los empates se resuelven por las mejores puntuaciones y luego por la última regata. Los códigos: DNC, DNS, OCS, ZFP, UFD, BFD, SCP, NSC, DNF, RET, DSQ, DNE, RDG y DPI.', 'Das Low-Point-System: Der erste Platz erhält 1 Punkt, der zweite 2 und so weiter, die schlechteste Wettfahrt eines Boots wird gestrichen, sofern die Ausschreibung nichts anderes sagt, und die niedrigste Summe gewinnt. Ein Boot, das die Bahn nicht gesegelt ist, aufgegeben hat oder disqualifiziert wurde, erhält einen Punkt mehr als die Zahl der gemeldeten Boote. Gleichstände werden zugunsten der besseren Ergebnisse entschieden, dann der letzten Wettfahrt. Die Codes: DNC, DNS, OCS, ZFP, UFD, BFD, SCP, NSC, DNF, RET, DSQ, DNE, RDG und DPI.', 'Düşük Puan Sistemi: birinci yer 1, ikinci 2 puan alır ve böyle sürer; yarış ilanı başka türlü söylemedikçe teknenin en kötü yarışı çıkarılır ve en düşük toplam kazanır. Parkuru tamamlamayan, çekilen ya da diskalifiye edilen tekne, kayıtlı tekne sayısından bir fazla puan alır. Beraberlikte daha iyi puanlar, sonra son yarış belirleyici olur. Kodlar: DNC, DNS, OCS, ZFP, UFD, BFD, SCP, NSC, DNF, RET, DSQ, DNE, RDG ve DPI.']),
        app('B', ['Windsurfing fleet racing rules', 'Правила флотовых гонок на виндсёрфинге', 'Reglas de regata de windsurf en flota', 'Wettfahrtregeln für Windsurf-Flottenrennen', 'Rüzgâr sörfü filo yarış kuralları'], ['How the rules change for windsurfing fleet races, marathon races included.', 'Как меняются правила для флотовых гонок на виндсёрфинге, включая марафоны.', 'Cómo cambian las reglas en las regatas de flota de windsurf, incluidas las de maratón.', 'Wie sich die Regeln für Windsurf-Flottenwettfahrten ändern, einschließlich Marathonrennen.', 'Maraton yarışları dahil, rüzgâr sörfü filo yarışlarında kuralların nasıl değiştiği.']),
        app('C', ['Match racing rules', 'Правила матчевых гонок', 'Reglas de regatas de match race', 'Wettfahrtregeln für Match Racing', 'Eşleşme yarışı kuralları'], ['How the rules change for match races, which are umpired unless the notice of race or sailing instructions say otherwise.', 'Как меняются правила для матчевых гонок, которые судят ампайры, если положение или инструкция не говорят иного.', 'Cómo cambian las reglas en los match races, que cuentan con árbitros salvo que el anuncio de regata o las instrucciones de regata digan otra cosa.', 'Wie sich die Regeln für Match Races ändern, die von Umpires geleitet werden, sofern Ausschreibung oder Segelanweisungen nichts anderes sagen.', 'Yarış ilanı ya da yelken talimatları aksini söylemedikçe hakemli olan eşleşme yarışlarında kuralların nasıl değiştiği.']),
        app('D', ['Team racing rules', 'Правила командных гонок', 'Reglas de regatas por equipos', 'Wettfahrtregeln für Team Racing', 'Takım yarışı kuralları'], ['How the rules change for team races. Among other things, the zone shrinks to two hull lengths.', 'Как меняются правила для командных гонок. Среди прочего, зона уменьшается до двух корпусов.', 'Cómo cambian las reglas en las regatas por equipos. Entre otras cosas, la zona se reduce a dos esloras de casco.', 'Wie sich die Regeln für Team Races ändern. Unter anderem schrumpft die Zone auf zwei Rumpflängen.', 'Takım yarışlarında kuralların nasıl değiştiği. Diğer şeylerin yanı sıra bölge iki gövde boyuna küçülür.']),
        app('E', ['Radio sailing racing rules', 'Правила гонок радиоуправляемых яхт', 'Reglas de regatas de vela radiocontrol', 'Wettfahrtregeln für Funkregatten', 'Telsiz kumandalı yelken yarış kuralları'], ['How the rules change for radio-controlled boats. Among other things, the zone grows to four hull lengths.', 'Как меняются правила для радиоуправляемых яхт. Среди прочего, зона увеличивается до четырёх корпусов.', 'Cómo cambian las reglas para barcos radiocontrolados. Entre otras cosas, la zona crece a cuatro esloras de casco.', 'Wie sich die Regeln für funkferngesteuerte Boote ändern. Unter anderem wächst die Zone auf vier Rumpflängen.', 'Telsiz kumandalı teknelerde kuralların nasıl değiştiği. Diğer şeylerin yanı sıra bölge dört gövde boyuna büyür.']),
        app('F', ['Kiteboarding racing rules', 'Правила гонок на кайтборде', 'Reglas de regatas de kiteboard', 'Wettfahrtregeln für Kiteboarding', 'Kitesurf yarış kuralları'], ['How the rules and definitions change for kiteboard course races.', 'Как меняются правила и определения для гонок на кайтборде.', 'Cómo cambian las reglas y las definiciones en las regatas de recorrido de kiteboard.', 'Wie sich die Regeln und Definitionen für Kiteboard-Kurswettfahrten ändern.', 'Kitesurf parkur yarışlarında kuralların ve tanımların nasıl değiştiği.']),
        app('G', ['Identification on sails', 'Опознавательные знаки на парусах', 'Identificación en las velas', 'Kennzeichnung auf den Segeln', 'Yelkenlerde tanıtma'], ['The class insignia, national letters and sail numbers a boat carries, and where and how large they go.', 'Какие эмблема класса, национальные буквы и номера несёт лодка, где они расположены и какого размера.', 'El emblema de clase, las letras nacionales y los números de vela que lleva un barco, y dónde y de qué tamaño van.', 'Die Klassenzeichen, Nationalitätszeichen und Segelnummern, die ein Boot führt, und wo und wie groß sie sein müssen.', 'Teknenin taşıdığı sınıf amblemi, ulusal harfler ve yelken numaraları, ve bunların nereye ve ne büyüklükte konacağı.']),
        app('H', ['Weighing clothing and equipment', 'Взвешивание одежды и снаряжения', 'Pesaje de ropa y equipo', 'Kleidung und Ausrüstung wiegen', 'Giysi ve donanımın tartılması'], ['How rule 50 is checked: the items are soaked in fresh water, drained on a rack for one minute and weighed.', 'Как проверяют правило 50: вещи замачивают в пресной воде, дают стечь на вешалке одну минуту и взвешивают.', 'Cómo se comprueba la regla 50: los artículos se empapan en agua dulce, se escurren en un soporte durante un minuto y se pesan.', 'Wie Regel 50 geprüft wird: Die Teile werden in Süßwasser getränkt, eine Minute auf einem Gestell abgetropft und gewogen.', 'Kural 50’nin nasıl denetlendiği: parçalar tatlı suda ıslatılır, bir dakika rafta süzülür ve tartılır.']),
        app('J', ['Notice of race and sailing instructions', 'Положение и гоночная инструкция', 'Anuncio de regata e instrucciones de regata', 'Ausschreibung und Segelanweisungen', 'Yarış ilanı ve yelken talimatları'], ['What these two documents must contain and what they may.', 'Что эти два документа обязаны содержать и что могут.', 'Lo que estos dos documentos deben contener y lo que pueden contener.', 'Was diese beiden Dokumente enthalten müssen und was sie enthalten dürfen.', 'Bu iki belgenin neleri içermesi gerektiği ve neleri içerebileceği.']),
        app('M', ['Recommendations for protest committees', 'Рекомендации протестовым комитетам', 'Recomendaciones para los comités de protestas', 'Empfehlungen für Protestkomitees', 'Protesto komiteleri için öneriler'], ['Advice, not requirements, on running a fair hearing from the first papers to the decision.', 'Советы, а не требования, как честно провести рассмотрение от первых документов до решения.', 'Consejos, no requisitos, para llevar una audiencia justa desde los primeros documentos hasta la decisión.', 'Ratschläge, keine Vorschriften, wie man eine faire Verhandlung von den ersten Unterlagen bis zur Entscheidung führt.', 'Gerekli kılınmayan; ilk belgelerden karara kadar adil bir duruşmanın nasıl yürütüleceğine dair tavsiyeler.']),
        app('N', ['International juries', 'Международные жюри', 'Jurados internacionales', 'Internationale Juries', 'Uluslararası jüriler'], ['At least five experienced members, most of them International Judges, and no more than two from one national authority (three in Groups M, N and Q). There is no appeal from their decisions.', 'Не меньше пяти опытных членов, большинство — международные судьи, не больше двух от одной федерации (трёх в группах M, N и Q). Их решения не обжалуются.', 'Al menos cinco miembros con experiencia, la mayoría de ellos Jueces Internacionales, y no más de dos de una misma autoridad nacional (tres en los Grupos M, N y Q). No hay apelación contra sus decisiones.', 'Mindestens fünf erfahrene Mitglieder, die meisten davon International Judges, und höchstens zwei aus einer nationalen Vereinigung (drei in den Gruppen M, N und Q). Gegen ihre Entscheidungen gibt es keine Berufung.', 'En az beş deneyimli üye, çoğu Uluslararası Hakem; aynı ulusal otoriteden en fazla ikisi (M, N ve Q Gruplarında üç). Kararlarına itiraz yolu yoktur.']),
        app('P', ['Special procedures for rule 42', 'Особые процедуры по правилу 42', 'Procedimientos especiales para la regla 42', 'Besondere Verfahren für Regel 42', 'Kural 42 için özel prosedürler'], ['Applies only if the event says so. Observers penalise a breach on the water with a sound signal and a yellow flag. First time, a Two-Turns Penalty; second time, she retires; a third time, she retires and the disqualification can’t be excluded.', 'Действует, только если это указано для соревнования. Наблюдатели наказывают прямо на воде звуковым сигналом и жёлтым флагом. В первый раз — два оборота, во второй — выход из гонки, в третий — выход из гонки и дисквалификация, которую нельзя исключить из зачёта.', 'Se aplica solo si el evento lo dice. Los observadores penalizan una infracción en el agua con una señal sonora y una bandera amarilla. La primera vez, una Penalización de Dos Giros; la segunda, se retira; la tercera, se retira y la descalificación no puede excluirse.', 'Gilt nur, wenn die Veranstaltung es sagt. Beobachter bestrafen einen Verstoß auf dem Wasser mit einem Schallsignal und einer gelben Flagge. Beim ersten Mal eine Zwei-Kringel-Strafe; beim zweiten Mal gibt es auf; beim dritten Mal gibt es auf und die Disqualifikation kann nicht gestrichen werden.', 'Yalnızca etkinlik öyle diyorsa uygulanır. Gözlemciler bir ihlali suda ses işareti ve sarı bayrakla cezalandırır. İlk seferde İki Dönüş Cezası; ikincisinde tekne çekilir; üçüncüsünde çekilir ve diskalifiye çıkarılamaz.']),
        app('R', ['Procedures for appeals and requests', 'Процедура апелляций и запросов', 'Procedimientos para apelaciones y solicitudes', 'Verfahren für Berufungen und Anfragen', 'İtirazlar ve talepler için prosedürler'], ['How to appeal to a national authority: the appeal goes in no later than seven days after receiving the protest committee’s written decision, with the reasons for it.', 'Как подать апелляцию в национальную федерацию: не позже семи дней после получения письменного решения протестового комитета, с указанием причин.', 'Cómo apelar ante una autoridad nacional: la apelación se presenta a más tardar siete días después de recibir la decisión escrita del comité de protestas, con los motivos de la apelación.', 'Wie man bei einer nationalen Vereinigung Berufung einlegt: Die Berufung geht spätestens sieben Tage nach Erhalt der schriftlichen Entscheidung des Protestkomitees ein, mit den Gründen dafür.', 'Ulusal otoriteye nasıl itiraz edilir: itiraz, protesto komitesinin yazılı kararı alındıktan en geç yedi gün sonra, gerekçeleriyle birlikte yapılır.']),
        app('S', ['Standard sailing instructions', 'Стандартная гоночная инструкция', 'Instrucciones de regata tipo', 'Standard-Segelanweisungen', 'Standart yelken talimatları'], ['A ready-made set of sailing instructions an event may use in place of its own, if the notice of race says so.', 'Готовая гоночная инструкция, которую соревнование может использовать вместо своей, если это указано в положении.', 'Un conjunto ya preparado de instrucciones de regata que un evento puede usar en lugar de las suyas, si el anuncio de regata lo dice.', 'Eine fertige Segelanweisung, die eine Veranstaltung anstelle einer eigenen verwenden darf, wenn die Ausschreibung es vorsieht.', 'Yarış ilanı öyle diyorsa, bir etkinliğin kendi yarış talimatı yerine kullanabileceği hazır bir yarış talimatı seti.']),
        app('T', ['Arbitration', 'Арбитраж', 'Arbitraje', 'Schiedsverfahren', 'Hakemlik'], ['Applies only if the event says so. Before a hearing an arbitrator gives an opinion on what the protest committee would likely decide, and a boat may take a Post-Race Penalty, a 30% scoring penalty, instead of going on to a hearing.', 'Действует, только если это указано для соревнования. До рассмотрения арбитр высказывает мнение о вероятном решении протестового комитета, и лодка может принять послегоночное наказание — штраф 30% очков — вместо рассмотрения.', 'Se aplica solo si el evento lo dice. Antes de una audiencia, un árbitro da una opinión sobre lo que probablemente decidiría el comité de protestas, y un barco puede aceptar una Penalización Posterior a la Regata, una penalización de puntuación del 30 %, en lugar de pasar a una audiencia.', 'Gilt nur, wenn die Veranstaltung es vorsieht. Vor einer Verhandlung gibt ein Schiedsrichter eine Einschätzung ab, wie das Protestkomitee wahrscheinlich entscheiden würde, und ein Boot kann eine Strafe nach der Wettfahrt (Post-Race Penalty) annehmen, eine Wertungsstrafe von 30 %, statt in die Verhandlung zu gehen.', 'Yalnızca etkinlik öyle diyorsa geçerlidir. Duruşmadan önce bir hakem, protesto komitesinin büyük olasılıkla ne karar vereceği konusunda görüş bildirir; tekne duruşmaya gitmek yerine %30’luk bir puanlama cezası olan Yarış Sonrası Ceza’yı kabul edebilir.']),
      ] }] },

    { id: 'signals', chip: t('Signals', 'Сигналы', 'Señales', 'Signale', 'Sinyaller'), title: t('Race signals', 'Гоночные сигналы', 'Señales de regata', 'Wettfahrtsignale', 'Yarış sinyalleri'),
      intro: t('What the race committee’s flags mean. Shown over a class flag, a signal applies to that class only.', 'Что значат флаги гоночного комитета. Сигнал над флагом класса относится только к этому классу.', 'Qué significan las banderas del comité de regatas. Mostrada sobre una bandera de clase, una señal se aplica solo a esa clase.', 'Was die Flaggen der Wettfahrtleitung bedeuten. Über einer Klassenflagge gezeigt, gilt ein Signal nur für diese Klasse.', 'Yarış komitesinin bayraklarının anlamı. Bir sınıf bayrağının üzerinde gösterilen sinyal yalnızca o sınıf için geçerlidir.'),
      sections: [
        sec('signals-postponement', ['Postponement', 'Откладывание', 'Aplazamiento', 'Verschiebung', 'Erteleme'], null, [
          sig('ap', 'AP', ['Answering pennant', 'Ответный вымпел', 'Gallardete de respuesta', 'Antwortwimpel', 'Cevap flaması'], ['Races not started are postponed. Two sounds. The warning signal comes 1 minute after it is lowered, unless the race is postponed again or abandoned.', 'Не начатые гонки отложены. Два звука. Предупреждение — через 1 минуту после спуска, если гонку снова не отложат и не прекратят.', 'Se aplazan las regatas que no han salido. Dos señales sonoras. La señal de atención llega 1 minuto después de arriarlo, salvo que se aplace de nuevo o se anule la regata.', 'Noch nicht gestartete Wettfahrten sind verschoben. Zwei Signaltöne. Das Ankündigungssignal folgt 1 Minute nach dem Niederholen, sofern die Wettfahrt nicht erneut verschoben oder abgebrochen wird.', 'Başlamamış yarışlar ertelenir. İki ses sinyali. İndirildikten 1 dakika sonra uyarı sinyali verilir; yarış yeniden ertelenmedikçe ya da iptal edilmedikçe.']),
          sig('ap-h', 'AP/H', ['AP over H', 'AP над H', 'AP sobre H', 'AP über H', 'AP, H’nin üzerinde'], ['Races not started are postponed. Further signals ashore.', 'Не начатые гонки отложены. Дальнейшие сигналы — на берегу.', 'Se aplazan las regatas que no han salido. Más señales en tierra.', 'Noch nicht gestartete Wettfahrten sind verschoben. Weitere Signale an Land.', 'Başlamamış yarışlar ertelenir. Yeni sinyaller karada verilecek.']),
          sig('ap-a', 'AP/A', ['AP over A', 'AP над A', 'AP sobre A', 'AP über A', 'AP, A’nın üzerinde'], ['Races not started are postponed. No more racing today.', 'Не начатые гонки отложены. Сегодня гонок больше не будет.', 'Se aplazan las regatas que no han salido. No habrá más regatas hoy.', 'Noch nicht gestartete Wettfahrten sind verschoben. Heute findet keine Wettfahrt mehr statt.', 'Başlamamış yarışlar ertelenir. Bugün başka yarış yok.']),
          sig('ap-num', 'AP/1–9', ['AP over a numeral pennant', 'AP над цифровым вымпелом', 'AP sobre un gallardete numérico', 'AP über einem Zahlenwimpel', 'AP, bir sayı flamasının üzerinde'], ['Postponement of 1 to 9 hours from the scheduled starting time.', 'Откладывание на 1–9 часов от назначенного времени старта.', 'Aplazamiento de 1 a 9 horas desde la hora de salida programada.', 'Verschiebung um 1 bis 9 Stunden gegenüber der planmäßigen Startzeit.', 'Planlanan start saatinden itibaren 1 ila 9 saat erteleme.']),
        ]),
        sec('signals-abandonment', ['Abandonment', 'Прекращение', 'Anulación', 'Abbruch', 'İptal'], null, [
          sig('n', 'N', ['Flag N', 'Флаг N', 'Bandera N', 'Flagge N', 'N bayrağı'], ['All races in progress are abandoned. Return to the starting area. Three sounds. The warning signal comes 1 minute after it is lowered, unless the race is abandoned again or postponed.', 'Все идущие гонки прекращены. Вернитесь в район старта. Три звука. Предупреждение — через 1 минуту после спуска, если гонку снова не прекратят и не отложат.', 'Se anulan todas las regatas en curso. Vuelve a la zona de salida. Tres señales sonoras. La señal de atención llega 1 minuto después de arriarla, salvo que se anule de nuevo o se aplace la regata.', 'Alle laufenden Wettfahrten sind abgebrochen. Zurück zum Startgebiet. Drei Signaltöne. Das Ankündigungssignal folgt 1 Minute nach dem Niederholen, sofern die Wettfahrt nicht erneut abgebrochen oder verschoben wird.', 'Devam eden tüm yarışlar iptal edildi. Start alanına dön. Üç ses sinyali. İndirildikten 1 dakika sonra uyarı sinyali verilir; yarış yeniden iptal edilmedikçe ya da ertelenmedikçe.']),
          sig('n-h', 'N/H', ['N over H', 'N над H', 'N sobre H', 'N über H', 'N, H’nin üzerinde'], ['All races in progress are abandoned. Further signals ashore.', 'Все идущие гонки прекращены. Дальнейшие сигналы — на берегу.', 'Se anulan todas las regatas en curso. Más señales en tierra.', 'Alle laufenden Wettfahrten sind abgebrochen. Weitere Signale an Land.', 'Devam eden tüm yarışlar iptal edildi. Yeni sinyaller karada verilecek.']),
          sig('n-a', 'N/A', ['N over A', 'N над A', 'N sobre A', 'N über A', 'N, A’nın üzerinde'], ['All races in progress are abandoned. No more racing today.', 'Все идущие гонки прекращены. Сегодня гонок больше не будет.', 'Se anulan todas las regatas en curso. No habrá más regatas hoy.', 'Alle laufenden Wettfahrten sind abgebrochen. Heute findet keine Wettfahrt mehr statt.', 'Devam eden tüm yarışlar iptal edildi. Bugün başka yarış yok.']),
        ]),
        sec('signals-start', ['Preparatory signals', 'Подготовительные сигналы', 'Señales de preparación', 'Vorbereitungssignale', 'Hazırlık sinyalleri'], null, [
          sig('p', 'P', ['Flag P', 'Флаг P', 'Bandera P', 'Flagge P', 'P bayrağı'], ['The preparatory signal.', 'Подготовительный сигнал.', 'La señal de preparación.', 'Das Vorbereitungssignal.', 'Hazırlık sinyali.']),
          sig('i', 'I', ['Flag I', 'Флаг I', 'Bandera I', 'Flagge I', 'I bayrağı'], ['Rule 30.1 is in effect.', 'Действует правило 30.1.', 'Está en vigor la regla 30.1.', 'Regel 30.1 gilt.', 'Kural 30.1 yürürlükte.']),
          sig('z', 'Z', ['Flag Z', 'Флаг Z', 'Bandera Z', 'Flagge Z', 'Z bayrağı'], ['Rule 30.2 is in effect: a 20% scoring penalty.', 'Действует правило 30.2: штраф 20% очков.', 'Está en vigor la regla 30.2: penalización del 20 % en la puntuación.', 'Regel 30.2 gilt: eine Wertungsstrafe von 20 %.', 'Kural 30.2 yürürlükte: %20’lik puanlama cezası.']),
          sig('u', 'U', ['Flag U', 'Флаг U', 'Bandera U', 'Flagge U', 'U bayrağı'], ['Rule 30.3 is in effect: disqualification unless the race is restarted or resailed.', 'Действует правило 30.3: дисквалификация, если гонку не перестартуют и не проведут заново.', 'Está en vigor la regla 30.3: descalificación, salvo que se repita la salida o se vuelva a navegar la regata.', 'Regel 30.3 gilt: Disqualifikation, außer die Wettfahrt wird neu gestartet oder wiederholt.', 'Kural 30.3 yürürlükte: yarış yeniden başlatılmadıkça ya da yeniden yapılmadıkça diskalifiye.']),
          sig('black', '', ['Black flag', 'Чёрный флаг', 'Bandera negra', 'Schwarze Flagge', 'Siyah bayrak'], ['Rule 30.4 is in effect: disqualification, even if the race is restarted or resailed.', 'Действует правило 30.4: дисквалификация, даже если гонку перестартуют или проведут заново.', 'Está en vigor la regla 30.4: descalificación, aunque se repita la salida o se vuelva a navegar la regata.', 'Regel 30.4 gilt: Disqualifikation, auch wenn die Wettfahrt neu gestartet oder wiederholt wird.', 'Kural 30.4 yürürlükte: yarış yeniden başlatılsa ya da yeniden yapılsa bile diskalifiye.']),
        ]),
        sec('signals-recall', ['Recalls', 'Отзывы', 'Llamadas', 'Rückrufe', 'Geri çağırmalar'], null, [
          sig('x', 'X', ['Flag X', 'Флаг X', 'Bandera X', 'Flagge X', 'X bayrağı'], ['Individual recall, with one sound.', 'Индивидуальный отзыв, один звук.', 'Llamada individual, con una señal acústica.', 'Einzelrückruf, mit einem Signalton.', 'Bireysel geri çağırma, bir ses sinyaliyle.']),
          sig('first-sub', '1st', ['First Substitute', 'Первый заменяющий', 'Primer Repetidor', 'Erster Ersatzwimpel', 'Birinci Vekil'], ['General recall, with two sounds. The warning signal comes 1 minute after it is lowered.', 'Общий отзыв, два звука. Предупреждение — через 1 минуту после спуска.', 'Llamada general, con dos señales acústicas. La señal de atención se da 1 minuto después de arriarla.', 'Allgemeiner Rückruf, mit zwei Signaltönen. Das Ankündigungssignal folgt 1 Minute nach dem Niederholen.', 'Genel geri çağırma, iki ses sinyaliyle. İndirildikten 1 dakika sonra uyarı sinyali verilir.']),
        ]),
        sec('signals-course', ['The course', 'Дистанция', 'El recorrido', 'Die Bahn', 'Parkur'], null, [
          sig('s', 'S', ['Flag S', 'Флаг S', 'Bandera S', 'Flagge S', 'S bayrağı'], ['The course has been shortened, with two sounds. Rule 32.2 is in effect.', 'Дистанция сокращена, два звука. Действует правило 32.2.', 'Se ha acortado el recorrido, con dos señales acústicas. Está en vigor la regla 32.2.', 'Die Bahn wurde verkürzt, mit zwei Signaltönen. Regel 32.2 gilt.', 'Parkur kısaltıldı, iki ses sinyaliyle. Kural 32.2 yürürlükte.']),
          sig('c', 'C', ['Flag C', 'Флаг C', 'Bandera C', 'Flagge C', 'C bayrağı'], ['The position of the next mark has been changed, with repetitive sounds: to starboard, to port, to shorten the leg or to lengthen it.', 'Положение следующего знака изменено, повторяющиеся звуки: вправо, влево, отрезок короче или длиннее.', 'Se ha cambiado la posición de la siguiente baliza, con señales acústicas repetidas: a estribor, a babor, para acortar el tramo o para alargarlo.', 'Die Position der nächsten Bahnmarke wurde geändert, mit wiederholten Signaltönen: nach Steuerbord, nach Backbord, den Schenkel zu verkürzen oder ihn zu verlängern.', 'Bir sonraki şamandıranın yeri değişti, tekrarlanan ses sinyalleriyle: sancağa, iskeleye, ayağı kısaltmak ya da uzatmak için.']),
          sig('m', 'M', ['Flag M', 'Флаг M', 'Bandera M', 'Flagge M', 'M bayrağı'], ['The object showing this flag replaces a missing mark.', 'Предмет с этим флагом заменяет пропавший знак.', 'El objeto que muestra esta bandera sustituye a una baliza que falta.', 'Das Objekt, das diese Flagge zeigt, ersetzt eine fehlende Bahnmarke.', 'Bu bayrağı taşıyan nesne eksik bir şamandıranın yerini tutar.']),
        ]),
        sec('signals-other', ['Other signals', 'Другие сигналы', 'Otras señales', 'Weitere Signale', 'Diğer sinyaller'], null, [
          sig('l', 'L', ['Flag L', 'Флаг L', 'Bandera L', 'Flagge L', 'L bayrağı'], ['Ashore: a notice to competitors has been posted. Afloat: come within hail or follow this vessel.', 'На берегу: вывешено сообщение для гонщиков. На воде: подойдите на расстояние оклика или следуйте за этим судном.', 'En tierra: se ha publicado un aviso para los participantes. En el agua: acércate a distancia de voz o sigue a este barco.', 'An Land: Eine Mitteilung an die Teilnehmer wurde ausgehängt. Auf dem Wasser: in Rufweite kommen oder diesem Fahrzeug folgen.', 'Karada: yarışçılara bir bildirim asıldı. Denizde: ses mesafesine gel ya da bu tekneyi izle.']),
          sig('y', 'Y', ['Flag Y', 'Флаг Y', 'Bandera Y', 'Flagge Y', 'Y bayrağı'], ['Wear a personal flotation device (rule 40), with one sound.', 'Наденьте спасательный жилет (правило 40), один звук.', 'Lleva puesto un dispositivo personal de flotación (regla 40), con una señal acústica.', 'Eine persönliche Schwimmhilfe tragen (Regel 40), mit einem Signalton.', 'Can yeleği giy (kural 40), bir ses sinyaliyle.']),
          sig('v', 'V', ['Flag V', 'Флаг V', 'Bandera V', 'Flagge V', 'V bayrağı'], ['Monitor the communication channel for safety instructions (rule 37), with one sound.', 'Слушайте канал связи для указаний по безопасности (правило 37), один звук.', 'Escucha el canal de comunicaciones por si hay instrucciones de seguridad (regla 37), con una señal acústica.', 'Den Kommunikationskanal auf Sicherheitsanweisungen abhören (Regel 37), mit einem Signalton.', 'Emniyet talimatları için haberleşme kanalını dinle (kural 37), bir ses sinyaliyle.']),
          sig('orange', '', ['Orange flag', 'Оранжевый флаг', 'Bandera naranja', 'Orange Flagge', 'Turuncu bayrak'], ['The staff showing this flag is one end of the starting line. No sound.', 'Шест с этим флагом — один конец стартовой линии. Без звука.', 'El mástil que muestra esta bandera es uno de los extremos de la línea de salida. Sin señal acústica.', 'Der Stab mit dieser Flagge ist ein Ende der Startlinie. Kein Signalton.', 'Bu bayrağı taşıyan direk start hattının bir ucudur. Ses sinyali yok.']),
          sig('blue', '', ['Blue flag', 'Синий флаг', 'Bandera azul', 'Blaue Flagge', 'Mavi bayrak'], ['The staff showing this flag is one end of the finishing line. No sound.', 'Шест с этим флагом — один конец финишной линии. Без звука.', 'El mástil que muestra esta bandera es uno de los extremos de la línea de llegada. Sin señal acústica.', 'Der Stab mit dieser Flagge ist ein Ende der Ziellinie. Kein Signalton.', 'Bu bayrağı taşıyan direk bitiş hattının bir ucudur. Ses sinyali yok.']),
        ]),
      ] },
  ];
}
